import * as THREE from 'three';
import { FPSPlayer } from './Player';
import { GameConfig } from './Config';

/**
 * Movement state produced by InputManager, consumed by PlayerController.
 * Decouples input reading from physics simulation.
 */
export interface MovementState {
    forward: boolean;
    backward: boolean;
    left: boolean;
    right: boolean;
    sprinting: boolean;
}

/**
 * Minimal interface for the controls object needed by PlayerController.
 * Avoids importing the full PointerLockWrapper type.
 */
export interface PlayerControls {
    object: { position: THREE.Vector3 };
    moveRight(distance: number): void;
    moveForward(distance: number): void;
}

/**
 * Minimal interface for the audio engine needed by PlayerController.
 * Only the teleport sound is used here.
 */
interface PlayerAudioEngine {
    playTeleportSound(): void;
}

/** Reusable vector for level center to avoid per-frame allocation */
const LEVEL_CENTER = new THREE.Vector3(0, 0, 0);

/**
 * PlayerController owns the player's physics simulation:
 * velocity, direction, delta-time integration, and boundary enforcement.
 *
 * It receives a MovementState from InputManager each frame and applies
 * movement to the controls object.
 */
export class PlayerController {
    private readonly player: FPSPlayer;
    private readonly velocity: THREE.Vector3;
    private readonly direction: THREE.Vector3;

    constructor(allowMovement = true) {
        this.player = new FPSPlayer(allowMovement);
        this.velocity = new THREE.Vector3();
        this.direction = new THREE.Vector3();
    }

    /**
     * Returns the player's eye height for camera positioning.
     */
    getHeight(): number {
        return this.player.height();
    }

    /**
     * Returns whether the player is allowed to move.
     */
    canMove(): boolean {
        return this.player.canMove();
    }

    /**
     * Updates the player's position based on movement state and delta time.
     *
     * @param delta - Time elapsed since last frame in seconds
     * @param movementState - Current movement input state
     * @param controls - The pointer lock controls to move
     */
    update(delta: number, movementState: MovementState, controls: PlayerControls): void {
        if (!this.player.canMove() || !controls) return;

        const moveSpeed = this.player.speed(movementState.sprinting);
        this.velocity.x -= this.velocity.x * moveSpeed * delta;
        this.velocity.z -= this.velocity.z * moveSpeed * delta;

        this.direction.z = Number(movementState.forward) - Number(movementState.backward);
        this.direction.x = Number(movementState.right) - Number(movementState.left);
        this.direction.normalize();

        if (movementState.left || movementState.right) {
            this.velocity.x -= this.direction.x * 1.0 * delta;
        }
        controls.moveRight(-this.velocity.x * delta);

        if (movementState.forward || movementState.backward) {
            this.velocity.z -= this.direction.z * 1.0 * delta;
        }
        controls.moveForward(-this.velocity.z * delta);

        // Compensate gravity — keep player on the ground
        controls.object.position.y = 0;
    }

    /**
     * Teleports the player back to the level center if they have wandered too far.
     *
     * @param controls - The pointer lock controls containing the player position
     * @param audioEngine - Audio engine to play the teleport sound effect
     */
    teleportIfTooFar(controls: PlayerControls, audioEngine: PlayerAudioEngine): void {
        const playerPosition = controls.object.position;

        if (playerPosition.distanceTo(LEVEL_CENTER) > GameConfig.MAX_DISTANCE_FROM_CENTER) {
            playerPosition.set(LEVEL_CENTER.x, LEVEL_CENTER.y, LEVEL_CENTER.z);
            audioEngine.playTeleportSound();
        }
    }
}
