import * as THREE from 'three';
import { Target } from './Target';
import { Utils } from './utils/Utils';
import { GameConfig } from './Config';

/**
 * Callback interface for statistics events triggered by target lifecycle.
 * Decouples TargetManager from the Statistics class.
 */
export interface TargetStatisticsCallbacks {
    startTargetTracking(): void;
    startTargetMetrics(
        targetPosition: THREE.Vector3,
        cameraPosition: THREE.Vector3,
        initialAngleDeg: number,
        targetRadius: number,
    ): void;
}

/**
 * TargetManager owns the target lifecycle: creation, raycasting,
 * lerp animation, ring color updates, and mesh caching.
 *
 * It does NOT own game-level orchestration (hit/miss scoring, audio,
 * overshoot/undershoot analysis). Those remain in Main, which calls
 * TargetManager's primitives.
 */
export class TargetManager {
    private target: Target | null;
    private targetMesh: THREE.Mesh | null;
    private targetRingMesh: THREE.Mesh | null;

    private readonly raycaster: THREE.Raycaster;
    private readonly raycastOrigin: THREE.Vector2;

    /** Cached raycast result from the last checkHover() call */
    private lastRaycastIntersects: THREE.Intersection[];

    private isLerping: boolean;
    private isTargetReady: boolean;
    private lerpStartTime: number;
    private readonly lerpStartPosition: THREE.Vector3;
    private readonly lerpTargetPosition: THREE.Vector3;
    private targetUpdateDirection: number;

    constructor() {
        this.target = null;
        this.targetMesh = null;
        this.targetRingMesh = null;

        this.raycaster = new THREE.Raycaster(
            new THREE.Vector3(),
            new THREE.Vector3(0, -1, 0),
            0,
            1000,
        );
        this.raycastOrigin = new THREE.Vector2(0, 0);
        this.lastRaycastIntersects = [];

        this.isLerping = false;
        this.isTargetReady = false;
        this.lerpStartTime = 0;
        this.lerpStartPosition = new THREE.Vector3();
        this.lerpTargetPosition = new THREE.Vector3();
        this.targetUpdateDirection = 0;
    }

    /**
     * Returns the cached target sphere mesh, or null if no target exists.
     */
    getTargetMesh(): THREE.Mesh | null {
        return this.targetMesh;
    }

    /**
     * Returns the Target instance, or null if no target exists.
     */
    getTarget(): Target | null {
        return this.target;
    }

    /**
     * Returns whether the target is ready to be interacted with.
     */
    getIsTargetReady(): boolean {
        return this.isTargetReady;
    }

    /**
     * Creates the initial target after countdown is done.
     * Only creates if no target exists yet.
     *
     * @param scene - The Three.js scene to add meshes to
     * @param camera - The camera for position calculation
     * @param callbacks - Statistics callbacks for Fitts' Law metrics
     */
    createInitial(
        scene: THREE.Scene,
        camera: THREE.Camera,
        callbacks: TargetStatisticsCallbacks,
    ): void {
        if (this.targetMesh) return;

        const newPos: THREE.Vector3 = Target.randomPosition(new THREE.Vector3(0, 0, 0), camera);
        this.target = Target.create(
            GameConfig.TARGET_COLOR,
            'target',
            new THREE.Vector3(
                // eslint-disable-next-line @typescript-eslint/restrict-plus-operands
                camera.position.x + newPos.x,
                // eslint-disable-next-line @typescript-eslint/restrict-plus-operands
                camera.position.y + newPos.y,
                // eslint-disable-next-line @typescript-eslint/restrict-plus-operands
                camera.position.z + newPos.z,
            ),
        );

        if (this.target) {
            const sphereMesh = this.target.sphereMesh();
            const ringMesh = this.target.ringMesh();
            if (sphereMesh) scene.add(sphereMesh);
            if (ringMesh) scene.add(ringMesh);

            this.targetMesh = sphereMesh;
            this.targetRingMesh = ringMesh;

            // Calculate initial angular distance for Fitts' Law
            const initialAngleRad = Utils.getCameraAngleToTarget(camera, sphereMesh.position);
            const initialAngleDeg = initialAngleRad * (180 / Math.PI);
            const targetRadius = this.target.getRadius();
            callbacks.startTargetMetrics(sphereMesh.position, camera.position, initialAngleDeg, targetRadius);
        }

        this.targetUpdateDirection = THREE.MathUtils.randFloat(-0.0001, 0.0001);
        this.isTargetReady = true;

        callbacks.startTargetTracking();
    }

    /**
     * Performs raycasting to check if the crosshair is over the target.
     *
     * @param camera - The camera to raycast from
     * @returns Whether the crosshair is hovering over the target
     */
    checkHover(camera: THREE.Camera): boolean {
        // Performance optimization: Reuse vector object and raycast only target
        this.raycaster.setFromCamera(this.raycastOrigin, camera);
        this.lastRaycastIntersects = this.targetMesh
            ? this.raycaster.intersectObject(this.targetMesh)
            : [];

        return this.lastRaycastIntersects.length > 0;
    }

    /**
     * Gets the hit distance from the raycast intersection point to the target center.
     * Uses the cached result from the last checkHover() call to avoid a redundant raycast.
     * Should only be called after checkHover() returns true in the same frame.
     *
     * @returns Hit distance, or null if no intersection was cached
     */
    getHitDistance(): number | null {
        if (this.lastRaycastIntersects.length > 0) {
            const hitPoint: THREE.Vector3 = this.lastRaycastIntersects[0].point;
            const targetPosition: THREE.Vector3 = this.lastRaycastIntersects[0].object.position;
            const distance: number = hitPoint.distanceTo(targetPosition);

            return distance;
        }
        return null;
    }

    /**
     * Relocates the target to a new random position via lerp animation.
     * Called when the player hits the target.
     *
     * @param time - Current timestamp for lerp timing
     * @param camera - The camera for position calculation
     */
    relocateTarget(time: number, camera: THREE.Camera): void {
        const currentTarget = this.targetMesh;
        if (!currentTarget) return;

        this.lerpStartPosition.copy(currentTarget.position);

        const newPos: THREE.Vector3 = Target.randomPosition(currentTarget.position, camera);
        this.lerpTargetPosition.set(
            // eslint-disable-next-line @typescript-eslint/restrict-plus-operands
            camera.position.x + newPos.x,
            // eslint-disable-next-line @typescript-eslint/restrict-plus-operands
            camera.position.y + newPos.y,
            // eslint-disable-next-line @typescript-eslint/restrict-plus-operands
            camera.position.z + newPos.z,
        );

        this.isLerping = true;
        this.isTargetReady = false;
        this.lerpStartTime = time;
    }

    /**
     * Flashes the target red on a miss.
     */
    flashMiss(): void {
        this.target?.flash(GameConfig.COLOR_TARGET_MISS);
    }

    /**
     * Updates the ring color based on hover state.
     *
     * @param isHovering - Whether the crosshair is over the target
     * @param canFire - Whether the player can currently fire
     */
    updateRingColor(isHovering: boolean, canFire: boolean): void {
        if (this.target && canFire) {
            if (isHovering) {
                this.target.setRingColor(GameConfig.COLOR_TARGET_HOVER);
            } else {
                this.target.resetRingColor();
            }
        }
    }

    /**
     * Updates target transform: lerp animation and billboard facing.
     *
     * @param time - Current timestamp
     * @param camera - The camera for lookAt calculations
     * @param lastCameraPosition - Previous frame camera position
     * @param cameraMovementThreshold - Minimum distance to consider camera moved
     * @param callbacks - Statistics callbacks for when lerp completes
     */
    updateTransform(
        time: number,
        camera: THREE.Camera,
        lastCameraPosition: THREE.Vector3,
        cameraMovementThreshold: number,
        callbacks: TargetStatisticsCallbacks,
    ): void {
        const target = this.targetMesh;
        const targetRing = this.targetRingMesh;
        const cameraMovedSignificantly =
            camera.position.distanceTo(lastCameraPosition) > cameraMovementThreshold;

        if (target) {
            this.updateLerp(time, target, camera, callbacks);

            if (this.isLerping || cameraMovedSignificantly) {
                target.lookAt(camera.position);
            }
        }

        if (targetRing) {
            if (target) {
                targetRing.position.copy(target.position);
            }

            if (this.isLerping || cameraMovedSignificantly) {
                targetRing.lookAt(camera.position);
            }
        }
    }

    /**
     * Removes the target meshes from the Three.js scene and resets all lerp/ready state.
     * Call this before clearMeshReferences() when the scene is still alive (e.g. resetMatch).
     *
     * @param scene - The Three.js scene to remove meshes from
     */
    removeFromScene(scene: THREE.Scene): void {
        if (this.targetMesh) {
            scene.remove(this.targetMesh);
        }
        if (this.targetRingMesh) {
            scene.remove(this.targetRingMesh);
        }
        this.isLerping = false;
        this.isTargetReady = false;
        this.lastRaycastIntersects = [];
    }

    /**
     * Clears cached mesh references and resets quadrant state during cleanup.
     */
    clearMeshReferences(): void {
        this.targetMesh = null;
        this.targetRingMesh = null;
        this.target = null;
        this.isLerping = false;
        this.isTargetReady = false;
        this.lastRaycastIntersects = [];

        // Reset quadrant distribution so the next session starts fresh
        Target.resetQuadrants();
    }

    // ── Private methods ──────────────────────────────────────────

    /**
     * Updates the lerp animation for target relocation.
     */
    private updateLerp(
        time: number,
        target: THREE.Mesh,
        camera: THREE.Camera,
        callbacks: TargetStatisticsCallbacks,
    ): void {
        if (!this.isLerping) return;

        const elapsed = time - this.lerpStartTime;
        const progress = Math.min(elapsed / GameConfig.TARGET_LERP_DURATION_MS, 1.0);

        // Cubic easing
        const easedProgress =
            progress < 0.5
                ? 4 * progress * progress * progress
                : 1 - ((((-2 * progress) + 2) ** 3) / 2);

        target.position.lerpVectors(
            this.lerpStartPosition,
            this.lerpTargetPosition,
            easedProgress,
        );

        if (progress >= 1.0) {
            this.isLerping = false;
            this.isTargetReady = true;

            callbacks.startTargetTracking();

            const initialAngleRad = Utils.getCameraAngleToTarget(camera, target.position);
            const initialAngleDeg = initialAngleRad * (180 / Math.PI);
            const targetRadius = this.target?.getRadius() ?? 0;
            callbacks.startTargetMetrics(target.position, camera.position, initialAngleDeg, targetRadius);
        }
    }
}
