import { useState, useEffect } from 'react';
import { GameConfig } from '../game/Config';

/**
 * Guards against accidental game restarts caused by the OS cursor snapping back
 * to its pre-lock position when pointer lock is released.
 *
 * When a game session ends (GAME_OVER), the browser releases pointer lock and the
 * OS repositions the cursor to where it was before the lock was acquired — typically
 * right on top of the Play button. Without a guard, any accidental click at that
 * position immediately re-triggers launchGame().
 *
 * ## Release logic (whichever comes first):
 * 1. **Mouse movement path** — on the *first* `mousemove` event after game over,
 *    a one-shot `ACCIDENTAL_RESTART_GUARD_MOVEMENT_DELAY_MS` (500 ms) timer starts.
 *    The listener is removed immediately so subsequent movements do NOT reset the
 *    timer (fixing the debounce-keeps-resetting bug).
 * 2. **Fallback path** — if the user never moves the mouse, the guard releases after
 *    `ACCIDENTAL_RESTART_GUARD_FALLBACK_MS` (1000 ms) unconditionally.
 *
 * @param isGameOver - True when the game has ended naturally (all targets attempted).
 * @returns `isAwaitingMouseMove` — true while the Play button should be disabled.
 */
export function useAccidentalRestartGuard(isGameOver: boolean): { isAwaitingMouseMove: boolean } {
    const [isAwaitingMouseMove, setIsAwaitingMouseMove] = useState(false);

    useEffect(() => {
        if (!isGameOver) {
            setIsAwaitingMouseMove(false);
            return;
        }

        setIsAwaitingMouseMove(true);

        /** Timer started by the fallback path (releases after 1000 ms of no movement). */
        let fallbackId: ReturnType<typeof setTimeout> | null = null;
        /** Timer started after the first movement (releases 500 ms after that movement). */
        let movementDelayId: ReturnType<typeof setTimeout> | null = null;

        /** Clears all pending timers and removes the mousemove listener. */
        const cleanup = (): void => {
            if (fallbackId !== null) {
                clearTimeout(fallbackId);
                fallbackId = null;
            }
            if (movementDelayId !== null) {
                clearTimeout(movementDelayId);
                movementDelayId = null;
            }
            document.removeEventListener('mousemove', handleFirstMouseMove);
        };

        /**
         * Handles the *first* mousemove after game over.
         * Immediately removes itself so it never fires again for this guard session,
         * cancels the fallback timer, and starts the shorter post-movement delay.
         */
        const handleFirstMouseMove = (): void => {
            // Remove listener right away — subsequent movements must NOT restart the timer.
            document.removeEventListener('mousemove', handleFirstMouseMove);

            if (fallbackId !== null) {
                clearTimeout(fallbackId);
                fallbackId = null;
            }

            // Wait ACCIDENTAL_RESTART_GUARD_MOVEMENT_DELAY_MS after the first movement,
            // then re-enable the button.
            movementDelayId = setTimeout(() => {
                setIsAwaitingMouseMove(false);
                movementDelayId = null;
            }, GameConfig.ACCIDENTAL_RESTART_GUARD_MOVEMENT_DELAY_MS);
        };

        // Fallback: re-enable after 1000 ms even if the user never moves the mouse.
        fallbackId = setTimeout(() => {
            fallbackId = null;
            cleanup();
            setIsAwaitingMouseMove(false);
        }, GameConfig.ACCIDENTAL_RESTART_GUARD_FALLBACK_MS);

        document.addEventListener('mousemove', handleFirstMouseMove);

        // eslint-disable-next-line consistent-return
        return cleanup;
    }, [isGameOver]);

    return { isAwaitingMouseMove };
}
