/**
 * Game event constants for TargetPracticeGame.
 *
 * Defines all events that the game can emit. New events should be added here
 * along with their corresponding payload type in GameEventMap.
 */

import { GameState } from './state/GameState';
import { StatisticsEntry } from './types';

/**
 * Enumeration of all game event names.
 * Use these constants when calling game.on() / game.off() / game.emit().
 */
export const GameEvents = {
    /** Fired whenever the game state machine transitions between states */
    STATE_CHANGED: 'STATE_CHANGED' as const,
    STATISTICS: 'STATISTICS' as const,
} as const;

/**
 * Type map linking each event name to its payload shape.
 * This is used by EventEmitter<GameEventMap> to enforce type safety.
 *
 * To add a new event:
 * 1. Add the event name to GameEvents above
 * 2. Add the payload interface here
 */
export type GameEventMap = {
    [GameEvents.STATE_CHANGED]: {
        /** The state the game was in before the transition */
        oldState: keyof typeof GameState;
        /** The state the game transitioned to */
        newState: keyof typeof GameState;
        /** Optional context data passed during the transition */
        context: object;
    };
    [GameEvents.STATISTICS]: StatisticsEntry;
};
