import * as THREE from 'three';
import { GameConfig } from './Config';

/**
 * Shared ground material singleton.
 * This material is intentionally shared across all ground meshes for performance.
 * WARNING: Mutating properties (color, emissive, etc.) affects ALL meshes using this material.
 * This is safe in the current single-instance game architecture.
 */
const groundMaterial: THREE.MeshStandardMaterial = new THREE.MeshStandardMaterial();
groundMaterial.color = new THREE.Color(GameConfig.GROUND_MATERIAL.COLOR);
groundMaterial.emissive = new THREE.Color(GameConfig.GROUND_MATERIAL.EMISSIVE);
groundMaterial.emissiveIntensity = GameConfig.GROUND_MATERIAL.EMISSIVE_INTENSITY;

export class MaterialsLibrary {
    static ground(): THREE.MeshStandardMaterial {
        return groundMaterial;
    }
}
