import { useState, useEffect } from 'react';
import { getLang } from 'modules/base';
import { GameEvents } from '../game/GameEvents';
import { TargetPracticeGame } from '../game/Main';
import { StatisticsEntry } from '../game/types';

const { STRING, STRINGS } = getLang();

const MAX_STATS_HISTORY = 10;

function getDefaultRecommendation(): string {
    return STRING(STRINGS.DPI_TESTER_DEFAULT_RECOMMENDATION);
}

function generateRecommendation(data: StatisticsEntry): string {
    const { overshoots, undershoots, perfectHits, averageMT } = data;

    let roundStatistics = '';
    if (overshoots === undershoots) {
        roundStatistics = `${STRING(STRINGS.DPI_TESTER_ROUND_STATISTICS_EQUAL, {
            OVERSHOOTS: overshoots,
            PERFECT_HITS: perfectHits,
        })}`;
    } else {
        roundStatistics = `${STRING(STRINGS.DPI_TESTER_ROUND_STATISTICS_DIFFERENT, {
            OVERSHOOTS: overshoots,
            UNDERSHOOTS: undershoots,
            PERFECT_HITS: perfectHits,
        })}`;
    }

    let recommendationText = '';
    if (Math.abs(overshoots - undershoots) <= 1) {
        recommendationText = (averageMT * 1000) > 480
            ? STRING(STRINGS.DPI_TESTER_ADVICE_MOVE_FASTER)
            : STRING(STRINGS.DPI_TESTER_ADVICE_FOCUS_ACCURACY);
    } else if (overshoots > undershoots) {
        recommendationText = STRING(STRINGS.DPI_TESTER_ADVICE_LOWER_DPI);
    } else {
        recommendationText = STRING(STRINGS.DPI_TESTER_ADVICE_HIGHER_DPI);
    }

    return `${roundStatistics}\n${recommendationText}`;
}

export function useGameStatistics(game: TargetPracticeGame | null) {
    const [history, setHistory] = useState<StatisticsEntry[]>([]);
    const [recommendation, setRecommendation] = useState(getDefaultRecommendation);

    useEffect(() => {
        if (!game) return undefined;

        const handleStats = (data: StatisticsEntry) => {
            setHistory(prev => [data, ...prev].slice(0, MAX_STATS_HISTORY));
            setRecommendation(generateRecommendation(data));
        };

        game.on(GameEvents.STATISTICS, handleStats);
        return () => { game.off(GameEvents.STATISTICS, handleStats); };
    }, [game]);

    return { history, recommendation };
}
