import type * as THREE from 'three';
import { logError } from 'logger/log';

/**
 * Configuration for creating a GameLoop instance.
 */
interface GameLoopConfig {
    renderer: THREE.WebGLRenderer;
    onUpdate: (time: number, delta: number) => void;
}

/**
 * Pure animation frame lifecycle controller.
 *
 * Owns only: start, stop, delta-time calculation, error boundary,
 * and renderer reference management (for WebGL context restore).
 *
 * All gameplay orchestration lives in the Facade (TargetPracticeGame),
 * which provides the `onUpdate` callback.
 */
export class GameLoop {
    private renderer: THREE.WebGLRenderer | null;
    private onUpdate: ((time: number, delta: number) => void) | null;
    private isRunning: boolean;
    private lastTime: number;

    constructor(config: GameLoopConfig) {
        this.renderer = config.renderer;
        this.onUpdate = config.onUpdate;
        this.isRunning = false;
        this.lastTime = 0;
    }

    /**
     * Internal animation frame callback.
     */
    private _loop = (time: number): void => {
        if (!this.isRunning) return;

        const delta = this.lastTime ? (time - this.lastTime) : 0;
        this.lastTime = time;

        try {
            this.onUpdate?.(time, delta);
        } catch (error) {
            logError('[GameLoop] Error in update:', error);
            this.stop();
        }
    };

    /**
     * Starts the animation loop via `renderer.setAnimationLoop`.
     * No-op if already running or renderer is null.
     */
    start(): void {
        if (this.isRunning) return;
        if (!this.renderer) return;

        this.isRunning = true;
        this.lastTime = 0;
        this.renderer.setAnimationLoop(this._loop);
    }

    /**
     * Stops the animation loop.
     * No-op if not running.
     */
    stop(): void {
        if (!this.isRunning) return;
        this.isRunning = false;
        this.renderer?.setAnimationLoop(null);
    }

    /**
     * Updates the renderer reference.
     * Used after WebGL context restore when a new renderer is created.
     */
    setRenderer(renderer: THREE.WebGLRenderer): void {
        const wasRunning = this.isRunning;
        if (wasRunning) {
            this.stop();
        }
        this.renderer = renderer;
        if (wasRunning) {
            this.start();
        }
    }

    /**
     * Stops the loop and nullifies all references.
     * Call this during game cleanup.
     */
    dispose(): void {
        this.stop();
        this.renderer = null;
        this.onUpdate = null;
    }
}
