import { useEffect, useRef } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { logWarning } from 'logger/log';
import { getImmutableActiveDevice } from 'controllers/device_controller';
import { setActiveOverlay } from 'slices/appState';
import { navigateTo } from 'navigation/navigationService';
import { ROUTES } from 'navigation/route.config';

/**
 * Guards the DPI Tester overlay against device disconnection.
 * When the active mouse is physically unplugged while the DPI Tester is open.
 */
export function useActiveDeviceGuard(): void {
    const dispatch = useDispatch();
    const activeDevice = useSelector(getImmutableActiveDevice);

    useEffect(() => {
        if (!activeDevice) {
            logWarning('DpiTester - useActiveDeviceGuard - Active device disconnected, navigating to home', null);

            // Safety net: if pointer lock is still active, release it explicitly so the
            // cursor is always restored before navigation.
            if (document.pointerLockElement) {
                document.exitPointerLock();
            }

            dispatch(setActiveOverlay({}));
            navigateTo(ROUTES.home);
        }
    }, [activeDevice, dispatch]);
}
