import { logError } from 'logger/log';

/**
 * A lightweight, typed event emitter for game event handling.
 *
 * @template TEventMap - A record mapping event names to their payload types.
 *
 * @example
 * ```typescript
 * interface MyEvents {
 *     STATE_CHANGED: { oldState: string; newState: string };
 * }
 *
 * const emitter = new EventEmitter<MyEvents>();
 * emitter.on('STATE_CHANGED', ({ newState }) => console.log(newState));
 * emitter.emit('STATE_CHANGED', { oldState: 'A', newState: 'B' });
 * ```
 */

type EventHandler<T> = (payload: T) => void;

export class EventEmitter<TEventMap extends { [key: string]: unknown }> {
    private _listeners: Map<keyof TEventMap, Set<EventHandler<never>>>;

    constructor() {
        this._listeners = new Map();
    }

    /**
     * Register an event handler for a specific event.
     * @param event - The event name to listen for
     * @param handler - The callback function to invoke when the event is emitted
     */
    on<K extends keyof TEventMap>(event: K, handler: EventHandler<TEventMap[K]>): void {
        if (!this._listeners.has(event)) {
            this._listeners.set(event, new Set());
        }

        this._listeners.get(event)!.add(handler as EventHandler<never>);
    }

    /**
     * Remove a previously registered event handler.
     * @param event - The event name to stop listening for
     * @param handler - The exact handler reference that was passed to `on()`
     */
    off<K extends keyof TEventMap>(event: K, handler: EventHandler<TEventMap[K]>): void {
        const handlers = this._listeners.get(event);
        if (!handlers) return;

        handlers.delete(handler as EventHandler<never>);

        if (handlers.size === 0) {
            this._listeners.delete(event);
        }
    }

    /**
     * Emit an event, invoking all registered handlers with the given payload.
     * Errors in individual handlers are caught and logged to prevent
     * one failing handler from blocking others.
     * @param event - The event name to emit
     * @param payload - The data to pass to each handler
     */
    emit<K extends keyof TEventMap>(event: K, payload: TEventMap[K]): void {
        const handlers = this._listeners.get(event);
        if (!handlers) return;

        handlers.forEach((handler) => {
            try {
                (handler as EventHandler<TEventMap[K]>)(payload);
            } catch (error) {
                logError(`[EventEmitter] Error in handler for event "${String(event)}":`, error, true);
            }
        });
    }

    /**
     * Remove all registered listeners for all events.
     * Should be called during cleanup/disposal to prevent memory leaks.
     */
    removeAllListeners(): void {
        this._listeners.clear();
    }

    /**
     * Remove all registered listeners for a specific event.
     * @param event - The event name to clear listeners for
     */
    removeListenersFor<K extends keyof TEventMap>(event: K): void {
        this._listeners.delete(event);
    }

    /**
     * Get the number of listeners registered for a specific event.
     * Useful for debugging and testing.
     * @param event - The event name to check
     * @returns The number of registered listeners
     */
    listenerCount<K extends keyof TEventMap>(event: K): number {
        const handlers = this._listeners.get(event);
        return handlers ? handlers.size : 0;
    }
}
