import * as THREE from 'three';
import { logInfo, logError, logWarning } from 'logger/log';
import { FBXLoader } from 'three/addons/loaders/FBXLoader.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RendererBuilder } from './Renderer';
import { SceneBuilder } from './Scene';
import { MaterialsLibrary } from './Materials';
import { GameLoop } from './GameLoop';
import { GameConfig } from './Config';
// @ts-expect-error — asset import handled by bundler
import SmGrid from './resources/models/SM_Grid.fbx';

/**
 * Configuration required to initialise the graphics subsystem.
 */
export interface GraphicsContextConfig {
    /** Player eye-height — passed to RendererBuilder.createCamera */
    playerHeight: number;
    /** Frame callback invoked by the GameLoop every animation frame */
    onUpdate: () => void;
    /**
     * Optional callback that returns true if initialisation should be aborted.
     * Called at key checkpoints during init() to allow the caller (Main)
     * to abort if e.g. the game state has transitioned to CLEANING_UP.
     */
    shouldAbort?: () => boolean;
}

/**
 * GraphicsContext owns the entire Three.js rendering pipeline:
 * scene, renderer, camera, post-processing composer, WebGL context
 * lifecycle, window resize handling, and the GameLoop.
 *
 * Main accesses `camera` and `scene` via public readonly getters
 * and calls `render()` / `dispose()` — everything else is internal.
 */
export class GraphicsContext {
    /** The Three.js WebGL renderer — null before init / after dispose */
    private _renderer: THREE.WebGLRenderer | null = null;

    /** The perspective camera — null before init / after dispose */
    private _camera: THREE.PerspectiveCamera | null = null;

    /** The Three.js scene — null before init / after dispose */
    private _scene: THREE.Scene | null = null;

    /** Post-processing effect composer */
    private _composer: EffectComposer | null = null;

    /** Render pass (scene + camera) — internal to composer pipeline */
    private _renderPass: RenderPass | null = null;

    /** Animation frame controller */
    private _gameLoop: GameLoop | null = null;

    /** FBX model loader */
    private readonly _fbxLoader = new FBXLoader();

    /** Last known camera position for movement-threshold checks */
    private readonly _lastCameraPosition = new THREE.Vector3();


    /** Bound context-loss handler for clean removal */
    private _boundHandleContextLoss: ((event: Event) => void) | null = null;

    /** Bound context-restore handler for clean removal */
    private _boundHandleContextRestore: (() => void) | null = null;

    /** Stored onUpdate callback for context restore */
    private _onUpdateCallback: (() => void) | null = null;

    // ── Public getters ────────────────────────────────────────────

    get renderer(): THREE.WebGLRenderer | null {
        return this._renderer;
    }

    get camera(): THREE.PerspectiveCamera | null {
        return this._camera;
    }

    get scene(): THREE.Scene | null {
        return this._scene;
    }

    get composer(): EffectComposer | null {
        return this._composer;
    }

    /** Returns true if renderer + camera + scene are all created */
    get isReady(): boolean {
        return this._renderer !== null && this._camera !== null && this._scene !== null;
    }

    // ── Initialisation ────────────────────────────────────────────

    /**
     * Creates scene, renderer, camera, composer, mounts DOM, and starts the game loop.
     * Must be called once before any rendering can occur.
     *
     * @param config - Player height and frame update callback
     * @returns true if initialisation succeeded, false otherwise
     */
    init(config: GraphicsContextConfig): boolean {
        this._onUpdateCallback = config.onUpdate;
        const shouldAbort = config.shouldAbort ?? (() => false);

        // Abort check before starting
        if (shouldAbort()) {
            logInfo('[GraphicsContext] Aborting init: shouldAbort returned true', {shouldAbort: true}, true);
            return false;
        }

        // 1. Scene
        this._setupScene();

        // 2. Renderer
        this._renderer = RendererBuilder.default(window);
        if (!this._renderer) {
            logError('[GraphicsContext] Failed to create renderer', {renderer: null}, true);
            return false;
        }

        // 3. Create animation loop but do NOT start it here.
        // The loop is started by Main.ts via startLoop() when pointer lock is acquired (onLock),
        // and stopped via stopLoop() when the lock is released (onUnlock).
        // This prevents the render loop from running at 60fps while the instructions screen is
        // visible between plays, which was causing ~1s UI lag on sliders, checkboxes and buttons.
        this._gameLoop = new GameLoop({
            renderer: this._renderer,
            onUpdate: config.onUpdate,
        });

        // 4. Camera
        this._camera = RendererBuilder.createCamera(GameConfig.CAMERA_FOV, config.playerHeight);
        if (!this._camera) {
            logError('[GraphicsContext] Failed to create camera', {camera: null}, true);
            return false;
        }

        // 5. WebGL context loss / restore handlers
        this._attachWebGLHandlers();

        // 6. Post-processing composer
        if (!this._scene) {
            logError('[GraphicsContext] Scene not initialised before composer setup', {scene: null}, true);
            return false;
        }
        this._createComposer();

        // Abort check after composer creation (matches original mid-setup guard)
        if (shouldAbort()) {
            logInfo('[GraphicsContext] Aborting init: shouldAbort returned true after composer', {shouldAbort: true}, true);
            return false;
        }

        // 7. Mount renderer DOM element — hidden until pointer lock is acquired (COUNTDOWN/PLAYING).
        // The canvas is appended here synchronously during INITIALIZING, before React has committed
        // GameInstructionsPopup. Without display:none the WebGL canvas flashes briefly on screen.
        const container = document.createElement('div');
        container.style.display = 'none';
        document.body.appendChild(container);
        container.appendChild(this._renderer.domElement);

        // 8. Initial resize + listener
        this._handleResize(); // Call for first refresh
        window.addEventListener('resize', this._handleResize);

        return true;
    }

    // ── Loop control ──────────────────────────────────────────────

    /**
     * Starts the render/game loop.
     */
    startLoop(): void {
        this._gameLoop?.start();
    }

    /**
     * Stops the render/game loop.
     * Called by Main when pointer lock is released (onUnlock) so the GPU is not
     * compositing an invisible 3D scene at 60fps while the instructions panel is shown.
     */
    stopLoop(): void {
        this._gameLoop?.stop();
    }

    // ── Frame rendering ───────────────────────────────────────────

    /** Renders the current frame via the post-processing composer */
    render(): void {
        this._composer?.render();
    }

    // ── Canvas visibility ─────────────────────────────────────────

    /**
     * Makes the renderer container visible.
     * Call this when pointer lock is acquired (COUNTDOWN state begins)
     * so the WebGL canvas only appears when the game is actively running.
     */
    showCanvas(): void {
        const container = this._renderer?.domElement.parentElement;
        if (container) {
            container.style.display = '';
        }
    }

    /**
     * Hides the renderer container.
     * Call this when pointer lock is released (CANCELLED, GAME_OVER, or cleanup)
     * so the WebGL canvas is not visible while the instructions panel is shown.
     */
    hideCanvas(): void {
        const container = this._renderer?.domElement.parentElement;
        if (container) {
            container.style.display = 'none';
        }
    }

    // ── Camera tracking ───────────────────────────────────────────

    /**
     * Returns true if the camera has moved more than the threshold
     * since the last call to updateCameraTracking().
     */
    hasCameraMoved(): boolean {
        if (!this._camera) return false;
        return this._camera.position.distanceTo(this._lastCameraPosition) > GameConfig.CAMERA_MOVEMENT_THRESHOLD;
    }

    /** Snapshots the current camera position for next-frame comparison */
    updateCameraTracking(): void {
        if (!this._camera) return;
        if (this.hasCameraMoved()) {
            this._lastCameraPosition.copy(this._camera.position);
        }
    }

    /** Returns the last known camera position (read-only copy) */
    get lastCameraPosition(): THREE.Vector3 {
        return this._lastCameraPosition;
    }

    /** Returns the camera movement threshold constant */
    get cameraMovementThreshold(): number {
        return GameConfig.CAMERA_MOVEMENT_THRESHOLD;
    }

    // ── Disposal ──────────────────────────────────────────────────

    /**
     * Stops the game loop, disposes renderer/scene/composer,
     * removes DOM elements and event listeners.
     */
    async dispose(): Promise<void> {
        // Stop game loop first
        if (this._gameLoop) {
            this._gameLoop.dispose();
            this._gameLoop = null;
        }

        // Wait one frame for the loop to fully stop
        if (this._renderer) {
            this._renderer.setAnimationLoop(null);
            await new Promise<void>(resolve => requestAnimationFrame(() => resolve()));
        }

        // Remove resize listener
        window.removeEventListener('resize', this._handleResize);

        // Remove WebGL context handlers
        this._detachWebGLHandlers();

        // Dispose composer
        if (this._composer) {
            try { this._composer.dispose(); } catch (e) {
                logWarning('[GraphicsContext] Failed to dispose composer:', e, true);
            }
        }

        // Dispose scene resources (geometries, materials, textures)
        if (this._scene) {
            this._disposeSceneResources();
        }

        // Force WebGL context loss + dispose renderer
        if (this._renderer) {
            this._forceWebGLContextLoss();
            try { this._renderer.dispose(); } catch (_e) {
                // Renderer disposal can fail if context already lost — safe to ignore
            }
        }

        // Remove renderer DOM element
        this._removeRendererElement();

        // Nullify references
        this._camera = null;
        this._renderPass = null;
        this._composer = null;
        this._scene = null;
        this._renderer = null;
        this._onUpdateCallback = null;
    }

    // ── Private methods ──────────────────────────────────────

    private _setupScene(): void {
        this._scene = SceneBuilder.createDefault();

        this._fbxLoader.load(
            SmGrid,
            (object: THREE.Group) => {
                if (!object || !this._scene) return;

                object.traverseVisible((child: THREE.Object3D) => {
                    if ((child as THREE.Mesh).isMesh) {
                        (child as THREE.Mesh).material = MaterialsLibrary.ground();
                    }
                });

                object.scale.set(0.001, 0.001, 0.001);
                object.position.y = -0.015;
                this._scene.add(object);
            },
            (xhr: ProgressEvent) => {
                logInfo(`[GraphicsContext] FBX model ${(xhr.loaded / xhr.total) * 100}% loaded`, null, true);
            },
            (error: unknown) => {
                logError('[GraphicsContext] Failed to load FBX model:', error, true);
            },
        );
    }

    private _createComposer(): void {
        if (!this._renderer || !this._scene || !this._camera) return;

        this._renderPass = new RenderPass(this._scene, this._camera);
        this._composer = new EffectComposer(this._renderer);
        this._composer.addPass(this._renderPass);
        this._composer.addPass(RendererBuilder.createBloomPass());
        this._composer.addPass(new OutputPass());
    }

    private _handleResize = (): void => {
        if (!this._renderer || !this._camera) return;

        const { innerWidth, innerHeight } = window;
        this._renderer.setSize(innerWidth, innerHeight);
        if (this._composer) {
            this._composer.setSize(innerWidth, innerHeight);
        }
        this._camera.aspect = innerWidth / innerHeight;
        this._camera.updateProjectionMatrix();
    };

    private _attachWebGLHandlers(): void {
        if (!this._renderer) return;

        const canvas = this._renderer.domElement;

        this._boundHandleContextLoss = (event: Event): void => {
            event.preventDefault();
            logWarning('[WebGL] Context lost — pausing rendering', null, true);
            if (this._renderer) {
                this._renderer.setAnimationLoop(null);
            }
        };

        this._boundHandleContextRestore = (): void => {
            logInfo('[WebGL] Context restored — reinitialising renderer', null, true);
            this._handleContextRestore();
        };

        canvas.addEventListener('webglcontextlost', this._boundHandleContextLoss, false);
        canvas.addEventListener('webglcontextrestored', this._boundHandleContextRestore, false);
    }

    private _detachWebGLHandlers(): void {
        if (!this._renderer) return;

        const canvas = this._renderer.domElement;
        if (this._boundHandleContextLoss) {
            canvas.removeEventListener('webglcontextlost', this._boundHandleContextLoss);
            this._boundHandleContextLoss = null;
        }
        if (this._boundHandleContextRestore) {
            canvas.removeEventListener('webglcontextrestored', this._boundHandleContextRestore);
            this._boundHandleContextRestore = null;
        }
    }

    private _handleContextRestore(): void {
        try {
            // Dispose old renderer
            if (this._renderer) {
                this._renderer.dispose();
            }

            // Recreate renderer
            this._renderer = RendererBuilder.default(window);
            if (!this._renderer) {
                logError('[WebGL] Failed to recreate renderer after context restore', {renderer: null}, true);
                return;
            }

            // Recreate composer with new renderer
            if (this._scene && this._camera) {
                this._createComposer();
            }

            // Reattach canvas to DOM — preserve display:none if no existing container
            const existingContainer = document.querySelector('div:has(> #renderer)');
            if (existingContainer) {
                existingContainer.innerHTML = '';
                existingContainer.appendChild(this._renderer.domElement);
            } else {
                const container = document.createElement('div');
                container.style.display = 'none';
                document.body.appendChild(container);
                container.appendChild(this._renderer.domElement);
            }

            // Update game loop with new renderer and restart
            if (this._gameLoop) {
                this._gameLoop.setRenderer(this._renderer);
            } else if (this._onUpdateCallback) {
                this._gameLoop = new GameLoop({
                    renderer: this._renderer,
                    onUpdate: this._onUpdateCallback,
                });
                this._gameLoop.start();
            }

            // Re-attach WebGL handlers to new canvas
            this._attachWebGLHandlers();

            // Trigger resize to ensure proper dimensions
            this._handleResize();

            logInfo('[WebGL] Context restore complete — rendering resumed', null, true);
        } catch (error) {
            logError('[WebGL] Error during context restore:', error, true);
        }
    }

    // ── Private: cleanup helpers ──────────────────────────────────

    private _forceWebGLContextLoss(): void {
        if (!this._renderer) return;
        try {
            const gl = this._renderer.getContext();
            if (gl) {
                const ext = gl.getExtension('WEBGL_lose_context');
                if (ext) ext.loseContext();
            }
        } catch (e) {
            logWarning('[GraphicsContext] Failed to force WebGL context loss:', e, true);
        }
    }

    private _disposeSceneResources(): void {
        if (!this._scene) return;
        try {
            this._scene.traverse((object: THREE.Object3D) => {
                if (!(object as THREE.Mesh).isMesh) return;
                const mesh = object as THREE.Mesh;

                if (mesh.geometry) {
                    try { mesh.geometry.dispose(); } catch (e) {
                        logWarning('[GraphicsContext] Failed to dispose geometry:', e, true);
                    }
                }

                if (mesh.material) {
                    const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
                    materials.forEach((mat: THREE.Material) => {
                        try {
                            mat.dispose();

                            // Dispose textures attached to the material
                            Object.values(mat).forEach((value: unknown) => {
                                if (value && typeof value === 'object' && 'minFilter' in value) {
                                    try {
                                        if (typeof (value as THREE.Texture).dispose === 'function') {
                                            (value as THREE.Texture).dispose();
                                        }
                                    } catch (texErr) {
                                        logWarning('[GraphicsContext] Failed to dispose texture:', texErr, true);
                                    }
                                }
                            });
                        } catch (e) {
                            logWarning('[GraphicsContext] Failed to dispose material:', e, true);
                        }
                    });
                }
            });
        } catch (e) {
            logError('[GraphicsContext] Failed to dispose scene resources:', e, true);
        }
    }

    private _removeRendererElement(): void {
        const rendererElement = document.getElementById('renderer');
        if (rendererElement) {
            const container = rendererElement.parentElement;
            if (container) {
                try {
                    container.style.display = 'none';
                    document.body.removeChild(container);
                } catch (e) {
                    logWarning('[GraphicsContext] Failed to remove renderer element:', e, true);
                }
            }
        }
    }
}
