import { Button, Icon, IconName, IconSize } from '@logi/magnetite';
import { useDispatch, useSelector } from 'react-redux';
import { getImmutableActiveDevice } from 'controllers/device_controller';
import { setActiveOverlay } from 'slices/appState';
import { getLang, Keys } from 'modules/base';
import { useCallback, useEffect } from 'react';
import { BodyText } from 'modules/base/components/typography';
import { navigateTo } from 'navigation/navigationService';
import { ROUTES } from 'navigation/route.config';

const { STRING, STRINGS } = getLang();

interface GameInstructionActionsProps {
    onStartGame: () => void,
    isPlayDisabled?: boolean;
}

function GameInstructionActions({ onStartGame, isPlayDisabled }: GameInstructionActionsProps) {
    const device = useSelector(getImmutableActiveDevice);
    const dispatch = useDispatch();

    const handleBackBtnClick = useCallback(() => {
        const isDeviceRequiresUpdate = device?.dfuInfo?.dfuAvailable && device?.dfuInfo?.dfuRequired;

        if (isDeviceRequiresUpdate) {
            // A mandatory firmware update is pending — navigate to home so the
            // user cannot access device configuration until DFU is complete.
            dispatch(setActiveOverlay({}));
            navigateTo(ROUTES.home);
            return;
        }

        dispatch(setActiveOverlay({ device }));
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [device]);

    // Escape key handler — only navigate away when pointer lock is NOT active.
    // When pointer IS locked, the game's InputManager ESC handler manages it
    // (unlock → CANCELLED), and the browser releases the lock automatically.
    // Once the lock is released, this component becomes visible again and
    // subsequent ESC presses will navigate away as expected.
    useEffect(() => {
        const handleEscapeClick = (event: KeyboardEvent) => {
            if (event.key === Keys.Escape && !document.pointerLockElement) {
                event.preventDefault();
                event.stopPropagation();
                handleBackBtnClick();
            }
        };

        document.addEventListener('keydown', handleEscapeClick);
        return () => document.removeEventListener('keydown', handleEscapeClick);
    }, [handleBackBtnClick]);

    const handlePlayClick = () => {
        onStartGame();
    };

    return (
        <div
            className="instructions-ctas"
            data-testid="dpi-tester-actions"
        >
            <div className="info-container" data-testid="dpi-tester-info-container">
                <Icon
                    name={IconName.more_info}
                    size={IconSize.smallest}
                    aria-hidden="true"
                />
                <BodyText level={2} className="info-text" data-testid="dpi-tester-active-dpi-info">
                    {STRING(STRINGS.DPI_TESTER_ACTIVE_DPI_INFO)}
                </BodyText>
            </div>
            <div className="ctas-container">
                <Button
                    onClick={handleBackBtnClick}
                    type="text"
                    text={STRING(STRINGS.DPI_TESTER_QUIT)}
                    data-testid="dpi-tester-quit-button"
                />
                <Button
                    classes="confirm-btn"
                    onClick={handlePlayClick}
                    text={STRING(STRINGS.DPI_TESTER_PLAY)}
                    data-testid="dpi-tester-play-button"
                    disabled={isPlayDisabled}
                />
            </div>
        </div>
    );
}

export default GameInstructionActions;
