import { useState, useEffect } from 'react';
import { GameState } from '../game/state/GameState';
import { GameEventMap, GameEvents } from '../game/GameEvents';
import { TargetPracticeGame } from '../game/Main';

type GameStateType = keyof typeof GameState

interface GameStateResult {
    /** The current game state value */
    gameState: GameStateType;
    /** True when the game has not been initialized yet */
    isUninitialized: boolean;
    /** True when the game is loading resources */
    isInitializing: boolean;
    /** True when the game is initialized and ready to start */
    isReady: boolean;
    /** True when the countdown timer is active (3, 2, 1...) */
    isCountdown: boolean;
    /** True when the game is actively being played */
    isPlaying: boolean;
    /** True when all targets have been attempted */
    isGameOver: boolean;
    /** True when the game is disposing resources */
    isCleaningUp: boolean;
    /** True when the user pressed ESC during COUNTDOWN or PLAYING — engine stays alive */
    isCancelled: boolean;
    /** True during the brief synchronous reset before a new COUNTDOWN begins */
    isReseting: boolean;
}

/**
 * React hook that subscribes to game state changes from a TargetPracticeGame instance.
 *
 * Listens for STATE_CHANGED events emitted by the game and provides
 * the current state along with boolean convenience flags for each state.
 *
 * The hook accepts the game instance directly (not a ref) so that React
 * can detect when the instance changes and re-subscribe accordingly.
 *
 * @param game - The TargetPracticeGame instance to subscribe to, or null
 * @returns An object with the current game state and boolean flags for each state
 */

export function useGameState(game: TargetPracticeGame | null): GameStateResult {
    const [gameState, setGameState] = useState<GameStateType>(GameState.UNINITIALIZED);

    useEffect(() => {
        if (!game) {
            setGameState(GameState.UNINITIALIZED);
            return undefined;
        }

        const handleStateChange = ({ newState }: GameEventMap['STATE_CHANGED']): void => {
            setGameState(newState);
        };

        game.on(GameEvents.STATE_CHANGED, handleStateChange);
        setGameState(game.getState());

        return () => {
            game.off(GameEvents.STATE_CHANGED, handleStateChange);
        };
    }, [game]);

    return {
        gameState,
        isUninitialized: gameState === GameState.UNINITIALIZED,
        isInitializing: gameState === GameState.INITIALIZING,
        isReady: gameState === GameState.READY,
        isCountdown: gameState === GameState.COUNTDOWN,
        isPlaying: gameState === GameState.PLAYING,
        isGameOver: gameState === GameState.GAME_OVER,
        isCleaningUp: gameState === GameState.CLEANING_UP,
        isCancelled: gameState === GameState.CANCELLED,
        isReseting: gameState === GameState.RESETING,
    };
}
