import type * as THREE from 'three';
import { AudioEngine } from './AudioEngine';
import { Statistics } from './statistics/Statistics';
import { AimAnalysisSystem, AimAnalysisResult } from './AimAnalysisSystem';
import { GameConfig } from './Config';
import { ControlsManager } from './ControlsManager';
import { GameState, GameStateMachine, GameStateValue } from './state/GameState';
import { EventEmitter } from './EventEmitter';
import { GameEvents, GameEventMap } from './GameEvents';
import { GraphicsContext } from './GraphicsContext';
import { HudManager } from './hud/HudManager';
import { PlayerController, PlayerControls } from './PlayerController';
import { InputManager } from './InputManager';
import { TargetManager, TargetStatisticsCallbacks } from './TargetManager';
import { logInfo, logError, logWarning } from 'logger/log';

/** Shape of a single countdown step */
interface CountdownStep {
    /** Text to display on the HUD (e.g. '3', '2', '1', '') */
    display: string;
    /** Detune value (cents) for the countdown beep */
    detune: number;
}

/** Countdown steps indexed by second — index 0 = first second, etc. */
const COUNTDOWN_STEPS: readonly CountdownStep[] = [
    { display: '3', detune: GameConfig.COUNTDOWN_DETUNE_DEFAULT },  // 0-999ms
    { display: '2', detune: GameConfig.COUNTDOWN_DETUNE_DEFAULT },  // 1000-1999ms
    { display: '1', detune: GameConfig.COUNTDOWN_DETUNE_DEFAULT },  // 2000-2999ms
    { display: '',  detune: GameConfig.COUNTDOWN_DETUNE_GO },       // 3000ms — Go
];

/** Countdown ends when the last step is reached */
const COUNTDOWN_DURATION_MS: number = (COUNTDOWN_STEPS.length - 1) * GameConfig.COUNTDOWN_STEP_MS;

/**
 * The main loop of the game.
 *
 * This contains the entire game logic and scoring
 * system. Statistics are in a separate module/folder.
 *
 * Project: Zapper.
 * Authors: Thomas Rouvinez - trouvinez@logitech.com.
 *          With the help of Khalil M'hirsi for statistics.
 */
export class TargetPracticeGame {
    // ── Subsystems ------------------------──────────────────────────
    private readonly stateMachine = new GameStateMachine(GameState.UNINITIALIZED);
    private readonly _emitter = new EventEmitter<GameEventMap>();
    private graphics = new GraphicsContext();
    private readonly controlsManager = new ControlsManager();
    private readonly inputManager = new InputManager();
    private readonly targetManager = new TargetManager();
    private readonly playerController = new PlayerController(true);
    private audioEngine: AudioEngine | null = new AudioEngine();
    private readonly statistics = new Statistics(GameConfig.GAME_LENGTH);
    /** Aim analysis: overshoot/undershoot detection + error axis tracking */
    private readonly aimAnalysis = new AimAnalysisSystem();
    /**
     * HUD is created during initialize(),
     * because the DOM elements only need to exist when the game is active.
     */
    private readonly hud = new HudManager(GameConfig.GAME_LENGTH);

    // ── Game state ──────────────────────────────────────────────────
    private startTimestamp: number | null = null;
    private prevTime: number = performance.now();
    private readonly gameLength: number = GameConfig.GAME_LENGTH;

    // ── Performance optimization: track state changes ───────────────
    private lastCountdownValue: string | null = null;
    private lastTargetIndex: number = -1;

    // ── First-frame sentinel (Windows DWM timing fix) ───────────────
    /**
     * Number of render frames remaining before the countdown clock starts.
     *
     * Set to GameConfig.COUNTDOWN_WARMUP_FRAMES in onLock() and decremented
     * once per frame inside updateCountdownAndGameState(). When it reaches 0,
     * startTimestamp is set and the countdown begins.
     *
     * This anchors countdown start to the rendering pipeline rather than to
     * OS event timing, ensuring the WebGL canvas is composited on screen
     * before the first tick fires — fixing premature beeps on Windows.
     */
    private _warmupFramesRemaining: number = 0;

    // ── Concurrency control ─────────────────────────────────────────
    /** Timeout ID for the CLEANING_UP retry in initialize(), so it can be cancelled. */
    private _reinitTimeoutId: ReturnType<typeof setTimeout> | null = null;

    // ── Cached callbacks ────────────────────────────────────────────
    private readonly _cachedTargetCallbacks: TargetStatisticsCallbacks;

    constructor() {
        // Wire state machine transitions to emit events
        this.stateMachine.onStateChange((oldState: GameStateValue, newState: GameStateValue, context: Record<string, unknown>) => {
            this._emitter.emit(GameEvents.STATE_CHANGED, { oldState, newState, context });
        });

        // Cached callbacks object for TargetManager — avoids creating new closures every frame.
        this._cachedTargetCallbacks = {
            startTargetTracking: (): void => this.aimAnalysis.reset(),
            startTargetMetrics: (
                targetPosition: THREE.Vector3,
                cameraPosition: THREE.Vector3,
                initialAngleDeg: number,
                targetRadius: number,
            ): void => {
                this.statistics.startTargetMetrics(targetPosition, cameraPosition, initialAngleDeg, targetRadius);
            },
        };
    }

    /**
     * Register an event handler for a game event.
     * @param event - Event name from GameEvents
     * @param handler - Callback function
     */
    on<K extends keyof GameEventMap>(event: K, handler: (payload: GameEventMap[K]) => void): void {
        this._emitter.on(event, handler);
    }

    /**
     * Remove a previously registered event handler.
     * @param event - Event name from GameEvents
     * @param handler - The exact handler reference passed to on()
     */
    off<K extends keyof GameEventMap>(event: K, handler: (payload: GameEventMap[K]) => void): void {
        this._emitter.off(event, handler);
    }

    /**
     * Get the current game state.
     * @returns Current game state from GameState enum
     */
    getState(): GameStateValue {
        return this.stateMachine.currentState;
    }

    /**
     * Derives whether the player can fire from the state machine.
     * True only during the PLAYING state.
     * @returns Whether the player can fire
     */
    private _canFire(): boolean {
        return this.stateMachine.is(GameState.PLAYING);
    }

    initialize(): void {
        // Prevent initialization during cleanup
        if (this.stateMachine.is(GameState.CLEANING_UP)) {
            logWarning('DpiTester - Main - Cannot initialize during cleanup, retrying...', null);
            this._reinitTimeoutId = setTimeout(() => {
                this._reinitTimeoutId = null;
                this.initialize();
            }, GameConfig.REINITIALIZATION_RETRY_MS);
            return;
        }

        if (this.graphics.isReady) {
            logWarning('DpiTester - Main - Game already initialized', null);
            return;
        }

        // Prevent concurrent initialization attempts
        if (this.stateMachine.is(GameState.INITIALIZING)) {
            logWarning('DpiTester - Main - Initialization already in progress', null);
            return;
        }

        this.stateMachine.transitionTo(GameState.INITIALIZING);

        // Recreate audioEngine if it was cleaned up
        if (!this.audioEngine) {
            this.audioEngine = new AudioEngine();
        }

        // Initialize graphics subsystem (scene, renderer, camera, composer, DOM)
        const graphicsReady: boolean = this.graphics.init({
            playerHeight: this.playerController.getHeight(),
            onUpdate: this.onUpdate,
            shouldAbort: () => this.stateMachine.is(GameState.CLEANING_UP),
        });

        if (!graphicsReady || !this.graphics.isReady) {
            logError('DpiTester - Main - Critical initialization failure: graphics not ready', null);
            this.stateMachine.transitionTo(GameState.UNINITIALIZED);
            return;
        }

        try {
            this.setupControls();
        } catch (error) {
            logError('DpiTester - Main - Failed to setup controls', { error });
            this.stateMachine.transitionTo(GameState.UNINITIALIZED);
            return;
        }

        // Initialize the various services needed to run the game
        if (this.audioEngine && this.graphics.camera) {
            this.audioEngine.initialize(this.graphics.camera);
            // Load SFX once at engine init so all audio buffers are fully decoded
            // before the first play starts.
            this.audioEngine.loadSFX();
        } else {
            logError('DpiTester - Main - Failed to initialize audioEngine', { audioEngine: !!this.audioEngine, camera: !!this.graphics.camera });
        }

        // Create HUD DOM elements and reset progress
        this.hud.create();
        this.hud.resetProgress();

        this.inputManager.resetClick();
        this.stateMachine.transitionTo(GameState.READY);
    }

    startGame(): void {
        // startGame() is the entry point for the very first play of a session.
        // It is only valid from READY state (reached once after engine initialization).
        // Subsequent plays go through resetMatch() → RESETING → COUNTDOWN directly.
        if (!this.stateMachine.is(GameState.READY)) {
            logInfo('DpiTester - Main - startGame() only valid from READY state', { state: this.getState() });
            return;
        }

        // Check if pointer lock is already active
        if (document.pointerLockElement) {
            logInfo('DpiTester - Main - Pointer lock already active', null);
            return;
        }

        if (!this.controlsManager.isReady) {
            logWarning('DpiTester - Main - Controls not ready for pointer lock', null);
            return;
        }

        this.controlsManager.requestLock();
    }

    setDpi(dpi: string | null): void {
        this.statistics.setDpiX(dpi);
    }

    private setupControls(): void {
        if (!this.graphics.camera || !this.graphics.scene) {
            throw new Error('Graphics camera and scene must be initialized before controls');
        }

        this.controlsManager.init(this.graphics.camera, this.graphics.scene, {
            /**
             * onLock — fires on pointer lock acquisition.
             * Starts the render loop, sets up canvas/HUD/audio/input, and arms
             * _warmupFramesRemaining so the render loop sets startTimestamp only
             * after N frames are composited on screen.
             * First play: READY → COUNTDOWN. Subsequent: RESETING → COUNTDOWN.
             */
            onLock: (): void => {
                // Reset prevTime immediately before starting the render loop so that the
                // first frame delta in updateMovement is near-zero instead of reflecting
                // the (potentially minutes-long) gap between class construction and lock
                // acquisition. Without this reset, prevTime stays at the value set during
                // construction (~performance.now() at page load), and the first call to
                // updateMovement computes delta = (now - constructionTime) / 1000 — which
                // can be tens of seconds, causing a massive velocity spike and teleport.
                this.prevTime = performance.now();

                // Resume the render loop first — it was stopped in onUnlock (or never
                // started on first play) to avoid GPU work while instructions are visible.
                this.graphics.startLoop();

                // Show the WebGL canvas now that the game is actively running.
                // It was hidden at init time to prevent a flash of instructions panel.
                this.graphics.showCanvas();
                this.hud.show();
                // Resume the AudioContext if it was suspended by the browser since
                // initialization (e.g. due to inactivity or user focus change).
                // SFX are NOT reloaded here — buffers were decoded once in initialize().
                if (this.audioEngine?.listener) {
                    this.audioEngine.resumeAudioContext();
                }
                this.inputManager.initTimestamp();
                // Only transition to COUNTDOWN from valid pre-play states.
                if (this.stateMachine.isAnyOf(GameState.READY, GameState.RESETING)) {
                    this.stateMachine.transitionTo(GameState.COUNTDOWN);
                }
                // Arm the warmup frame counter. The render loop (onUpdate →
                // updateCountdownAndGameState) decrements this each frame; startTimestamp
                // is set on the first frame after the counter reaches zero.
                // onUpdate is gated on controlsManager.isLocked, so the counter only
                // starts decrementing once pointer lock is confirmed acquired.
                this._warmupFramesRemaining = GameConfig.COUNTDOWN_WARMUP_FRAMES;
            },
            onUnlock: (): void => {
                // Hide the WebGL canvas so it is not visible behind the instructions panel.
                this.graphics.hideCanvas();
                // Stop the render loop — no need to composite a 3D scene at 60fps while
                // the instructions panel is shown. This frees the main thread for React
                // event handling (sliders, checkboxes, buttons), eliminating the ~1s UI
                // lag that accumulated after each play.
                this.graphics.stopLoop();
                this.hud.hide();
                // User cancelled (ESC pressed during active play) → CANCELLED state.
                // GAME_OVER unlock is triggered by checkGameOver() → controlsManager.unlock();
                if (this.stateMachine.isAnyOf(GameState.PLAYING, GameState.COUNTDOWN)) {
                    this.stateMachine.transitionTo(GameState.CANCELLED);
                }
            },
            onAcquisitionFailed: (): void => {
                // Only tear down the engine if lock failure was unexpected.
                // CANCELLED: user pressed ESC intentionally — acquisition timeout firing
                // after an intentional unlock is a false positive, not a real failure.
                // GAME_OVER: checkGameOver() unlocks intentionally — same false positive.
                // CLEANING_UP / UNINITIALIZED: cleanup already in progress or done.
                if (!this.stateMachine.isAnyOf(
                    GameState.CANCELLED,
                    GameState.GAME_OVER,
                    GameState.CLEANING_UP,
                    GameState.UNINITIALIZED,
                )) {
                    logWarning('DpiTester - Main - Pointer lock acquisition failed, cleaning up', { state: this.getState() });
                    this.cleanUp().catch((error: unknown) => {
                        logError('DpiTester - Main - Failed to clean up after acquisition failure', { error });
                    });
                }
            },
        });

        // Delegate input event registration to InputManager
        this.inputManager.attachListeners();

        // Wire up fire sound callback — InputManager calls this on valid clicks
        this.inputManager.setOnValidClick((): void => {
            if (this._canFire() && this.audioEngine) {
                this.audioEngine.playFireSound();
            }
        });

        // Wire up Escape key callback — InputManager calls this on Escape press during active play.
        // ESC only releases the pointer lock; it does NOT tear down the engine.
        // onUnlock fires next and transitions to CANCELLED.
        // Full engine teardown (CLEANING_UP) only happens on component unmount via cleanUp().
        this.inputManager.setOnEscapePressed((): void => {
            if (this.stateMachine.isAnyOf(GameState.COUNTDOWN, GameState.PLAYING)) {
                this.controlsManager.unlock();
            }
        });
    }

    /** The update loop of the game */
    private onUpdate = (): void => {
        // Early catch for rendering issues
        if (this.stateMachine.is(GameState.CLEANING_UP) || !this.graphics.isReady) {
            return;
        }

        const time: number = performance.now();

        if (this.controlsManager.isLocked && this.graphics.scene) {
            this.updateGameplay(time);
            this.checkGameOver();
        }

        // Finalize update
        this.prevTime = time;
        this.graphics.render();
    };

    private updateGameplay(time: number): void {
        // --- Phase 1: Movement ---
        this.updateMovement(time);

        // --- Phase 2: Aim tracking ---
        const targetInScene: THREE.Mesh | null = this.targetManager.getTargetMesh();
        if (this._canFire() && targetInScene && this.graphics.camera) {
            this.aimAnalysis.update(time, this.graphics.camera, targetInScene.position);
        }

        // --- Phase 3: Shot processing ---
        const targetIsHit: boolean = this.processShot(time);

        // --- Phase 4: Target state ---
        this.updateTargetState(time);

        // Update last camera position for next frame
        this.graphics.updateCameraTracking();
        this.updateHUD(targetIsHit);

        this.inputManager.resetClick();

        this.updateCountdownAndGameState(time);
    }

    /**
     * Phase 1: Updates player movement based on input and delta time.
     */
    private updateMovement(time: number): void {
        if (this.playerController.canMove()) {
            this.inputManager.updateKeyInputs();
        }
        const delta: number = (time - this.prevTime) / 1000;
        const movementState = this.inputManager.getMovementState();
        this.playerController.update(delta, movementState, this.controlsManager.controls as PlayerControls);
    }

    /**
     * Phase 2: Processes shooting — hit/miss detection and handling.
     * @returns Whether the target was hit this frame
     */
    private processShot(time: number): boolean {
        if (!this.graphics.camera) return false;

        const isHoveringTarget: boolean = this.targetManager.checkHover(this.graphics.camera);
        let targetIsHit = false;

        // Performance optimization: Direct check instead of loop
        if (isHoveringTarget && this.inputManager.isClicked && this._canFire()) {
            const { hasOvershoot, hasUndershoot }: AimAnalysisResult = this.aimAnalysis.getResult();

            const isPerfectHit: boolean = !hasOvershoot && !hasUndershoot;
            if (isPerfectHit) this.statistics.recordPerfectHit();
            if (hasUndershoot) this.statistics.recordUndershoot();
            if (hasOvershoot) this.statistics.recordOvershoot();

            logInfo('DpiTester - Main - [Shot result recorded]', {
                result: isPerfectHit ? 'perfect' : (hasUndershoot && hasOvershoot) ? 'under+over' : hasUndershoot ? 'undershoot' : 'overshoot',
                shotNumber: this.statistics.getHitTargets() + this.statistics.getMissedTargets(),
            }, true);

            const hitDistance: number | null = this.targetManager.getHitDistance();
            this.statistics.completeTargetMetrics(true, hitDistance);

            targetIsHit = true;
        }

        this.targetManager.updateRingColor(isHoveringTarget, this._canFire());

        if (this.audioEngine) {
            this.playerController.teleportIfTooFar(this.controlsManager.controls as PlayerControls, this.audioEngine);
        }

        // Handle target hit
        if (targetIsHit) {
            this.handleTargetHit(time);
        }

        // Handle target miss
        if (!targetIsHit && this._canFire() && this.inputManager.isClicked) {
            this.handleTargetMiss();
        }

        return targetIsHit;
    }

    /**
     * Phase 3: Updates target lifecycle — creation and transform.
     */
    private updateTargetState(time: number): void {
        // Create initial target if playing and none exists
        if (this._canFire() && !this.targetManager.getTargetMesh() && this.graphics.isReady && this.graphics.scene && this.graphics.camera) {
            this.targetManager.createInitial(this.graphics.scene, this.graphics.camera, this._targetStatsCallbacks());
        }

        if (this.graphics.camera) {
            this.targetManager.updateTransform(time, this.graphics.camera, this.graphics.lastCameraPosition, this.graphics.cameraMovementThreshold, this._targetStatsCallbacks());
        }
    }

    private handleTargetHit(time: number): void {
        if (!this.graphics.camera) return;

        this.targetManager.relocateTarget(time, this.graphics.camera);

        // The player hit the target
        this.statistics.incrementHitTargets();

        // Start recording session time on the very first hit (called once)
        if (this.statistics.getHitTargets() === 1) {
            this.statistics.startRecordingTime();
        }

        if (this.audioEngine) {
            this.audioEngine.playHitSound(this.statistics.getKillStreak());
        }

        // Note: aimAnalysis.reset() is handled by TargetManager via _cachedTargetCallbacks.startTargetTracking
        // when the lerp animation completes (relocateTarget → updateLerp → callbacks.startTargetTracking).
    }

    private handleTargetMiss(): void {
        const { hasOvershoot, hasUndershoot }: AimAnalysisResult = this.aimAnalysis.getResult();

        // Complete Fitts' Law metrics for this target (miss)
        this.statistics.completeTargetMetrics(false, null);

        this.statistics.incrementMissedTargets();
        this.targetManager.flashMiss();
        this.audioEngine?.playMissSound();

        this.statistics.recordMissedShot();
        if (hasUndershoot) this.statistics.recordUndershoot();
        if (hasOvershoot) this.statistics.recordOvershoot();

        logInfo('DpiTester - Main - [Shot result recorded]', {
            result: (hasUndershoot && hasOvershoot) ? 'miss:under+over' : hasUndershoot ? 'miss:undershoot' : hasOvershoot ? 'miss:overshoot' : 'miss:perfect',
            shotNumber: this.statistics.getHitTargets() + this.statistics.getMissedTargets(),
        }, true);

        // Reset aim analysis immediately for misses (no lerp animation to trigger callback)
        this.aimAnalysis.reset();
    }

    /**
     * Returns the cached statistics callbacks object for TargetManager.
     * Cached in the constructor to avoid creating new closures every frame.
     */
    private _targetStatsCallbacks(): TargetStatisticsCallbacks {
        return this._cachedTargetCallbacks;
    }

    private updateHUD(isHit: boolean): void {
        // Performance optimization: Only update HUD when state changes
        const targetIndex: number = (this.statistics.getHitTargets() + this.statistics.getMissedTargets()) - 1;
        if (targetIndex < this.gameLength && this.inputManager.isClicked && this._canFire() && targetIndex !== this.lastTargetIndex) {
            this.lastTargetIndex = targetIndex;
            this.hud.updateProgress(targetIndex, isHit);
        }
    }

    private updateCountdownAndGameState(time: number): void {
        // Phase 1 — Warmup gate: skip N frames after pointer lock so the canvas is
        // composited on screen before the first countdown tick (Windows DWM fix).
        // Only active while startTimestamp === null; falls through to Phase 2 once set.
        if (this.stateMachine.is(GameState.COUNTDOWN) && this.startTimestamp === null) {
            if (this._warmupFramesRemaining > 0) {
                this._warmupFramesRemaining--;
                return;
            }

            this.startTimestamp = time;
            // Clear dedup guard so the "3" beep fires fresh each session.
            this.lastCountdownValue = null;
        }

        // Phase 2 — Countdown tick (runs every frame once startTimestamp is set).
        if (this.stateMachine.is(GameState.COUNTDOWN) && this.startTimestamp !== null) {
            this.updateStartCountdown(time - this.startTimestamp);

            if ((time - this.startTimestamp) >= COUNTDOWN_DURATION_MS) {
                // Transition to playing state — _canFire() derives from PLAYING state
                this.stateMachine.transitionTo(GameState.PLAYING);
            }
        }
    }

    private checkGameOver(): void {
        // Check if this is game over (20 shots in total)
        if (this.stateMachine.is(GameState.PLAYING) &&
            (this.statistics.getHitTargets() + this.statistics.getMissedTargets()) >= this.gameLength) {

            this.stateMachine.transitionTo(GameState.GAME_OVER);
            this.statistics.stopRecordingTime();

            // Create the statistics report
            const data = this.statistics.compile();
            this._emitter.emit(GameEvents.STATISTICS, data);
            this.statistics.reset();

            // Bring the user to the main menu
            this.controlsManager.unlock();
        }
    }

    private updateStartCountdown(elapsedMs: number): void {
        const stepIndex: number = Math.min(
            Math.floor(elapsedMs / GameConfig.COUNTDOWN_STEP_MS),
            COUNTDOWN_STEPS.length - 1,
        );
        const activeStep: CountdownStep = COUNTDOWN_STEPS[stepIndex];
        const newCountdownValue: string = activeStep.display;

        if (this.lastCountdownValue === newCountdownValue) return;

        this.lastCountdownValue = newCountdownValue;
        this.hud.updateCountdown(newCountdownValue);

        if (this.audioEngine) {
            this.audioEngine.playCountdownSound(activeStep.detune);
        }
    }

    /**
     * Resets match-specific state for a new game session without reinitializing the engine.
     * Valid when state is CANCELLED or GAME_OVER.
     *
     * Flow: CANCELLED/GAME_OVER → RESETING → (pointer lock requested) → COUNTDOWN
     *
     * Use this instead of cleanUp() + initialize() for rapid restarts.
     * Stats reset happens here; onLock only drives the RESETING → COUNTDOWN transition.
     */
    public resetMatch(): void {
        if (!this.stateMachine.isAnyOf(GameState.CANCELLED, GameState.GAME_OVER)) {
            logWarning('[TargetPracticeGame] resetMatch() called in invalid state', {
                state: this.getState(),
            });
            return;
        }

        // Enter RESETING — clears match data without tearing down the engine.
        this.stateMachine.transitionTo(GameState.RESETING);

        // Remove existing target meshes from the scene before clearing references,
        // so the old target is not visible in the next session.
        if (this.graphics.scene) {
            this.targetManager.removeFromScene(this.graphics.scene);
        }
        this.statistics.reset();
        this.targetManager.clearMeshReferences();
        this.hud.resetProgress();
        this.lastCountdownValue = null;
        this.lastTargetIndex = -1;
        this.startTimestamp = null;
        this._warmupFramesRemaining = 0;

        // Cancel any pending acquisition timers from the previous lock request before
        this.controlsManager.cancelAcquisition();

        // Request pointer lock — on success, onLock fires: RESETING → COUNTDOWN
        this.controlsManager.requestLock();
    }

    async cleanUp(): Promise<void> {
        // Cancel any pending reinitialization retry to avoid a stale initialize() call
        // firing after cleanup completes.
        if (this._reinitTimeoutId !== null) {
            clearTimeout(this._reinitTimeoutId);
            this._reinitTimeoutId = null;
        }

        // Only transition to CLEANING_UP if we're not already UNINITIALIZED or CLEANING_UP
        if (!this.stateMachine.isAnyOf(GameState.UNINITIALIZED, GameState.CLEANING_UP)) {
            this.stateMachine.transitionTo(GameState.CLEANING_UP);
        } else if (this.stateMachine.is(GameState.UNINITIALIZED)) {
            logInfo('DpiTester - Main - Already in UNINITIALIZED state, skipping cleanup', null);
            return;
        } else {
            logInfo('DpiTester - Main - Cleanup already in progress', null);
            return;
        }

        try {
            // Clean up controls (pointer lock, event listeners, timers)
            this.controlsManager.dispose();

            // Detach input listeners
            this.inputManager.detachListeners();

            // Dispose audio engine
            if (this.audioEngine) {
                try {
                    this.audioEngine.dispose();
                } catch (e) {
                    logWarning('DpiTester - Main - Failed to dispose audio engine', { error: e });
                }
            }

            // Dispose graphics subsystem (renderer, scene, composer, DOM, resize listener)
            await this.graphics.dispose();

            // Reset gameplay state
            this.inputManager.resetClick();

            // Clear cached references
            this.targetManager.clearMeshReferences();
            this.lastTargetIndex = -1;
            this.lastCountdownValue = null;
            this._warmupFramesRemaining = 0;

            // Dispose HUD DOM elements
            this.hud.dispose();

            // Recreate graphics context for potential re-initialization
            this.graphics = new GraphicsContext();
            this.audioEngine = null;
        } finally {
            // Only transition to UNINITIALIZED if we're in CLEANING_UP state
            if (this.stateMachine.is(GameState.CLEANING_UP)) {
                this.stateMachine.transitionTo(GameState.UNINITIALIZED);
            }

            // Remove all event listeners to prevent memory leaks
            this._emitter.removeAllListeners();
        }
    }
}
