import { FocusScope } from '@react-aria/focus';
import { DpiCanvas } from 'modules/device/components/dpi-canvas';
import { BodyText, Heading } from 'modules/base/components/typography';
import { getLang } from 'modules/base';

import GameInstructionActions from './GameInstructionActions';
import GameStatisticsPanel from './GameStatisticsPanel';
import CrosshairBold from '../game/resources/textures/image.png';
import Preview from '../game/resources/video/task_visualizer.webm';
import { StatisticsEntry } from '../game/types';

const { STRING, STRINGS } = getLang();

interface GameInstructionPopupProps {
    statsHistory: StatisticsEntry[],
    recommendation: string;
    onStartGame: () => void,
    isPlayDisabled?: boolean;
}

function GameInstructionsPopup({ statsHistory, onStartGame, recommendation, isPlayDisabled }: GameInstructionPopupProps) {
    const hasStatisticsData = !!statsHistory.length;
    const description = hasStatisticsData
        ? STRING(STRINGS.DPI_TESTER_DESCRIPTION_WITH_STATS)
        : STRING(STRINGS.DPI_TESTER_DESCRIPTION);

    return (
        <div className="dpi-tester-blocker">
            <FocusScope contain restoreFocus>
                <div
                    className="dpi-tester-instructions"
                    role="dialog"
                    aria-labelledby="dpi-tester-title"
                    data-testid="dpi-tester-instructions"
                >
                    <div className="instructions-content g-d-flex g-space-between width-100">
                        <div className="instructions-main">
                            <div className="instructions-content">
                                <div className="instructions-header">
                                    <Heading level={1} id="dpi-tester-title" className="dpi-tester-title" data-testid="dpi-tester-title">
                                        {STRING(STRINGS.DPI_TESTER_TITLE)}
                                    </Heading>
                                    <BodyText tag="p" level={2} className="instructions-description" data-testid="dpi-tester-description">
                                        {description}
                                    </BodyText>
                                </div>

                                <DpiCanvas showOnlySensitivity />
                            </div>
                        </div>

                        {!statsHistory.length && (
                            <div
                                className="visualizer-container"
                                data-testid="dpi-tester-visualizer"
                            >
                                <video
                                    autoPlay
                                    muted
                                    loop
                                    aria-label={STRING(STRINGS.DPI_TESTER_PREVIEW_VIDEO_LABEL)}
                                    data-testid="dpi-tester-preview-video"
                                >
                                    <source src={Preview} type="video/webm" />
                                </video>
                                <div className="visualizer-overlay">
                                    <img
                                        className="overlay-image"
                                        src={CrosshairBold}
                                        alt={STRING(STRINGS.DPI_TESTER_CROSSHAIR_ALT)}
                                    />
                                    <BodyText tag="p" className="overlay-text" data-testid="dpi-tester-visualizer-text">
                                        {STRING(STRINGS.DPI_TESTER_VISUALIZER_INSTRUCTION, { LINE_BREAK: <br /> })}
                                    </BodyText>
                                </div>
                            </div>
                        )}

                        {!!statsHistory.length && (
                            <GameStatisticsPanel
                                statsHistory={statsHistory}
                                recommendation={recommendation}
                            />
                        )}
                    </div>

                    <GameInstructionActions onStartGame={onStartGame} isPlayDisabled={isPlayDisabled} />
                </div>
            </FocusScope>
        </div>
    );
}

export default GameInstructionsPopup;
