/**
 * FittsLaw - Fitts' Law calculations (ISO 9241-9)
 */

/** Data point for Fitts' Law regression (ID vs MT) */
interface FittsDataPoint {
    id: number;
    mt: number;
}

/** Prediction result from linear regression */
interface RegressionPrediction {
    id: number;
    actual: number;
    predicted: number;
    residual: number;
}

/** Result of Fitts' Law linear regression */
export interface FittsRegressionResult {
    /** Intercept (baseline time) */
    a: number;
    /** Slope (time per bit of difficulty) */
    b: number;
    /** R-squared (0-1, higher = better fit) */
    r2: number;
    /** Number of data points */
    n: number;
    /** Mean Index of Difficulty */
    meanID?: number;
    /** Mean Movement Time */
    meanMT?: number;
    /** Predictions for each data point */
    predictions: RegressionPrediction[];
}

/** Target data for Fitts' Law analysis */
interface FittsTargetData {
    distance: number;
    width: number;
    movementTime: number;
    hitDistance?: number | null;
}

/** Result of Fitts' Law session analysis */
export interface FittsAnalysisResult {
    throughput: number;
    averageID: number;
    averageMT: number;
    effectiveWidth: number;
    regression?: FittsRegressionResult;
}

export class FittsLaw {
    // ISO 9241-9 constant for effective width calculation
    static EFFECTIVE_WIDTH_MULTIPLIER = 4.133;

    /**
     * Calculate mean (average) of a dataset
     * @param values - Array of numeric values
     * @returns {number} Mean
     */
    static calculateMean(values: number[]): number {
        if (!values || values.length === 0) {
            return 0;
        }
        return values.reduce((sum, val) => sum + val, 0) / values.length;
    }

    /**
     * Calculate standard deviation of a dataset
     * @param values - Array of numeric values
     * @returns {number} Standard deviation
     */
    static calculateStdDev(values: number[]): number {
        if (!values || values.length === 0) {
            return 0;
        }
        const mean: number = values.reduce((sum, val) => sum + val, 0) / values.length;
        const squaredDifferences: number[] = values.map(val => (val - mean) ** 2);
        const variance: number = squaredDifferences.reduce((sum, val) => sum + val, 0) / values.length;
        return Math.sqrt(variance);
    }

    /**
     * Calculate Index of Difficulty (ID) using Fitts' Law
     * ID = log₂(D/W + 1) where D = distance, W = width
     * @param distance - Distance to target (in any unit)
     * @param width - Target width (same unit as distance)
     * @returns {number} Index of Difficulty in bits
     */
    static calculateIndexOfDifficulty(distance: number, width: number): number {
        if (!distance || !width || distance <= 0 || width <= 0) {
            return 0;
        }

        // Natural log of 2 for converting to base-2 logarithm
        const LOG2: number = Math.log(2);
        return Math.log((distance / width) + 1) / LOG2;
    }

    /**
     * Calculate effective target width (We) from hit distribution
     * We = 4.133 × SDx (ISO 9241-9 standard)
     * @param hitDistances - Array of radial distances from target center
     * @returns {number} Effective width
     */
    static calculateEffectiveWidth(hitDistances: number[]): number {
        if (!hitDistances || hitDistances.length < 2) {
            return 0;
        }

        return FittsLaw.EFFECTIVE_WIDTH_MULTIPLIER * FittsLaw.calculateStdDev(hitDistances);
    }

    /**
     * Calculate effective Index of Difficulty (IDe)
     * IDe = log₂(D/We + 1) where We = effective width from actual performance
     * @param distance - Distance to target
     * @param effectiveWidth - Effective width from hit distribution
     * @returns {number} Effective Index of Difficulty in bits
     */
    static calculateEffectiveID(distance: number, effectiveWidth: number): number {
        return FittsLaw.calculateIndexOfDifficulty(distance, effectiveWidth);
    }

    /**
     * Calculate throughput (TP) according to ISO 9241-9
     * TP = IDe / MT where MT = movement time
     * @param effectiveID - Effective Index of Difficulty
     * @param movementTime - Time to complete movement (in seconds)
     * @returns {number} Throughput in bits/second
     */
    static calculateThroughput(effectiveID: number, movementTime: number): number {
        if (!movementTime || movementTime <= 0 || !effectiveID) {
            return 0;
        }

        return effectiveID / movementTime;
    }

    /**
     * Perform linear regression for Fitts' Law
     * MT = a + b × ID
     * Returns coefficients a (intercept) and b (slope), plus R² for model quality
     * @param dataPoints - Array of {id, mt} objects
     * @returns {FittsRegressionResult} Regression results
     */
    static fittsLawRegression(dataPoints: FittsDataPoint[]): FittsRegressionResult {
        if (!dataPoints || dataPoints.length < 2) {
            return {
                a: 0, // Intercept
                b: 0, // Slope
                r2: 0, // R-squared (goodness of fit)
                n: 0,
                predictions: [],
            };
        }

        const n: number = dataPoints.length;
        const ids: number[] = dataPoints.map(p => p.id);
        const mts: number[] = dataPoints.map(p => p.mt);

        // Calculate means
        const meanID: number = FittsLaw.calculateMean(ids);
        const meanMT: number = FittsLaw.calculateMean(mts);

        const POWER_FOR_SQUARED = 2;
        // Calculate slope (b)
        let numerator = 0;
        let denominator = 0;
        for (let i = 0; i < n; i++) {
            numerator += (ids[i] - meanID) * (mts[i] - meanMT);
            denominator += (ids[i] - meanID) ** POWER_FOR_SQUARED;
        }

        const b: number = denominator !== 0 ? numerator / denominator : 0;
        const a: number = meanMT - (b * meanID);

        // Calculate R² (coefficient of determination)
        let ssRes = 0; // Sum of squared residuals
        let ssTot = 0; // Total sum of squares
        const predictions: RegressionPrediction[] = [];

        for (let i = 0; i < n; i++) {
            const predicted: number = a + (b * ids[i]);
            predictions.push({
                id: ids[i],
                actual: mts[i],
                predicted,
                residual: mts[i] - predicted,
            });

            ssRes += (mts[i] - predicted) ** POWER_FOR_SQUARED;
            ssTot += (mts[i] - meanMT) ** POWER_FOR_SQUARED;
        }

        const r2: number = ssTot !== 0 ? 1 - (ssRes / ssTot) : 0;

        return {
            a, // Intercept (baseline time)
            b, // Slope (time per bit of difficulty)
            r2, // R-squared (0-1, higher = better fit)
            n,
            meanID,
            meanMT,
            predictions,
        };
    }

    /**
     * Calculate Fitts' Law analysis for a session
     * @param targets - Array of target data with distance, width, and movementTime
     * @returns {FittsAnalysisResult} Fitts' Law metrics
     */
    static analyzeFittsLaw(targets: FittsTargetData[]): FittsAnalysisResult {
        if (!targets || targets.length === 0) {
            return { throughput: 0, averageID: 0, averageMT: 0, effectiveWidth: 0 };
        }

        // Calculate nominal ID for each target
        const ids: number[] = targets.map(t => FittsLaw.calculateIndexOfDifficulty(t.distance, t.width));
        const avgID: number = FittsLaw.calculateMean(ids);
        const avgMT: number = FittsLaw.calculateMean(targets.map(t => t.movementTime));
        const avgDistance: number = FittsLaw.calculateMean(targets.map(t => t.distance));

        // Calculate effective width from hit distribution
        const hitDistances: number[] = targets.map(t => t.hitDistance).filter(
            (d): d is number => d !== undefined && d !== null && isFinite(d),
        );
        const effectiveWidth: number = FittsLaw.calculateEffectiveWidth(hitDistances);

        // Calculate throughput using effective ID (ISO 9241-9)
        // Note: effectiveWidth > 0 check prevents division by zero in calculateIndexOfDifficulty
        let throughput = 0;
        if (effectiveWidth > 0 && avgMT > 0) {
            const effectiveID: number = FittsLaw.calculateIndexOfDifficulty(avgDistance, effectiveWidth);
            throughput = effectiveID / avgMT;
        }

        // Perform linear regression MT = a + b × ID
        const regressionData: FittsDataPoint[] = targets.map(t => ({
            id: FittsLaw.calculateIndexOfDifficulty(t.distance, t.width),
            mt: t.movementTime,
        }));
        const regression: FittsRegressionResult = FittsLaw.fittsLawRegression(regressionData);

        return {
            throughput,
            averageID: avgID,
            averageMT: avgMT,
            effectiveWidth,
            regression,
        };
    }
}
