import { logWarning } from 'logger/log';
import { BaseEventAnalyzer, AnalyzerEvent } from './BaseEventAnalyzer';
import { MovementPhaseAnalysis, DETECTION_CONSTANTS } from './MovementPhaseAnalysis';

/** Shape of a movement data sample for undershoot analysis */
interface UndershootDataPoint {
    signedErrorRaw?: number;
    timestamp?: number;
}

/** Internal undershoot event with extended metrics */
interface UndershootEvent {
    amplitude: number;
    direction: number;
    shortfall_deg?: number;
    correction_time_ms?: number;
    correction_peak_v?: number;
    peakAmplitude?: number;
    detectionMethod?: string;
    movementStartIndex?: number | null;
    analysisWindow?: { start: number; end: number } | null;
    timestamp: number;
    peakIndex?: number;
}

/**
 * Handles undershoot detection.
 *
 * Method: Raw velocity pause detection with movement bounds
 * - Uses raw signedErrorRaw data (no filtering for performance)
 * - Movement onset detection (first local velocity peak > 0.05 * v_peak)
 * - Research-standard velocity gate (v_eps = 0.05 * v_peak, τ = 40ms)
 * - Bounded backward scanning (movement start ← → target entry)
 *
 * Assumes:
 *  - signedErrorRaw(t) = u·(p(t)-p0) - D  (task-axis projection per ISO 9241-9)
 *  - getAngularToleranceDeg() returns target half-width W/2 in degrees
 *  - Undershoot = primary endpoint that pauses outside target, then corrects to enter
 */
export class UndershootAnalyzer extends BaseEventAnalyzer {
    /**
     * Detect undershoot events using research-based velocity pause detection.
     *
     * Algorithm:
     *  1) Use raw signedErrorRaw data
     *  2) Calculate velocity: v(t) = -de/dt
     *  3) Find v_peak and set v_eps = 0.05 * v_peak (research-standard velocity gate)
     *  4) Find first entry: |e(t)| ≤ W/2
     *  5) Scan backward from entry for paused endpoint outside band
     *  6) Validate: pause ≥ 40ms AND movement resumption toward target
     *  7) Calculate metrics: shortfall_deg, correction_time_ms, correction_peak_v
     */
    detectUndershoots(data: UndershootDataPoint[], targetHalfWidth: number): number[] {
        const hits: number[] = [];
        if (!this._validateData(data)) {
            return hits;
        }

        const tol: number = targetHalfWidth;
        if (!Number.isFinite(tol) || tol <= 0) {
            logWarning('[UndershootAnalyzer] Invalid targetHalfWidth:', targetHalfWidth, true);
            return hits;
        }

        // One-shot for live detection
        const events: UndershootEvent[] = this._detectUndershootEvents(data, tol, false);

        if (events.length > 0 && !this.eventDetected) {
            const event: UndershootEvent = events[0];
            const enhancedEvent: AnalyzerEvent = {
                amplitude: event.amplitude,
                direction: event.direction,
                shortfall_deg: event.shortfall_deg ?? event.amplitude,
                correction_time_ms: event.correction_time_ms,
                correction_peak_v: event.correction_peak_v,
                peakAmplitude: event.peakAmplitude ?? Math.abs(event.amplitude),
                detectionMethod: event.detectionMethod ?? 'legacy_geometric',
                movementStartIndex: event.movementStartIndex ?? null,
                analysisWindow: event.analysisWindow ?? null,
            };
            this._storeEvent(enhancedEvent, event.timestamp, hits, 'Undershoot', '#4ecdc4');
        }

        return hits;
    }

    // ---------- Internals ----------

    /**
     * Detect undershoot events using research-based velocity pause detection.
     * Pure implementation of the one-pass detector from motor control literature.
     * @param data - Data points to analyze
     * @param tol - Target tolerance (W/2)
     * @param allowMultiple - Allow multiple detections for visual analysis
     * @returns {UndershootEvent[]} Array of undershoot events
     */
    private _detectUndershootEvents(data: UndershootDataPoint[], tol: number, allowMultiple = false): UndershootEvent[] {
        const events: UndershootEvent[] = [];

        // Validate input data
        if (!data || data.length < 2) return events;

        // Use raw signedErrorRaw data (no filtering) for performance
        const e: number[] = data.map(d => d?.signedErrorRaw ?? 0);
        const t: number[] = data.map(d => d?.timestamp ?? 0);

        const v: number[] = MovementPhaseAnalysis.calculateVelocity(e, t);
        const vEps: number = MovementPhaseAnalysis.calculateResearchVelocityGate(v);
        const tMovementStart: number = MovementPhaseAnalysis.detectMovementOnsetByFirstPeak(v, vEps);

        // No significant movement detected
        if (tMovementStart < 0) return events;

        // Find first entry into target band: |e(t)| ≤ W/2
        let tEntry = -1;
        // Start search from movement onset
        for (let i = tMovementStart; i < e.length; i++) {
            if (Math.abs(e[i]) <= tol) {
                tEntry = i;
                break;
            }
        }

        // Handle truncated streams: if no entry found, still attempt detection
        // This allows detection of undershoots in incomplete data streams
        if (tEntry < 0) {
            // For truncated streams, use end of data as search boundary
            // Keep as -1 to signal truncated stream to the pause detection
            tEntry = -1;
        }

        // Use movement-bounded backward scanning for velocity pause detection
        const pauseResult = MovementPhaseAnalysis.scanBackwardForPausedEndpoint({
            e,
            v,
            timestamps: t,
            tEntry,
            tMovementStart,
            bandHalfWidth: tol,
            vEps,
            tauMs: DETECTION_CONSTANTS.PAUSE_DURATION_MS,
        });

        if (pauseResult.found) {
            const tP: number = pauseResult.t_p;
            const correctionPeakV: number = MovementPhaseAnalysis.calculateCorrectionPeakVelocity(v, tP, tEntry);

            if (correctionPeakV < vEps) {
                return events;
            }

            const event: UndershootEvent = {
                // Research-based metrics
                shortfall_deg: pauseResult.shortfall_deg,
                correction_time_ms: pauseResult.correction_time_ms,
                correction_peak_v: correctionPeakV,

                // Compatibility with existing system
                amplitude: pauseResult.shortfall_deg ?? 0,
                direction: this._inferApproachDirection(e, tP),
                timestamp: data[tP]?.timestamp ?? 0,
                peakIndex: tP,
                peakAmplitude: Math.abs(e[tP]),

                // Method indicator with movement bounds info
                detectionMethod: 'research_raw_velocity_pause_bounded',
                movementStartIndex: tMovementStart,
                analysisWindow: {
                    start: tMovementStart,
                    end: tEntry,
                },
            };

            events.push(event);

            if (!allowMultiple) {
                // One-shot detection for live mode
                return events;
            }
        }

        return events;
    }

    /**
     * Infer approach direction from error signal at pause point
     * @param e - Smoothed error values
     * @param tP - Pause point index
     * @returns {number} +1 for positive approach, -1 for negative approach
     */
    private _inferApproachDirection(e: number[], tP: number): number {
        // Default
        if (tP < 0 || tP >= e.length) return 1;
        // Sign of error at pause point
        return e[tP] > 0 ? 1 : -1;
    }
}
