import * as THREE from 'three';

/** Signed angle result for directional error analysis */
interface SignedAngles {
    yaw: number;
    pitch: number;
}

export class Utils {
    /**
     * Computes the angle (rad) between the camera's look at vector and a target
     * @param {THREE.Camera} camera - The camera
     * @param {THREE.Vector3} targetPosition - Target position
     * @returns {number} Angle in radians
     */
    static getCameraAngleToTarget(camera: THREE.Camera, targetPosition: THREE.Vector3): number {
        const cameraVector: THREE.Vector3 = new THREE.Vector3(0, 0, -1);
        cameraVector.applyQuaternion(camera.quaternion);
        cameraVector.normalize();

        const vectorTargetCamera: THREE.Vector3 = new THREE.Vector3().subVectors(camera.position, targetPosition);
        vectorTargetCamera.normalize();

        return Math.abs(cameraVector.angleTo(vectorTargetCamera) - Math.PI);
    }

    /**
     * Calculates signed angles for directional error analysis
     * Positive/negative indicates which side of target
     * @param {THREE.Camera} camera - The camera
     * @param {THREE.Vector3} targetPos - Target position
     * @returns {SignedAngles} Signed angles in degrees
     */
    static calculateSignedAngles(camera: THREE.Camera, targetPos: THREE.Vector3): SignedAngles {
        if (!camera || !targetPos) return { yaw: 0, pitch: 0 };

        const dir: THREE.Vector3 = new THREE.Vector3().subVectors(targetPos, camera.position).normalize();
        const q: THREE.Quaternion = new THREE.Quaternion();
        camera.getWorldQuaternion(q);
        q.invert();
        const local: THREE.Vector3 = dir.clone().applyQuaternion(q);
        const yawRad: number = Math.atan2(local.x, -local.z);
        const pitchRad: number = Math.atan2(local.y, Math.hypot(local.x, local.z));

        return {
            yaw: THREE.MathUtils.radToDeg(yawRad),
            pitch: THREE.MathUtils.radToDeg(pitchRad),
        };
    }
}
