import { MovementState } from './PlayerController';
import { GameConfig } from './Config';

/**
 * Callback invoked when a valid mouse click (left button, past rate-of-fire delay) occurs.
 * Main uses this to play the fire sound when canFire is true.
 */
export type MouseClickCallback = () => void;

/** Callback invoked when the Escape key is pressed during gameplay. */
export type EscapePressedCallback = () => void;

/**
 * InputManager owns all raw input state: keyboard key tracking,
 * mouse click tracking, and movement boolean derivation.
 *
 * It does NOT own game-level decisions like "can the player fire?"
 * or "should we play a sound?". Those remain in Main, which reads
 * InputManager's state each frame.
 */
export class InputManager {
    private readonly keyStates: Record<string, boolean> = {};
    private moveForward = false;
    private moveBackward = false;
    private moveLeft = false;
    private moveRight = false;
    private isSprinting = false;
    private _isClicked = false;
    private lastShotFiredTimestamp: number | null = null;
    private _onValidClick: MouseClickCallback | null = null;
    private _onEscapePressed: EscapePressedCallback | null = null;

    /**
     * Whether the left mouse button was clicked this frame.
     * Reset to false at the end of each frame by Main.
     */
    get isClicked(): boolean {
        return this._isClicked;
    }

    /**
     * Reset the click state at the end of each frame.
     * Called by Main after processing the click.
     */
    resetClick(): void {
        this._isClicked = false;
    }

    /**
     * Set a callback that fires on every valid mouse click
     * (left button, past rate-of-fire delay). Main uses this
     * to play the fire sound when canFire is true.
     */
    setOnValidClick(callback: MouseClickCallback | null): void {
        this._onValidClick = callback;
    }

    /**
     * Set a callback that fires when the Escape key is pressed.
     * Main uses this to abort the current game session.
     */
    setOnEscapePressed(callback: EscapePressedCallback | null): void {
        this._onEscapePressed = callback;
    }

    /**
     * Initialize the lastShotFiredTimestamp.
     * Called when controls are locked and the game session begins.
     */
    initTimestamp(): void {
        this.lastShotFiredTimestamp = performance.now();
    }

    /**
     * Reads the current key states and updates the movement booleans.
     * Should be called once per frame before getMovementState().
     */
    updateKeyInputs(): void {
        this.moveForward = !!this.keyStates.KeyW;
        this.moveBackward = !!this.keyStates.KeyS;
        this.moveLeft = !!this.keyStates.KeyA;
        this.moveRight = !!this.keyStates.KeyD;
        this.isSprinting = !!this.keyStates.ShiftLeft;
    }

    /**
     * Returns the current movement state from keyboard input.
     * Consumed by PlayerController.update() each frame.
     */
    getMovementState(): MovementState {
        return {
            forward: this.moveForward,
            backward: this.moveBackward,
            left: this.moveLeft,
            right: this.moveRight,
            sprinting: this.isSprinting,
        };
    }

    /**
     * Register keyboard and mouse event listeners on the document.
     */
    attachListeners(): void {
        document.addEventListener('mousedown', this._handleMouseDown);
        document.addEventListener('mouseup', this._handleMouseUp);
        document.addEventListener('keydown', this._handleKeyDown);
        document.addEventListener('keyup', this._handleKeyUp);
    }

    /**
     * Remove all event listeners registered by attachListeners().
     */
    detachListeners(): void {
        document.removeEventListener('mousedown', this._handleMouseDown);
        document.removeEventListener('mouseup', this._handleMouseUp);
        document.removeEventListener('keydown', this._handleKeyDown);
        document.removeEventListener('keyup', this._handleKeyUp);
        this._onEscapePressed = null;
    }

    // ── Private handlers ──────────────────────────────────────────

    private _handleKeyDown = (event: KeyboardEvent): void => {
        if (event.key === 'Escape') {
            event.preventDefault();
            event.stopPropagation();
            this._onEscapePressed?.();
            return;
        }
        this.keyStates[event.code] = true;
    };

    private _handleKeyUp = (event: KeyboardEvent): void => {
        this.keyStates[event.code] = false;
    };

    private _handleMouseDown = (event: MouseEvent): void => {
        // Left button only
        if (event.button !== 0) {
            return;
        }

        // Rate-of-fire limiting
        const time = performance.now();
        if (this.lastShotFiredTimestamp !== null && time - this.lastShotFiredTimestamp < GameConfig.RATE_OF_FIRE_DELAY_MS) {
            return;
        }

        this.lastShotFiredTimestamp = performance.now();
        this._isClicked = true;

        if (this._onValidClick) {
            this._onValidClick();
        }
    };

    private _handleMouseUp = (): void => {
        this._isClicked = false;
    };
}
