import { logInfo, logWarning } from 'logger/log';

/** Shape of a detected event stored by the analyzer */
export interface AnalyzerEvent {
    amplitude?: number;
    direction?: number;
    shortfall_deg?: number;
    correction_time_ms?: number;
    [key: string]: unknown;
}

/**
 * Base class for event analyzers (overshoot/undershoot detection)
 * Provides shared functionality to reduce code duplication
 */
export class BaseEventAnalyzer {
    private _eventDetected = false;
    protected detectedEvents: AnalyzerEvent[] = [];

    /** Whether an event has been detected for the current target */
    get eventDetected(): boolean {
        return this._eventDetected;
    }

    /**
     * Reset analyzer state for new target
     * Subclasses can override to add additional reset logic
     */
    reset(): void {
        this._eventDetected = false;
    }

    /**
     * Get all detected events
     * @returns {AnalyzerEvent[]} Array of detected event objects
     */
    getEvents(): AnalyzerEvent[] {
        return this.detectedEvents;
    }

    /**
     * Store event with one-shot behavior
     * @param event - Event data to store
     * @param timestamp - Event timestamp
     * @param hits - Array to store hit timestamps
     * @param eventType - Type of event (for logging)
     * @param logColor - Console log color
     * @protected
     */
    protected _storeEvent(event: AnalyzerEvent, timestamp: number, hits: number[], eventType: string, logColor: string): void {
        this._eventDetected = true;
        hits.push(timestamp);
        this.detectedEvents.push(event);

        logInfo(`DpiTester - EventAnalyzer - [${eventType} Detected]`, {
            amplitude: `${event.amplitude?.toFixed(4)}°`,
            direction: (event.direction ?? 0) > 0 ? 'positive' : 'negative',
            timestamp: `${timestamp.toFixed(2)}ms`,
            ...(event.shortfall_deg && { shortfall: `${event.shortfall_deg.toFixed(4)}°` }),
            ...(event.correction_time_ms && { correction_time: `${event.correction_time_ms.toFixed(2)}ms` }),
        }, true);
    }

    /**
     * Validate input data for analysis
     * @param data - Data to validate
     * @param minLength - Minimum required data length
     * @returns {boolean} True if data is valid
     * @protected
     */
    protected _validateData(data: unknown[], minLength = 2): boolean {
        if (!data || !Array.isArray(data) || data.length < minLength) {
            logWarning(`[${this.constructor.name}] Invalid data provided to detection method`, null, true);
            return false;
        }
        return true;
    }
}
