import * as THREE from 'three';

import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass';
import { GameConfig } from './Config';

/**
 * A class that packs the default setup for the renderer, the camera and the VFXs.
 * Changes here may affect performance, so be careful when changing properties.
 */
export class RendererBuilder {
    static default(windowRef: Window): THREE.WebGLRenderer {
        const renderer: THREE.WebGLRenderer = new THREE.WebGLRenderer({ alpha: true, depth: true, antialias: true });
        renderer.setPixelRatio(windowRef.devicePixelRatio);
        renderer.setSize(windowRef.innerWidth, windowRef.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.VSMShadowMap;
        renderer.toneMapping = THREE.ReinhardToneMapping;
        renderer.toneMappingExposure = GameConfig.TONE_MAPPING_EXPOSURE;
        renderer.outputColorSpace = THREE.SRGBColorSpace;

        renderer.domElement.style.position = 'fixed';
        renderer.domElement.id = 'renderer';
        renderer.domElement.style.zIndex = '-1';
        renderer.domElement.style.left = '0';
        renderer.domElement.style.top = '0';
        return renderer;
    }

    /**
     * Creates a camera for first person view.
     * @param fov - The expected field of view of the camera.
     * @param playerHeight - At which height to place the camera from the ground.
     * @returns A camera object.
     */
    static createCamera(fov: number, playerHeight: number): THREE.PerspectiveCamera {
        const camera: THREE.PerspectiveCamera = new THREE.PerspectiveCamera(
            fov,
            window.innerWidth / window.innerHeight,
            GameConfig.CAMERA_NEAR_PLANE,
            GameConfig.CAMERA_FAR_PLANE,
        );
        camera.position.y = playerHeight;
        return camera;
    }

    /**
     * Creates a rendering pass to add bloom. This smoothes the skybox's components, making their
     * transitions less noticeable.
     * @returns A bloom filter pre-baked with the correct values for the look and feel of the game.
     */
    static createBloomPass(): UnrealBloomPass {
        return new UnrealBloomPass(
            new THREE.Vector2(GameConfig.BLOOM.RESOLUTION.WIDTH, GameConfig.BLOOM.RESOLUTION.HEIGHT),
            GameConfig.BLOOM.STRENGTH,
            GameConfig.BLOOM.RADIUS,
            GameConfig.BLOOM.THRESHOLD,
        );
    }
}
