import * as THREE from 'three';

import { ShadersLibrary } from './Shaders';
import { GameConfig } from './Config';

/** Color for the top of the sky dome (deep blue) */
const skyTopColor: THREE.Color = new THREE.Color(GameConfig.SKY_TOP_COLOR);

/** Color for the middle sky and fog (light cyan) */
const skyColor: THREE.Color = new THREE.Color(GameConfig.SKY_COLOR);

/** Color for the ground plane (bright cyan) */
const groundColor: THREE.Color = new THREE.Color(GameConfig.GROUND_COLOR);

/**
 * SceneBuilder class for creating and configuring Three.js scene.
 * Provides factory methods to generate pre-configured 3D environments.
 * If more games are created, this should be reused and expanded upon.
 */
export class SceneBuilder {
    /**
     * Creates a default scene with ground, sky dome, and lighting setup.
     * The scene includes:
     * - A large ground plane positioned below the origin
     * - A sky dome with gradient shader
     * - Hemisphere and directional lighting with shadows
     * - Fog effect for depth perception
     * @returns {THREE.Scene} A fully configured Three.js scene ready for rendering
     */
    static createDefault(): THREE.Scene {
        // Initialize the main scene with background color and fog
        const scene: THREE.Scene = new THREE.Scene();
        scene.background = skyColor;
        scene.fog = new THREE.Fog(skyColor, GameConfig.FOG.NEAR, GameConfig.FOG.FAR);

        // Create ground plane
        // Rotated to be horizontal and positioned below the origin
        const floorGeometry: THREE.Mesh = new THREE.Mesh(
            new THREE.PlaneGeometry(5000, 5000),
            new THREE.MeshLambertMaterial({ color: groundColor }),
        );
        floorGeometry.rotateX(-Math.PI / 2); // Rotate from vertical (XY) to horizontal (XZ)
        floorGeometry.position.y = GameConfig.FLOOR_Y_POSITION;
        floorGeometry.receiveShadow = false;
        scene.add(floorGeometry);

        // Create sky ceiling plane
        // Positioned above the scene to create a bounded environment
        const skyGeometry: THREE.Mesh = new THREE.Mesh(
            new THREE.PlaneGeometry(5000, 5000),
            new THREE.MeshLambertMaterial({ color: skyTopColor }),
        );
        skyGeometry.rotateX(Math.PI / 2); // Rotate to face downward
        skyGeometry.position.y = GameConfig.SKY_Y_POSITION;
        skyGeometry.receiveShadow = false;
        scene.add(skyGeometry);

        // Add hemisphere light for ambient illumination
        // Provides soft lighting from above (sky) and below (ground)
        const hemiLight: THREE.HemisphereLight = new THREE.HemisphereLight(0xffffff, 0xffffff, GameConfig.HEMISPHERE_LIGHT_INTENSITY);
        hemiLight.color.setHSL(0.6, 1, 0.6); // Sky color: cyan-blue hue
        hemiLight.groundColor.setHSL(0.095, 1, 0.75); // Ground color: warm orange hue
        hemiLight.position.set(0, 50, 0);
        scene.add(hemiLight);

        // Add directional light for shadows and definition
        // Simulates sunlight coming from upper-left direction
        const directionalLight: THREE.DirectionalLight = new THREE.DirectionalLight(0xffffff, GameConfig.DIRECTIONAL_LIGHT_INTENSITY);
        directionalLight.color.setHSL(0.1, 1, 0.95); // Slightly warm white light
        directionalLight.position.set(-1, 1.75, 1);
        directionalLight.position.multiplyScalar(30); // Scale position for proper shadow casting

        // Configure shadow mapping for the directional light
        const d: number = GameConfig.SHADOW.CAMERA_SIZE; // Shadow camera frustum size
        directionalLight.castShadow = true;
        directionalLight.shadow.mapSize.width = GameConfig.SHADOW.MAP_SIZE;
        directionalLight.shadow.mapSize.height = GameConfig.SHADOW.MAP_SIZE;
        directionalLight.shadow.camera.left = -d;
        directionalLight.shadow.camera.right = d;
        directionalLight.shadow.camera.top = d;
        directionalLight.shadow.camera.bottom = -d;
        directionalLight.shadow.camera.far = GameConfig.SHADOW.FAR; // Maximum shadow distance
        directionalLight.shadow.bias = GameConfig.SHADOW.BIAS; // Prevents shadow acne artifacts

        scene.add(directionalLight);

        // Create sky dome with gradient shader
        // Uses custom shaders to create a smooth color gradient from top to bottom
        const vertexShader: string = ShadersLibrary.skydomeVertex();
        const fragmentShader: string = ShadersLibrary.skydomeFragment();

        // Shader uniforms control the gradient appearance
        const uniforms = {
            topColor: { value: groundColor }, // Color at the top of the dome
            bottomColor: { value: skyColor }, // Color at the bottom/horizon
            offset: { value: GameConfig.SKY_GRADIENT.OFFSET }, // Vertical offset for gradient positioning
            exponent: { value: GameConfig.SKY_GRADIENT.EXPONENT }, // Controls gradient falloff curve
        };

        // Sync top color with hemisphere light for consistent lighting
        uniforms.topColor.value.copy(hemiLight.color);

        // Match fog color to the sky gradient bottom color
        scene.fog.color.copy(uniforms.bottomColor.value);

        // Create sphere geometry for the sky dome (radius: 4000, segments: 32x15)
        const skyGeo: THREE.SphereGeometry = new THREE.SphereGeometry(4000, 32, 15);
        const skyMat: THREE.ShaderMaterial = new THREE.ShaderMaterial({
            uniforms,
            vertexShader,
            fragmentShader,
            side: THREE.BackSide, // Render inside of sphere
        });

        const sky: THREE.Mesh = new THREE.Mesh(skyGeo, skyMat);
        scene.add(sky);

        // Return the fully configured scene
        return scene;
    }
}
