import type * as THREE from 'three';
import { type PointerLockControls as PointerLockControlsType, PointerLockControls } from 'three/addons/controls/PointerLockControls.js';
import { logWarning } from 'logger/log';
import { isWindows } from 'utilities/statics';
import { GameConfig } from '../Config';

/**
 * Shape of the Three.js PointerLockControls instance that this wrapper proxies.
 * Extends the base PointerLockControls type with additional internal methods.
 *
 * Inheritance hierarchy:
 * - EventDispatcher (provides addEventListener, removeEventListener, etc.)
 * - Controls (provides object, domElement, enabled, connect, disconnect, dispose)
 * - PointerLockControls (provides isLocked, pointerSpeed, lock, unlock, moveForward, moveRight)
 */
interface PointerLockControlsShape extends PointerLockControlsType {
    // Explicitly type properties to avoid 'any' inference issues
    readonly isLocked: boolean;
    readonly object: THREE.Object3D;
    readonly domElement: HTMLElement | SVGElement | null;
    pointerSpeed: number;

    // Additional method needed by wrapper (not in standard type definition)
    getObject: () => THREE.Object3D;

    /** Internal Three.js error handler — not part of the public API */
    _onPointerlockError?: () => void;
}

/**
 * Wrapper class for Three.js PointerLockControls that provides enhanced pointer lock functionality
 * with automatic retry logic and error handling to prevent camera skips and improve reliability.
 */
class PointerLockWrapper {
    private _controls: PointerLockControlsShape | null;
    private _isPointerLockPending = false;
    private _hasRetried = false;
    private _retryTimeoutId: ReturnType<typeof setTimeout> | null = null;
    private _checkTimeoutId: ReturnType<typeof setTimeout> | null = null;
    private _isDisposed = false;

    /**
     * Creates a new PointerLockWrapper instance
     *
     * @param {PointerLockControls} controls - Three.js PointerLockControls instance to wrap
     */
    constructor(controls: PointerLockControls) {
        this._controls = controls as PointerLockControlsShape;

        this._setupEventListeners();
        this._suppressThreeJsErrorLogging();
    }

    /**
     * Gets the controls instance, asserting it's non-null.
     * This is safe because _controls is only null after dispose(),
     * and all public methods check _isDisposed before accessing controls.
     * @private
     */
    private get controls(): PointerLockControlsShape {
        if (!this._controls || this._isDisposed) {
            throw new Error('[PointerLockWrapper] Instance is disposed or null');
        }

        return this._controls;
    }

    // Getters - Proxy properties from underlying controls

    /**
     * Gets the camera from the controls.
     * Note: PointerLockControls stores the camera in the 'object' property inherited from Controls base class.
     * @returns {THREE.Camera} The camera object from the controls
     */
    get camera(): THREE.Camera { return this.controls.object as THREE.Camera; }

    /** @returns {HTMLElement} The DOM element the controls are attached to */
    get domElement(): HTMLElement { return this.controls.domElement as HTMLElement; }

    /** @returns {boolean} Whether the pointer is currently locked */
    get isLocked(): boolean { return this.controls.isLocked; }

    /** @returns {THREE.Object3D} The object being controlled (typically the camera) */
    get object(): THREE.Object3D { return this.controls.object; }

    /**
     * Gets the pointer speed (mouse sensitivity)
     * @returns {number} The current pointer speed value
     */
    get pointerSpeed(): number { return this.controls.pointerSpeed; }

    /**
     * Sets the pointer speed (mouse sensitivity)
     * @param {number} value - The new pointer speed value
     */
    set pointerSpeed(value: number) { this.controls.pointerSpeed = value; }

    // Proxy methods - Delegate to underlying controls

    /**
     * Adds an event listener to the controls
     * @param {string} type - Event type
     * @param {Function} listener - Event listener callback
     */
    addEventListener(...args: Parameters<THREE.EventDispatcher['addEventListener']>): void {
        this.controls.addEventListener(...args);
    }
    // addEventListener<K extends keyof THREE.EventDispatcher['addEventListener']>(
    //     type: K,
    //     listener: (event: THREE.EventDispatcher['addEventListener']) => void
    // ): void {
    //     this.controls.addEventListener(type, listener);
    // }

    /**
     * Removes an event listener from the controls
     * @param {string} type - Event type
     * @param {Function} listener - Event listener callback
     */
    removeEventListener(...args: Parameters<THREE.EventDispatcher['removeEventListener']>): void {
        this.controls.removeEventListener(...args);
    }

    /** Connects the controls */
    connect(): void { this.controls.connect(this.controls.domElement as HTMLElement); }

    /** Disconnects the controls */
    disconnect(): void { this.controls.disconnect(); }

    /**
     * Gets the controlled object
     * @returns {THREE.Object3D} The controlled object
     */
    getObject(): THREE.Object3D { return this.controls.getObject(); }

    /**
     * Moves the camera forward by the specified distance
     * @param {number} distance - Distance to move forward
     */
    moveForward(distance: number): void { this.controls.moveForward(distance); }

    /**
     * Moves the camera right by the specified distance
     * @param {number} distance - Distance to move right
     */
    moveRight(distance: number): void { this.controls.moveRight(distance); }

    /**
     * Requests pointer lock with enhanced error handling and retry logic.
     * Attempts to use unadjustedMovement mode for raw input to prevent camera skips.
     */
    lock(): void {
        // Prevent multiple simultaneous lock requests
        if (this._isDisposed || document.pointerLockElement || this._isPointerLockPending) {
            return;
        }

        this._isPointerLockPending = true;
        this._hasRetried = false;

        const el: HTMLElement = (this.controls.domElement ?? document.body) as HTMLElement;

        // `unadjustedMovement: true` disables OS-level pointer acceleration for raw, unprocessed
        // mouse deltas.
        //
        // On Windows, Chromium's implementation of unadjustedMovement may fail to call
        // ClipCursor() to physically confine the cursor, causing it to escape the window
        // even though document.pointerLockElement remains set. Omitting the option on Windows
        // avoids the bug while still granting pointer lock for gameplay. macOS does not have
        // this issue, so unadjustedMovement is kept there for accurate raw input.
        const options = isWindows() ? undefined : { unadjustedMovement: true };

        const result = (el as Element & { requestPointerLock(options?: { unadjustedMovement?: boolean }): Promise<void> })
            .requestPointerLock(options) as Promise<void> | void;
        if (result && typeof (result).catch === 'function') {
            (result).catch(() => {
                // Silently handled — _handlePointerLockError will fire and retry if needed
            });
        }
    }

    /**
     * Releases the pointer lock
     */
    unlock(): void {
        this.controls.unlock();
    }

    /**
     * Handles pointer lock state changes.
     * Resets pending and retry flags when pointer lock state changes.
     *
     * @private
     */
    private _handlePointerLockChange = (): void => {
        if (this._isDisposed) return;

        if (document.pointerLockElement) {
            // Pointer lock successfully acquired
            this._isPointerLockPending = false;
        } else {
            // Pointer lock released or failed
            this._isPointerLockPending = false;
            this._hasRetried = false;
        }
    };

    /**
     * Handles pointer lock errors with automatic retry logic.
     * Waits briefly to check if the lock was actually acquired (some browsers fire error events incorrectly),
     * then attempts one retry after a delay if the lock is still not active.
     *
     * @private
     */
    private _handlePointerLockError = (): void => {
        if (this._isDisposed) return;

        this._isPointerLockPending = false;

        // Wait briefly to verify the lock actually failed (some browsers fire spurious errors)
        this._checkTimeoutId = setTimeout(() => {
            if (document.pointerLockElement) return;

            // Attempt one retry if we haven't already
            if (!this._hasRetried) {
                this._hasRetried = true;
                this._retryTimeoutId = setTimeout(() => {
                    if (!document.pointerLockElement && !this._isPointerLockPending) {
                        this.lock();
                    }
                }, GameConfig.POINTER_LOCK_RETRY_DELAY_MS);
            }
        }, GameConfig.POINTER_LOCK_CHECK_DELAY_MS);
    };

    /**
     * Sets up document-level event listeners for pointer lock changes and errors
     *
     * @private
     */
    private _setupEventListeners(): void {
        document.addEventListener('pointerlockchange', this._handlePointerLockChange);
        document.addEventListener('pointerlockerror', this._handlePointerLockError);
    }

    /**
     * Suppresses Three.js's default pointer lock error logging to prevent console spam.
     * Replaces the Three.js error handler with a no-op function while maintaining
     * the event listener structure.
     *
     * @private
     */
    private _suppressThreeJsErrorLogging(): void {
        if (this.controls._onPointerlockError) {
            const doc: Document = this.controls.domElement?.ownerDocument || document;

            // Remove the original Three.js error handler
            doc.removeEventListener('pointerlockerror', this.controls._onPointerlockError);

            // Replace with a no-op to prevent error logging
            this.controls._onPointerlockError = () => {};

            // Re-add the no-op handler to maintain Three.js's internal state
            doc.addEventListener('pointerlockerror', this.controls._onPointerlockError);
        }
    }

    /**
     * Cleans up pointer lock related resources, timers, and event listeners
     *
     * @private
     */
    private _pointerLockCleanup(): void {
        // Clear any pending timers
        if (this._retryTimeoutId !== null) {
            clearTimeout(this._retryTimeoutId);
            this._retryTimeoutId = null;
        }
        if (this._checkTimeoutId !== null) {
            clearTimeout(this._checkTimeoutId);
            this._checkTimeoutId = null;
        }

        // Remove event listeners
        document.removeEventListener('pointerlockchange', this._handlePointerLockChange);
        document.removeEventListener('pointerlockerror', this._handlePointerLockError);

        // Reset state flags
        this._isPointerLockPending = false;
        this._hasRetried = false;
    }

    /**
     * Disposes of the wrapper and cleans up all resources.
     * Should be called when the controls are no longer needed to prevent memory leaks.
     */
    dispose(): void {
        // Prevent double disposal
        if (this._isDisposed) {
            logWarning('[PointerLockWrapper] Already disposed', null, true);
            return;
        }

        this._isDisposed = true;

        // Clean up pointer lock resources
        this._pointerLockCleanup();

        // Dispose of the underlying controls if possible
        this._controls?.dispose?.();

        // Clear reference to controls
        this._controls = null;
    }
}

/**
 * Factory function to create a PointerLockWrapper instance.
 * Wraps Three.js PointerLockControls with enhanced error handling and retry logic.
 *
 * @param {PointerLockControls} controls - Three.js PointerLockControls instance to wrap
 * @returns {PointerLockWrapper} A new PointerLockWrapper instance
 */
export function wrapPointerLockControls(controls: PointerLockControls): PointerLockWrapper {
    return new PointerLockWrapper(controls);
}
