import * as THREE from 'three';
import { GameConfig } from './Config';

// Local aliases for readability — sourced from the centralized GameConfig

/**
 * Target geometry constants defining the visual dimensions of targets.
 * @constant {Object}
 */
const TARGET_GEOMETRY = GameConfig.TARGET_GEOMETRY;

/**
 * Target positioning constants defining spawn boundaries and constraints.
 * @constant {Object}
 */
const TARGET_POSITIONING = GameConfig.TARGET_POSITIONING;

/**
 * Quadrant angle constants defining the 8 directional zones around the cursor.
 * All values are in degrees.
 * @constant {Object}
 */
const QUADRANT_ANGLES = {
    RIGHT: 0,
    TOP_RIGHT: 45,
    TOP: 90,
    TOP_LEFT: 135,
    LEFT: 180,
    BOTTOM_LEFT: 225,
    BOTTOM: 270,
    BOTTOM_RIGHT: 315,
} as const;

/**
 * Target visual constants for emissive effects and animations.
 * @constant {Object}
 */
const TARGET_VISUAL = GameConfig.TARGET_VISUAL;

/**
 * Target distance constant (matches Z_POSITION).
 * @constant {number}
 */
const TARGET_DISTANCE: number = Math.abs(TARGET_POSITIONING.Z_POSITION);

/**
 * Manages quadrant-based target distribution to ensure uniform spatial coverage.
 * Uses a singleton pattern to maintain state across target spawns.
 */
class QuadrantManager {
    static instance: QuadrantManager | null = null;

    private quadrants: number[];
    private availableQuadrants: number[];

    /**
     * Creates a new QuadrantManager instance.
     * Initializes 8 quadrants: 0° (right), 45° (top-right), 90° (top), 135° (top-left),
     * 180° (left), 225° (bottom-left), 270° (bottom), 315° (bottom-right).
     */
    constructor() {
        this.quadrants = [
            QUADRANT_ANGLES.RIGHT,
            QUADRANT_ANGLES.TOP_RIGHT,
            QUADRANT_ANGLES.TOP,
            QUADRANT_ANGLES.TOP_LEFT,
            QUADRANT_ANGLES.LEFT,
            QUADRANT_ANGLES.BOTTOM_LEFT,
            QUADRANT_ANGLES.BOTTOM,
            QUADRANT_ANGLES.BOTTOM_RIGHT,
        ];
        this.availableQuadrants = [...this.quadrants];
        this.shuffleQuadrants();
    }

    /**
     * Gets the singleton instance of QuadrantManager.
     * @static
     * @returns {QuadrantManager} The singleton instance.
     */
    static getInstance(): QuadrantManager {
        if (!QuadrantManager.instance) {
            QuadrantManager.instance = new QuadrantManager();
        }
        return QuadrantManager.instance;
    }

    /**
     * Shuffles the available quadrants using the Fisher-Yates algorithm.
     * Ensures random but fair distribution of target positions.
     */
    shuffleQuadrants(): void {
        for (let i: number = this.availableQuadrants.length - 1; i > 0; i--) {
            // Math.random() is used for gameplay quadrant shuffling only, not for security-critical operations
            // nosemgrep: javascript-crypto-rule-node_insecure_random_generator
            const j: number = Math.floor(Math.random() * (i + 1));
            [this.availableQuadrants[i], this.availableQuadrants[j]] = [
                this.availableQuadrants[j],
                this.availableQuadrants[i],
            ];
        }
    }

    /**
     * Peeks at the next available quadrant without consuming it.
     * Automatically refreshes and shuffles when all quadrants are exhausted.
     * @returns {number} The angle (in degrees) of the next quadrant.
     */
    peekNextQuadrant(): number {
        if (this.availableQuadrants.length === 0) {
            this.availableQuadrants = [...this.quadrants];
            this.shuffleQuadrants();
        }

        return this.availableQuadrants[this.availableQuadrants.length - 1];
    }

    /**
     * Consumes and returns the next available quadrant.
     * @returns {number | undefined} The angle (in degrees) of the consumed quadrant.
     */
    consumeQuadrant(): number | undefined {
        return this.availableQuadrants.pop();
    }

    /**
     * Resets the quadrant manager to its initial state.
     * Refreshes all quadrants and shuffles them.
     */
    reset(): void {
        this.availableQuadrants = [...this.quadrants];
        this.shuffleQuadrants();
    }
}

/**
 * Represents a clickable target in the DPI tester game.
 * Manages target geometry, positioning, visual effects, and interactions.
 */
export class Target {
    private isFlashing: boolean;
    private originalColor!: THREE.Color;
    private sphere_mesh!: THREE.Mesh;
    private ring_mesh!: THREE.Mesh;
    private ringMaterial!: THREE.MeshStandardMaterial;
    private direction!: number;

    /**
     * Creates a new Target instance.
     */
    constructor() {
        this.isFlashing = false;
    }

    /**
     * Calculate target half-width in degrees (angular tolerance)
     * Based on actual target geometry and viewing distance
     * @param camera - Camera for distance calculation (optional, uses default distance)
     * @param targetPosition - Target position (optional, uses default distance)
     * @returns {number} Target half-width in degrees
     */
    static getAngularToleranceDeg(camera: THREE.Camera | null = null, targetPosition: THREE.Vector3 | null = null): number {
        let distance: number = TARGET_DISTANCE;
        if (camera && targetPosition) {
            distance = camera.position.distanceTo(targetPosition);
        }

        // θ/2 = arctan(r / d) - angular half-width formula
        const angularRadiusRad: number = Math.atan(TARGET_GEOMETRY.CIRCLE_RADIUS / distance);
        const angularRadiusDeg: number = angularRadiusRad * (180 / Math.PI);

        return angularRadiusDeg;
    }

    /**
     * Factory method to create a Target instance with specified properties.
     * @static
     * @param targetColor - The color of the target (hex or CSS color string).
     * @param tag - A unique identifier for the target.
     * @param vector3Position - The position of the target in 3D space.
     * @returns {Target} A new Target instance.
     */
    static create(targetColor: THREE.ColorRepresentation, tag: string, vector3Position: THREE.Vector3): Target {
        const target: Target = new Target();
        target.build(targetColor, tag, vector3Position);
        return target;
    }

    /**
     * Builds the target's 3D geometry and materials.
     * Creates both the central circle and outer ring meshes.
     * @param targetColor - The color of the target.
     * @param tag - A unique identifier for the target.
     * @param vector3Position - The position of the target in 3D space.
     */
    build(targetColor: THREE.ColorRepresentation, tag: string, vector3Position: THREE.Vector3): void {
        // Create the material for the central circle
        const mat: THREE.MeshStandardMaterial = new THREE.MeshStandardMaterial();
        mat.color = new THREE.Color(targetColor);
        mat.emissive = new THREE.Color(targetColor);
        mat.emissiveIntensity = TARGET_VISUAL.EMISSIVE_INTENSITY;

        // Store the original color for reset operations
        this.originalColor = new THREE.Color(targetColor);

        // Create the central circle geometry
        const geometry: THREE.CircleGeometry = new THREE.CircleGeometry(TARGET_GEOMETRY.CIRCLE_RADIUS, TARGET_GEOMETRY.CIRCLE_SEGMENTS);
        this.sphere_mesh = new THREE.Mesh(geometry, mat);
        this.sphere_mesh.material = mat;
        this.sphere_mesh.name = tag;

        this.sphere_mesh.position.x = vector3Position.x;
        this.sphere_mesh.position.y = vector3Position.y;
        this.sphere_mesh.position.z = vector3Position.z;
        this.sphere_mesh.castShadow = true;
        this.sphere_mesh.receiveShadow = false;

        // Create the outer ring geometry
        const geometryRing: THREE.RingGeometry = new THREE.RingGeometry(
            TARGET_GEOMETRY.RING_INNER_RADIUS,
            TARGET_GEOMETRY.RING_OUTER_RADIUS,
            TARGET_GEOMETRY.RING_SEGMENTS,
            1,
            Math.PI * 2,
        );

        // Create a separate material for the ring to allow independent color changes
        this.ringMaterial = new THREE.MeshStandardMaterial({
            color: new THREE.Color(targetColor),
            emissive: new THREE.Color(targetColor),
            emissiveIntensity: TARGET_VISUAL.EMISSIVE_INTENSITY,
        });

        this.ring_mesh = new THREE.Mesh(geometryRing, this.ringMaterial);
        this.ring_mesh.name = `${tag}_ring`;

        this.ring_mesh.position.x = vector3Position.x;
        this.ring_mesh.position.y = vector3Position.y;
        this.ring_mesh.position.z = vector3Position.z;
        this.ring_mesh.castShadow = true;
        this.ring_mesh.receiveShadow = false;

        this.direction = THREE.MathUtils.randFloat(-1, 1);
    }

    /**
     * Flashes the target's ring to a specified color temporarily.
     * Prevents multiple simultaneous flash effects.
     * @param flashColor - The color to flash (hex or CSS color string).
     */
    flash(flashColor: THREE.ColorRepresentation): void {
        if (this.isFlashing) return;

        this.isFlashing = true;

        // Store original color values
        const originalColor: THREE.Color = this.ringMaterial.color.clone();
        const originalEmissive: THREE.Color = this.ringMaterial.emissive.clone();

        // Change to flash color
        this.ringMaterial.color.set(flashColor);
        this.ringMaterial.emissive.set(flashColor);
        this.ringMaterial.emissiveIntensity = TARGET_VISUAL.FLASH_INTENSITY;

        // Reset after flash duration
        setTimeout(() => {
            this.ringMaterial.color.copy(originalColor);
            this.ringMaterial.emissive.copy(originalEmissive);
            this.ringMaterial.emissiveIntensity = TARGET_VISUAL.EMISSIVE_INTENSITY;
            this.isFlashing = false;
        }, TARGET_VISUAL.FLASH_DURATION_MS);
    }

    /**
     * Sets the target's ring color continuously (e.g., for hover state).
     * Does not override active flash animations.
     * @param color - The color to set (hex or CSS color string).
     */
    setRingColor(color: THREE.ColorRepresentation): void {
        if (this.isFlashing) return;

        this.ringMaterial.color.set(color);
        this.ringMaterial.emissive.set(color);
        this.ringMaterial.emissiveIntensity = TARGET_VISUAL.EMISSIVE_INTENSITY;
    }

    /**
     * Resets the target's ring to its original color.
     * Does not override active flash animations.
     */
    resetRingColor(): void {
        if (this.isFlashing) return;

        this.ringMaterial.color.copy(this.originalColor);
        this.ringMaterial.emissive.copy(this.originalColor);
        this.ringMaterial.emissiveIntensity = TARGET_VISUAL.EMISSIVE_INTENSITY;
    }

    /**
     * Converts polar offset (angle, distance) to a clamped 3D position
     * relative to the cursor center on the target plane.
     *
     * Applies conditional vertical shrinking, upward bias, vertical clamping,
     * and absolute bounds clamping.
     *
     * @static
     * @param angleRad - Angle in radians from cursor center.
     * @param distance - Distance from cursor center.
     * @param cursorCenterOnPlane - Cursor projection on the target plane.
     * @returns {THREE.Vector3} Clamped position on the target plane.
     */
    static _polarToClampedPosition(angleRad: number, distance: number, cursorCenterOnPlane: THREE.Vector3): THREE.Vector3 {
        // Convert polar coordinates (angle, distance) to Cartesian (x, y)
        const offsetX: number = Math.cos(angleRad) * distance;
        let offsetY: number = Math.sin(angleRad) * distance;

        // Apply conditional vertical shrinking based on cursor position:
        // - If cursor is high (>0) and target moves upward: shrink to prevent extreme heights
        // - If cursor is low (<0) and target moves downward: shrink to prevent going too low
        // - Otherwise: allow full vertical range for natural movement
        const cursorIsHigh: boolean = cursorCenterOnPlane.y > 0;
        const cursorIsLow: boolean = cursorCenterOnPlane.y < 0;

        if ((cursorIsHigh && offsetY > 0) || (cursorIsLow && offsetY < 0)) {
            offsetY *= TARGET_POSITIONING.VERTICAL_SHRINK_FACTOR;
        }

        // Apply upward bias to avoid ground overlap
        offsetY += TARGET_POSITIONING.VERTICAL_UPWARD_BIAS;

        // Clamp vertical offset to prevent going too far up/down
        offsetY = THREE.MathUtils.clamp(
            offsetY,
            -TARGET_POSITIONING.MAX_VERTICAL_OFFSET,
            TARGET_POSITIONING.MAX_VERTICAL_OFFSET,
        );

        // Position relative to where the cursor is pointing
        const pos: THREE.Vector3 = new THREE.Vector3(
            (cursorCenterOnPlane.x) + offsetX,
            (cursorCenterOnPlane.y) + offsetY,
            TARGET_POSITIONING.Z_POSITION,
        );

        // Apply absolute bounds clamping
        pos.x = THREE.MathUtils.clamp(pos.x, TARGET_POSITIONING.MIN_X, TARGET_POSITIONING.MAX_X);
        pos.y = THREE.MathUtils.clamp(pos.y, TARGET_POSITIONING.MIN_Y, TARGET_POSITIONING.MAX_Y);

        return pos;
    }

    /**
     * Generates a random target position relative to the camera's look direction.
     * Uses quadrant-based placement to ensure spatial variety.
     *
     * @param lastKnownPosition - Previous target position for minimum distance checks.
     * @param camera - The camera for cursor direction projection.
     * @returns {THREE.Vector3} New target position on the target plane.
     */
    static randomPosition(lastKnownPosition: THREE.Vector3 = new THREE.Vector3(0, 0, 0), camera: THREE.Camera | null = null): THREE.Vector3 {
        const quadrantManager: QuadrantManager = QuadrantManager.getInstance();

        // Get the cursor direction (where the camera is looking)
        const cursorDirection: THREE.Vector3 = new THREE.Vector3(0, 0, -1);
        if (camera) {
            camera.getWorldDirection(cursorDirection);
        }

        // Project the cursor direction onto a plane at Z_POSITION distance
        const cursorCenterOnPlane: THREE.Vector3 = cursorDirection.clone().multiplyScalar(Math.abs(TARGET_POSITIONING.Z_POSITION));

        // Try each available quadrant until we find a valid position
        // We have 8 quadrants, so we can try up to 8 different directions
        const maxQuadrantAttempts = 8;

        for (let quadrantAttempt = 0; quadrantAttempt < maxQuadrantAttempts; quadrantAttempt++) {
            const baseQuadrantAngle: number = quadrantManager.peekNextQuadrant();

            for (let i = 0; i < GameConfig.TARGET_ATTEMPTS_PER_QUADRANT; i++) {
                // Add random variation within the quadrant
                const angleVariation: number = THREE.MathUtils.randFloat(
                    -TARGET_POSITIONING.QUADRANT_ANGLE_VARIATION,
                    TARGET_POSITIONING.QUADRANT_ANGLE_VARIATION,
                );
                const finalAngleDegrees: number = baseQuadrantAngle + angleVariation;
                const finalAngleRadians: number = THREE.MathUtils.degToRad(finalAngleDegrees);

                // Pick random distance from cursor center
                const distance: number = THREE.MathUtils.randFloat(
                    TARGET_POSITIONING.MIN_DISTANCE_FROM_CURSOR,
                    TARGET_POSITIONING.MAX_DISTANCE_FROM_CURSOR,
                );

                const newPos: THREE.Vector3 = Target._polarToClampedPosition(finalAngleRadians, distance, cursorCenterOnPlane);
                const distanceFromLast: number = newPos.distanceTo(lastKnownPosition);

                // Check if position meets minimum distance requirement
                if (distanceFromLast >= TARGET_POSITIONING.MIN_DISTANCE_FROM_LAST) {
                    // Success! Consume the quadrant and return
                    quadrantManager.consumeQuadrant();
                    return newPos;
                }
            }

            // This quadrant didn't work, try the next one
            quadrantManager.consumeQuadrant();
        }

        // Fallback: Use maximum distance in a random direction to guarantee separation
        // Math.random() is used for fallback target positioning only, not for security-critical operations
        // nosemgrep: javascript-crypto-rule-node_insecure_random_generator
        const fallbackAngle: number = Math.random() * Math.PI * 2;
        const fallbackDistance: number = TARGET_POSITIONING.MAX_DISTANCE_FROM_CURSOR;

        return Target._polarToClampedPosition(fallbackAngle, fallbackDistance, cursorCenterOnPlane);
    }

    /**
     * Resets the QuadrantManager singleton to a fresh state.
     * Must be called between game sessions to ensure uniform
     * quadrant distribution from the start of each new game.
     * @static
     */
    static resetQuadrants(): void {
        QuadrantManager.getInstance().reset();
    }

    /**
     * Gets the sphere mesh (central circle) of the target.
     * @returns {THREE.Mesh} The sphere mesh.
     */
    sphereMesh(): THREE.Mesh {
        return this.sphere_mesh;
    }

    /**
     * Gets the ring mesh (outer ring) of the target.
     * @returns {THREE.Mesh} The ring mesh.
     */
    ringMesh(): THREE.Mesh {
        return this.ring_mesh;
    }

    /**
     * Gets the outer radius of the target ring.
     * @returns {number} The ring outer radius.
     */
    getRadius(): number {
        return TARGET_GEOMETRY.RING_OUTER_RADIUS;
    }
}
