import { GameConfig } from '../Config';
import { BaseEventAnalyzer, AnalyzerEvent } from './BaseEventAnalyzer';

/** Shape of a movement data sample for overshoot analysis */
interface OvershootDataPoint {
    signedErrorRaw?: number;
    timestamp: number;
}

/** Result of geometric overshoot detection */
interface GeometricOvershootResult {
    isOvershoot: boolean;
    peakAmplitude?: number;
    direction?: number;
    signChangeTimestamp?: number;
    peakTimestamp?: number;
    correctionTimestamp?: number | null;
}

/** Result of peak tracking and correction detection */
interface TrackingResult {
    maxAmplitude: number;
    peakIdx: number;
    hasReversalPeak: boolean;
}

/**
 * Handles overshoot detection and visualization
 *
 * Assumes:
 *  - signedErrorRaw(t) = u·(p(t)-p0) - D  (task-axis projection)
 *  - Overshoot detected immediately when cursor goes past target (sign change)
 */
export class OvershootAnalyzer extends BaseEventAnalyzer {
    /**
     * Detect overshoot events using geometric movement pattern analysis without tolerance.
     *
     * Algorithm:
     *  1) Detect bidirectional sign changes (crossing target center)
     *  2) Track movement away from target to find peak amplitude
     *  3) Look for velocity/speed reversal indicating movement back toward target
     *  4) Confirm overshoot only when reversal movement peak is observed
     *  5) Pure geometric approach - no tolerance thresholds, time windows or amplitude thresholds
     */
    detectOvershoots(data: OvershootDataPoint[]): number[] {
        const hits: number[] = [];
        if (!this._validateData(data)) {
            return hits;
        }

        for (let i = 1; i < data.length; i++) {
            const prev: number = data[i - 1].signedErrorRaw ?? 0;
            const curr: number = data[i].signedErrorRaw ?? 0;

            // Detect bidirectional sign changes (no artificial thresholds)
            // Only skip true zeros
            const signChanged: boolean = Math.sign(prev) !== Math.sign(curr) && (prev !== 0 || curr !== 0);

            if (signChanged) {
                // Attempt geometric overshoot detection from this sign change
                const overshootResult: GeometricOvershootResult = this._detectGeometricOvershoot(data, i);

                if (overshootResult.isOvershoot) {
                    // ONE-SHOT: Only detect the first overshoot per movement
                    if (!this.eventDetected) {
                        const event: AnalyzerEvent = {
                            amplitude: overshootResult.peakAmplitude,
                            direction: overshootResult.direction,
                            overshootType: (overshootResult.direction ?? 0) > 0 ? 'positive' : 'negative',
                        };

                        this._storeEvent(event, overshootResult.signChangeTimestamp ?? 0, hits, 'Overshoot', '#ff6b6b');
                        break;
                    }
                }
            }
        }

        return hits;
    }

    // ---------- Internals ----------

    /**
     * Pure geometric overshoot detection
     *
     * True overshoot requires: sign change → movement peak → velocity reversal
     * Confirmed when we see a local peak with speed/velocity reversal back toward target.
     */
    private _detectGeometricOvershoot(data: OvershootDataPoint[], signChangeIdx: number): GeometricOvershootResult {
        const direction: number = this._findDirection(data, signChangeIdx);
        if (direction === 0) return { isOvershoot: false };

        const initialAmplitude: number = Math.abs(data[signChangeIdx].signedErrorRaw ?? 0);
        const trackingResult: TrackingResult = this._trackPeakAndCorrection(data, signChangeIdx, direction, initialAmplitude);

        return this._determineOvershootResult(data, signChangeIdx, direction, trackingResult);
    }

    /**
     * Find the direction of movement from sign change point.
     */
    private _findDirection(data: OvershootDataPoint[], signChangeIdx: number): number {
        let direction: number = Math.sign(data[signChangeIdx].signedErrorRaw ?? 0);

        // If direction is 0 (missing data), look ahead for the actual direction
        if (direction === 0) {
            for (let i = signChangeIdx + 1; i < data.length; i++) {
                const nextValue: number = data[i].signedErrorRaw ?? 0;
                if (nextValue !== 0) {
                    direction = Math.sign(nextValue);
                    break;
                }
            }
        }

        return direction;
    }

    /**
     * Track peak amplitude and reversal movement patterns.
     * Looks for local peaks where movement speed reverses direction.
     */
    private _trackPeakAndCorrection(
        data: OvershootDataPoint[],
        signChangeIdx: number,
        direction: number,
        initialAmplitude: number,
    ): TrackingResult {
        let maxAmplitude: number = initialAmplitude;
        let peakIdx: number = signChangeIdx;
        let hasReversalPeak = false;

        // Track movement velocity (change in signedErrorRaw)
        let previousValue: number = data[signChangeIdx].signedErrorRaw ?? 0;
        let previousVelocity: number | null = null;

        // Track movement to find reversal peaks
        for (let i = signChangeIdx + 1; i < data.length; i++) {
            const current: number = data[i].signedErrorRaw ?? 0;
            const amplitude: number = Math.abs(current);

            // Calculate velocity (change in signed error)
            const velocity: number = current - previousValue;

            // Update peak amplitude if we're still moving away from target
            if (Math.sign(current) === direction || (Math.sign(current) === 0 && amplitude > maxAmplitude)) {
                if (amplitude > maxAmplitude) {
                    maxAmplitude = amplitude;
                    peakIdx = i;
                }
            }

            // Check for velocity reversal (speed reversal in signed error)
            if (previousVelocity !== null && previousVelocity !== 0 && velocity !== 0) {
                // Velocity sign change indicates movement direction reversal
                if (Math.sign(velocity) !== Math.sign(previousVelocity)) {
                    // We found a reversal - this indicates a local peak in movement
                    hasReversalPeak = true;
                    break;
                }
            }

            // Also detect reversal when sign of position changes back toward target
            if (Math.sign(current) !== 0 && Math.sign(current) !== direction) {
                hasReversalPeak = true;
                break;
            }

            previousValue = current;
            if (velocity !== 0) {
                previousVelocity = velocity;
            }
        }

        return { maxAmplitude, peakIdx, hasReversalPeak };
    }

    /**
     * Determine final overshoot result based on tracking data.
     */
    private _determineOvershootResult(
        data: OvershootDataPoint[],
        signChangeIdx: number,
        direction: number,
        trackingResult: TrackingResult,
    ): GeometricOvershootResult {
        const { maxAmplitude, peakIdx, hasReversalPeak } = trackingResult;

        // overshoot detection requirements:
        // 1. Sign change past target (already detected)
        // 2. Movement away from target to a peak
        // 3. Velocity/speed reversal indicating correction back toward target

        const isTrueOvershoot: boolean = hasReversalPeak;

        const isSignificantAmplitude: boolean = maxAmplitude >= GameConfig.MIN_OVERSHOOT_AMPLITUDE_DEG;

        if (isTrueOvershoot && isSignificantAmplitude) {
            return {
                isOvershoot: true,
                peakAmplitude: maxAmplitude,
                direction,
                signChangeTimestamp: data[signChangeIdx].timestamp,
                peakTimestamp: data[peakIdx].timestamp,
                correctionTimestamp: hasReversalPeak ? data[Math.min(data.length - 1, peakIdx + 1)].timestamp : null,
            };
        }

        return { isOvershoot: false };
    }
}
