import * as THREE from 'three';
import { logError } from 'logger/log';
import { GameConfig } from './Config';

// SFX imports
// @ts-expect-error — asset import handled by bundler
import fire from './resources/sfx/fire.mp3';
// @ts-expect-error — asset import handled by bundler
import hitConfirm from './resources/sfx/hit_confirm.mp3';
// @ts-expect-error — asset import handled by bundler
import miss from './resources/sfx/miss.mp3';
// @ts-expect-error — asset import handled by bundler
import destroy from './resources/sfx/destroy.mp3';
// @ts-expect-error — asset import handled by bundler
import countdown from './resources/sfx/countdown.mp3';
// @ts-expect-error — asset import handled by bundler
import teleport from './resources/sfx/teleport.mp3';

/** Sound key names used as instance property identifiers */
type SoundKey =
    | 'fireSound'
    | 'correctHitSound'
    | 'incorrectHitSound'
    | 'targetDestroyedSound'
    | 'countdownSound'
    | 'teleportSound';

/** Configuration entry for a single sound effect */
interface SfxConfigEntry {
    /** Display name for the audio object */
    name: string;
    /** Asset path resolved by the bundler */
    path: string;
    /** Volume level relative to master volume */
    volume: number;
    /** Instance property key for named access */
    soundKey: SoundKey;
}

/**
 * Unified SFX configuration array.
 * Each entry maps a sound name to its asset path, volume, and instance property key.
 * Volumes are sourced from GameConfig.SFX_VOLUMES.
 */
const SFX_CONFIG: readonly SfxConfigEntry[] = [
    { name: 'fire.mp3', path: fire as string, volume: GameConfig.SFX_VOLUMES.fire, soundKey: 'fireSound' },
    { name: 'hit_confirm.mp3', path: hitConfirm as string, volume: GameConfig.SFX_VOLUMES.hit_confirm, soundKey: 'correctHitSound' },
    { name: 'miss.mp3', path: miss as string, volume: GameConfig.SFX_VOLUMES.miss, soundKey: 'incorrectHitSound' },
    { name: 'destroy.mp3', path: destroy as string, volume: GameConfig.SFX_VOLUMES.destroy, soundKey: 'targetDestroyedSound' },
    { name: 'countdown.mp3', path: countdown as string, volume: GameConfig.SFX_VOLUMES.countdown, soundKey: 'countdownSound' },
    { name: 'teleport.mp3', path: teleport as string, volume: GameConfig.SFX_VOLUMES.teleport, soundKey: 'teleportSound' },
];

/**
 * The audio engine provides helper functionalities for anything related to the audio of the
 * game. It adds an audio listener to the player camera and loads the audio resources.
 */
export class AudioEngine {
    // Audio objects
    private sounds: THREE.Audio[] = [];
    private audioLoader: THREE.AudioLoader | null = null;
    public listener: THREE.AudioListener | null = null;

    // Named sound references
    private fireSound: THREE.Audio | null = null;
    private correctHitSound: THREE.Audio | null = null;
    private incorrectHitSound: THREE.Audio | null = null;
    private targetDestroyedSound: THREE.Audio | null = null;
    private countdownSound: THREE.Audio | null = null;
    private teleportSound: THREE.Audio | null = null;

    /** Pitch constants for hit sound streak progression */
    private readonly hitSoundPitchValuesDefault: readonly number[] = [
        0, 100, 200, 300, 400, 500, 600, 700, 800, 900, 1000,
        1100, 1200, 1300, 1400, 1500, 1600, 1700, 1800, 1900, 2000,
    ];

    /**
     * Initialize the audio service with camera and loading manager.
     * @param camera - Camera to attach audio listener to
     * @param manager - Optional loading manager
     */
    initialize(camera: THREE.Camera, manager: THREE.LoadingManager = new THREE.LoadingManager()): void {
        this.audioLoader = new THREE.AudioLoader(manager);
        this.listener = new THREE.AudioListener();
        camera.add(this.listener);
    }

    /**
     * Disconnects and discards all currently tracked THREE.Audio nodes.
     *
     * Called at the top of loadSFX() before creating new nodes to prevent
     * accumulation across plays. Also called from dispose() to replace the
     * partial cleanup that previously skipped sounds without a buffer.
     */
    private clearSounds(): void {
        this.sounds.forEach((sound) => {
            try {
                sound.stop();
                sound.disconnect();
            } catch (_e) {
                // disconnect() throws if the node was never connected — safe to ignore
            }
        });
        this.sounds = [];
        this.fireSound = null;
        this.correctHitSound = null;
        this.incorrectHitSound = null;
        this.targetDestroyedSound = null;
        this.countdownSound = null;
        this.teleportSound = null;
    }

    /** Load all sound effects */
    loadSFX(): void {
        if (!this.audioLoader || !this.listener) {
            logError('[AudioEngine] AudioService not initialized! Call initialize() first.', null, true);
            return;
        }

        const listener = this.listener;
        const audioLoader = this.audioLoader;

        SFX_CONFIG.forEach(({ name, path, volume, soundKey }) => {
            const sound = new THREE.Audio(listener);
            sound.name = name;

            // Calculate normalized volume using master volume
            const normalizedVolume = volume * GameConfig.MASTER_VOLUME;
            sound.setVolume(normalizedVolume);

            // Assign to the named instance property
            this[soundKey] = sound;

            this.sounds.push(sound);
            audioLoader.load(path, (buffer: AudioBuffer) => {
                sound.setBuffer(buffer);
            });
        });
    }

    /** Play fire sound with randomized detune */
    playFireSound(): void {
        if (!this.fireSound) return;
        this.fireSound.stop();
        // Math.random() is used for audio pitch variation only, not for security-critical operations
        // nosemgrep: javascript-crypto-rule-node_insecure_random_generator
        this.fireSound.setDetune(Math.floor(Math.random() * GameConfig.FIRE_DETUNE_RANGE));
        this.fireSound.play();
    }

    /**
     * Play hit confirmation sound with streak-based detune.
     * @param streak - Current kill streak to affect detune
     */
    playHitSound(streak = 0): void {
        if (!this.correctHitSound) return;
        this.correctHitSound.stop();

        // Use predefined pitch values from array instead of computing on the fly
        const pitchIndex = Math.min(streak, this.hitSoundPitchValuesDefault.length - 1);
        this.correctHitSound.setDetune(this.hitSoundPitchValuesDefault[pitchIndex]);

        this.correctHitSound.play();
    }

    /** Play missed shot sound */
    playMissSound(): void {
        if (!this.incorrectHitSound) return;
        this.incorrectHitSound.stop();
        this.incorrectHitSound.play();
    }

    /** Play target destroyed sound */
    playDestroySound(): void {
        if (!this.targetDestroyedSound) return;
        this.targetDestroyedSound.stop();
        this.targetDestroyedSound.play();
    }

    /**
     * Play countdown sound with optional detune.
     * @param detune - Optional detune value
     */
    playCountdownSound(detune = 0): void {
        if (!this.countdownSound) return;
        this.countdownSound.stop();
        if (detune) this.countdownSound.setDetune(detune);
        this.countdownSound.play();
    }

    /** Resume the AudioContext if it has been suspended by the browser due to inactivity */
    resumeAudioContext(): Promise<void> {
        if (this.listener && this.listener.context.state === 'suspended') {
            return this.listener.context.resume();
        }
        return Promise.resolve();
    }

    /** Play teleport sound effect */
    playTeleportSound(): void {
        if (!this.teleportSound) return;
        this.teleportSound.stop();
        this.teleportSound.play();
    }

    /** Clean up audio resources */
    dispose(): void {
        this.clearSounds();

        if (this.listener) {
            // Find the camera containing the listener and remove it
            const camera = this.listener.parent;
            if (camera) {
                camera.remove(this.listener);
            }
        }

        this.listener = null;
        this.audioLoader = null;
    }
}
