import * as THREE from 'three';
import { PointerLockControls } from 'three/addons/controls/PointerLockControls.js';
import { logWarning, logError } from 'logger/log';
import { wrapPointerLockControls } from './utils/PointerLockUtils';
import { GameConfig } from './Config';

/**
 * Callbacks provided by the Facade (Main) so ControlsManager can notify
 * about lifecycle transitions without knowing about HUD, audio, etc.
 */
export interface ControlsCallbacks {
    /** Called immediately when pointer lock is acquired (Three.js 'lock' event) */
    onLock: () => void;
    /** Called when pointer lock is released */
    onUnlock: () => void;
    /** Called if pointer lock acquisition fails completely */
    onAcquisitionFailed: () => void;
}

/**
 * Owns PointerLockControls creation, lock/unlock event handling,
 * pointer lock acquisition monitoring, and disposal.
 *
 * Uses callbacks (not events) because lock/unlock are lifecycle transitions
 * that need ordered orchestration of multiple subsystems by the Facade.
 */
export class ControlsManager {
    /** The wrapped PointerLockControls — needed by PlayerController */
    private _controls: ReturnType<typeof wrapPointerLockControls> | null = null;

    /** Callbacks provided by Main */
    private _callbacks: ControlsCallbacks | null = null;

    /** Debounce flag to prevent rapid unlock re-entry */
    private _unlockInProgress = false;

    /** Handler for pointerlockchange during acquisition monitoring */
    private _pointerLockAcquiredHandler: (() => void) | null = null;

    /** Timeout ID for acquisition loading timeout */
    private _loadingTimeoutId: ReturnType<typeof setTimeout> | null = null;

    /** Timeout ID for a deferred lock retry when the previous pointer lock hasn't fully released yet */
    private _lockRetryTimeoutId: ReturnType<typeof setTimeout> | null = null;

    /**
     * Capture-phase mousemove interceptor that clamps per-event movementX/Y deltas.
     * Prevents Windows high-report-rate mice from delivering giant raw deltas (e.g. ±600 px)
     * that would rotate the camera ~68° in a single frame.
     */
    private _mouseDeltaClampHandler: ((e: MouseEvent) => void) | null = null;

    /** Reusable Euler instance for the clamp handler — avoids per-event allocation */
    private readonly _clampEuler = new THREE.Euler(0, 0, 0, 'YXZ');


    /** The wrapped PointerLockControls — needed by PlayerController and scene */
    get controls(): ReturnType<typeof wrapPointerLockControls> | null {
        return this._controls;
    }

    /** Returns true if controls exist and are ready */
    get isReady(): boolean {
        return this._controls !== null && typeof this._controls.lock === 'function';
    }

    /** Returns true if pointer is currently locked */
    get isLocked(): boolean {
        return this._controls?.isLocked === true;
    }

    /**
     * Creates PointerLockControls, wires lock/unlock events, adds to scene.
     * @param camera - The Three.js camera
     * @param scene - The Three.js scene (controls.object is added to it)
     * @param callbacks - Lifecycle callbacks for the Facade
     */
    init(camera: THREE.Camera, scene: THREE.Scene, callbacks: ControlsCallbacks): void {
        this._callbacks = callbacks;

        const baseControls = new PointerLockControls(camera, document.body);

        // Clamp pitch to prevent the camera from reaching the ±90° gimbal lock
        // singularity. At exactly ±90° the YXZ Euler decomposition used by Three.js
        // PointerLockControls is degenerate — yaw and roll become indistinguishable,
        // so any horizontal mouse delta can produce a wild camera snap. A small margin
        // (~3°) from both vertical extremes keeps the camera in the stable range while
        // preserving the full practical look range for a DPI tester.
        baseControls.minPolarAngle = GameConfig.CAMERA_MIN_POLAR_ANGLE;
        baseControls.maxPolarAngle = GameConfig.CAMERA_MAX_POLAR_ANGLE;

        this._controls = wrapPointerLockControls(baseControls);

        this._controls.addEventListener('lock' as never, this._onControlsLock);
        this._controls.addEventListener('unlock' as never, this._onControlsUnlock);

        scene.add(this._controls.object);

        // Install a capture-phase mousemove interceptor to clamp giant per-event deltas.
        //
        // Root cause: Windows high-report-rate mice (e.g. 8000 Hz) can deliver movementX values
        // of ±600 px in a single mousemove event. At pointerSpeed = 1.0, Three.js computes:
        //   -600 * 0.002 = -1.2 radians (~68°) of yaw per event → violent camera snap.
        //
        // Strategy: intercept in capture phase (fires before Three.js's bubbling-phase handler).
        // If a delta exceeds MAX_MOUSE_DELTA_PER_EVENT, call stopImmediatePropagation() to
        // cancel the raw event, then apply the clamped rotation ourselves using the same
        // YXZ Euler math that Three.js PointerLockControls uses internally.
        const _PI_2 = Math.PI / 2;
        const maxDelta = GameConfig.MAX_MOUSE_DELTA_PER_EVENT;

        this._mouseDeltaClampHandler = (e: MouseEvent): void => {
            if (!this._controls?.isLocked) return;

            const rawX = e.movementX ?? 0;
            const rawY = e.movementY ?? 0;

            // Only intervene when at least one axis exceeds the safe threshold
            if (Math.abs(rawX) <= maxDelta && Math.abs(rawY) <= maxDelta) return;

            // Suppress the raw event so Three.js onMouseMove never sees the giant delta
            e.stopImmediatePropagation();

            // Apply clamped rotation using the same YXZ Euler math as Three.js PointerLockControls
            const cam = this._controls.camera;
            const ps = this._controls.pointerSpeed;
            const clampedX = Math.max(-maxDelta, Math.min(maxDelta, rawX));
            const clampedY = Math.max(-maxDelta, Math.min(maxDelta, rawY));

            this._clampEuler.setFromQuaternion(cam.quaternion);
            this._clampEuler.y -= clampedX * 0.002 * ps;
            this._clampEuler.x -= clampedY * 0.002 * ps;
            // Enforce the same polar-angle pitch clamp that baseControls uses
            this._clampEuler.x = Math.max(
                _PI_2 - GameConfig.CAMERA_MAX_POLAR_ANGLE,
                Math.min(_PI_2 - GameConfig.CAMERA_MIN_POLAR_ANGLE, this._clampEuler.x),
            );
            cam.quaternion.setFromEuler(this._clampEuler);
        };

        // { capture: true } ensures this handler fires before Three.js's bubbling-phase listener
        document.addEventListener('mousemove', this._mouseDeltaClampHandler, { capture: true });
    }

    /**
     * Resets player position and requests pointer lock with stability monitoring.
     * Called by `Main.startGame()` and `Main.resetMatch()`.
     */
    requestLock(): void {
        if (!this._controls || !this.isReady) {
            logWarning('[ControlsManager] Controls not ready for pointer lock', null, true);
            return;
        }

        // Reset player position
        const controlsObject = this._controls.object;
        if (controlsObject?.position) {
            controlsObject.position.x = 0;
            controlsObject.position.z = 0;
        }

        // If the browser hasn't finished releasing the previous pointer lock, defer
        // the lock request until document.pointerLockElement is cleared.
        if (document.pointerLockElement) {
            logWarning('[ControlsManager] Pointer lock element still set, deferring lock request', null, true);
            this._cancelLockRetry();
            this._lockRetryTimeoutId = setTimeout(() => {
                this._lockRetryTimeoutId = null;
                this._attemptLock();
            }, GameConfig.POINTER_LOCK_CHECK_DELAY_MS);
            return;
        }

        this._attemptLock();
    }

    /**
     * Attempts to set up acquisition monitoring and call `lock()`.
     * Extracted for retry use by the deferred lock path in `requestLock()`.
     */
    private _attemptLock(): void {
        this._setupPointerLockAcquisition();
        try {
            this._controls?.lock();
        } catch (error) {
            logError('[ControlsManager] Failed to request pointer lock:', error, true);
            this._clearPointerLockAcquisition();
        }
    }

    /**
     * Cancels any pending deferred lock retry timer.
     * Called before scheduling a new retry and during `dispose()` / `cancelAcquisition()`.
     */
    private _cancelLockRetry(): void {
        if (this._lockRetryTimeoutId !== null) {
            clearTimeout(this._lockRetryTimeoutId);
            this._lockRetryTimeoutId = null;
        }
    }

    /** Unlocks pointer lock. Used by Main.checkGameOver(). */
    unlock(): void {
        if (this._controls && typeof this._controls.unlock === 'function') {
            this._controls.unlock();
        }
    }

    /**
     * Cancels any pending pointer lock acquisition monitoring (timers and listeners)
     * and any pending deferred lock retry.
     *
     * Call this before requesting a new lock when a previous lock attempt may still
     * have its acquisition timeout in flight (e.g. user pressed ESC during COUNTDOWN
     * then immediately clicks Play — the old _loadingTimeoutId would otherwise fire
     * onAcquisitionFailed while the new lock request is already in progress).
     */
    cancelAcquisition(): void {
        this._cancelLockRetry();
        this._clearPointerLockAcquisition();
    }

    /**
     * Cleans up all timers, event listeners, and disposes controls.
     * Safe to call multiple times.
     */
    dispose(): void {
        if (this._mouseDeltaClampHandler) {
            // Must match the { capture: true } flag used during addEventListener
            document.removeEventListener('mousemove', this._mouseDeltaClampHandler, { capture: true });
            this._mouseDeltaClampHandler = null;
        }
        this._cancelLockRetry();
        this._clearPointerLockAcquisition();

        if (this._controls) {
            this._controls.removeEventListener('lock' as never, this._onControlsLock);
            this._controls.removeEventListener('unlock' as never, this._onControlsUnlock);
            // PointerLockWrapper.dispose() handles pointer lock cleanup + underlying controls disposal
            this._controls.dispose();
            this._controls = null;
        }

        this._callbacks = null;
        this._unlockInProgress = false;
    }

    // --- Private: lock/unlock handlers ---

    /** Called when PointerLockControls fires 'lock' event */
    private _onControlsLock = (): void => {
        this._callbacks?.onLock();
    };

    /** Called when PointerLockControls fires 'unlock' event, with debounce */
    private _onControlsUnlock = (): void => {
        if (this._unlockInProgress) {
            return;
        }
        this._unlockInProgress = true;

        this._callbacks?.onUnlock();

        setTimeout(() => {
            this._unlockInProgress = false;
        }, GameConfig.UNLOCK_RESET_DELAY_MS);
    };

    // --- Private: pointer lock acquisition monitoring ---

    /**
     * Sets up acquisition monitoring with a loading timeout for self-recovery.
     * The pointerlockchange listener cleans up as soon as the lock is confirmed,
     * so the watchdog (_loadingTimeoutId) is the only outstanding timer while
     * the lock request is in flight.
     */
    private _setupPointerLockAcquisition(): void {
        this._pointerLockAcquiredHandler = (): void => {
            if (!document.pointerLockElement) return;

            // Lock confirmed — tear down the listener and cancel the watchdog.
            this._clearPointerLockAcquisition();
        };

        document.addEventListener('pointerlockchange', this._pointerLockAcquiredHandler);

        // Fallback timeout if pointer lock is never acquired
        this._loadingTimeoutId = setTimeout(() => {
            this._clearPointerLockAcquisition();
            if (!document.pointerLockElement) {
                this._callbacks?.onAcquisitionFailed(); // Self-recover
            }
        }, GameConfig.LOADING_TIMEOUT_MS);
    }

    /** Clears all acquisition monitoring timers and listeners */
    private _clearPointerLockAcquisition(): void {
        if (this._pointerLockAcquiredHandler) {
            document.removeEventListener('pointerlockchange', this._pointerLockAcquiredHandler);
            this._pointerLockAcquiredHandler = null;
        }
        if (this._loadingTimeoutId) {
            clearTimeout(this._loadingTimeoutId);
            this._loadingTimeoutId = null;
        }
    }
}
