import { logInfo, logError } from 'logger/log';

/**
 * Game state string literal union type for TargetPracticeGame.
 * Defines all possible states the game can be in.
 */
export type GameStateValue = keyof typeof GameState;

/**
 * Game state enumeration for TargetPracticeGame
 * Defines all possible states the game can be in
 */
export const GameState = {
    UNINITIALIZED: 'UNINITIALIZED',
    INITIALIZING: 'INITIALIZING',
    READY: 'READY',
    COUNTDOWN: 'COUNTDOWN',
    PLAYING: 'PLAYING',
    GAME_OVER: 'GAME_OVER',
    /** User pressed ESC during COUNTDOWN or PLAYING — engine stays alive, match data cleared on next resetMatch() */
    CANCELLED: 'CANCELLED',
    /** Brief synchronous state entered on "play again" from CANCELLED or GAME_OVER — clears match data and re-requests pointer lock */
    RESETING: 'RESETING',
    CLEANING_UP: 'CLEANING_UP',
} as const;

/** State change listener callback signature */
type StateChangeListener = (oldState: GameStateValue, newState: GameStateValue, context: Record<string, unknown>) => void;

/** State enter/exit listener callback signature */
type StateEventListener = (context: Record<string, unknown>) => void;

/**
 * Valid state transitions for the game
 * Prevents invalid state changes
 */
const VALID_TRANSITIONS: Readonly<Record<GameStateValue, GameStateValue[]>> = {
    [GameState.UNINITIALIZED]: [GameState.INITIALIZING],
    [GameState.INITIALIZING]: [GameState.READY, GameState.CLEANING_UP],
    [GameState.READY]: [GameState.COUNTDOWN, GameState.CLEANING_UP],
    [GameState.COUNTDOWN]: [GameState.PLAYING, GameState.CANCELLED, GameState.CLEANING_UP],
    [GameState.PLAYING]: [GameState.GAME_OVER, GameState.CANCELLED, GameState.CLEANING_UP],
    [GameState.GAME_OVER]: [GameState.RESETING, GameState.CLEANING_UP],
    [GameState.CANCELLED]: [GameState.RESETING, GameState.CLEANING_UP],
    [GameState.RESETING]: [GameState.COUNTDOWN, GameState.CLEANING_UP],
    [GameState.CLEANING_UP]: [GameState.UNINITIALIZED],
} as const;

/**
 * GameStateMachine manages the game's state transitions
 * Ensures only valid state changes occur and provides hooks for state changes
 */
export class GameStateMachine {
    private _currentState: GameStateValue;
    private _previousState: GameStateValue | null = null;
    private _stateChangeListeners: StateChangeListener[] = [];
    private _stateEnterListeners: Map<GameStateValue, StateEventListener[]> = new Map();
    private _stateExitListeners: Map<GameStateValue, StateEventListener[]> = new Map();

    constructor(initialState: GameStateValue = GameState.UNINITIALIZED) {
        this._currentState = initialState;
    }

    /**
     * Get the current state
     * @returns {GameStateValue} Current game state
     */
    get currentState(): GameStateValue {
        return this._currentState;
    }

    /**
     * Get the previous state
     * @returns {GameStateValue | null} Previous game state
     */
    get previousState(): GameStateValue | null {
        return this._previousState;
    }

    /**
     * Check if the game is in a specific state
     * @param state - State to check
     * @returns {boolean} True if in the specified state
     */
    is(state: GameStateValue): boolean {
        return this._currentState === state;
    }

    /**
     * Check if the game is in any of the specified states
     * @param states - States to check
     * @returns {boolean} True if in any of the specified states
     */
    isAnyOf(...states: GameStateValue[]): boolean {
        return states.includes(this._currentState);
    }

    /**
     * Check if a transition to the target state is valid
     * @param targetState - Target state
     * @returns {boolean} True if transition is valid
     */
    canTransitionTo(targetState: GameStateValue): boolean {
        const validTransitions: GameStateValue[] | undefined = VALID_TRANSITIONS[this._currentState];
        return validTransitions !== undefined && validTransitions.includes(targetState);
    }

    /**
     * Transition to a new state
     * @param newState - Target state
     * @param context - Optional context data for the transition
     * @throws {Error} If transition is invalid
     */
    transitionTo(newState: GameStateValue, context: Record<string, unknown> = {}): void {
        if (!this.canTransitionTo(newState)) {
            throw new Error(
                `Invalid state transition: ${this._currentState} -> ${newState}. ` +
                `Valid transitions from ${this._currentState}: ${VALID_TRANSITIONS[this._currentState]?.join(', ') || 'none'}`,
            );
        }

        const oldState: GameStateValue = this._currentState;

        // Call exit listeners for old state
        this._callStateExitListeners(oldState, context);

        // Update state
        this._previousState = oldState;
        this._currentState = newState;

        // Call enter listeners for new state
        this._callStateEnterListeners(newState, context);

        // Call general state change listeners
        this._callStateChangeListeners(oldState, newState, context);

        logInfo(`[GameStateMachine] ${oldState} -> ${newState}`, context, true);
    }

    /**
     * Add a listener for any state change
     * @param callback - Callback function (oldState, newState, context) => void
     */
    onStateChange(callback: StateChangeListener): void {
        this._stateChangeListeners.push(callback);
    }

    /**
     * Add a listener for entering a specific state
     * @param state - State to listen for
     * @param callback - Callback function (context) => void
     */
    onStateEnter(state: GameStateValue, callback: StateEventListener): void {
        if (!this._stateEnterListeners.has(state)) {
            this._stateEnterListeners.set(state, []);
        }
        this._stateEnterListeners.get(state)!.push(callback);
    }

    /**
     * Add a listener for exiting a specific state
     * @param state - State to listen for
     * @param callback - Callback function (context) => void
     */
    onStateExit(state: GameStateValue, callback: StateEventListener): void {
        if (!this._stateExitListeners.has(state)) {
            this._stateExitListeners.set(state, []);
        }
        this._stateExitListeners.get(state)!.push(callback);
    }

    /**
     * Remove all listeners
     */
    clearListeners(): void {
        this._stateChangeListeners = [];
        this._stateEnterListeners.clear();
        this._stateExitListeners.clear();
    }

    /**
     * Reset the state machine to initial state
     */
    reset(): void {
        this._currentState = GameState.UNINITIALIZED;
        this._previousState = null;
    }

    // Private methods

    private _callStateChangeListeners(oldState: GameStateValue, newState: GameStateValue, context: Record<string, unknown>): void {
        this._stateChangeListeners.forEach((callback) => {
            try {
                callback(oldState, newState, context);
            } catch (error) {
                logError('[GameStateMachine] Error in state change listener:', error, true);
            }
        });
    }

    private _callStateEnterListeners(state: GameStateValue, context: Record<string, unknown>): void {
        const listeners: StateEventListener[] | undefined = this._stateEnterListeners.get(state);
        if (listeners) {
            listeners.forEach((callback) => {
                try {
                    callback(context);
                } catch (error) {
                    logError(`[GameStateMachine] Error in state enter listener for ${state}:`, error, true);
                }
            });
        }
    }

    private _callStateExitListeners(state: GameStateValue, context: Record<string, unknown>): void {
        const listeners: StateEventListener[] | undefined = this._stateExitListeners.get(state);
        if (listeners) {
            listeners.forEach((callback) => {
                try {
                    callback(context);
                } catch (error) {
                    logError(`[GameStateMachine] Error in state exit listener for ${state}:`, error, true);
                }
            });
        }
    }
}
