import { logWarning } from 'logger/log';
import { getLang } from 'modules/base';
import CrosshairReticle from '../resources/textures/T_Crosshair_Dot.png';

const { STRING, STRINGS } = getLang();

/**
 * HudManager owns the full lifecycle of in-game HUD DOM elements.
 *
 * It creates, shows/hides, updates, and disposes the crosshair,
 * countdown overlay, and progress bar — all of which are manipulated
 * imperatively by the game loop.
 */

/** CSS class names applied to individual target bullets in the progress bar */
const BULLET_CLASS = {
    PENDING: 'hud-progress-pending',
    HIT: 'hud-progress-hit',
    MISSED: 'hud-progress-missed',
} as const;

interface HudElements {
    /** Root container appended to document.body — removing this removes everything */
    container: HTMLDivElement;
    crosshair: HTMLImageElement;
    countdown: HTMLDivElement;
    topBar: HTMLDivElement;
    progressIndicator: HTMLDivElement;
    /** Individual bullet divs keyed by index (0 … gameLength-1) */
    bullets: HTMLDivElement[];
}

export class HudManager {
    private elements: HudElements | null = null;
    private readonly gameLength: number;

    constructor(gameLength: number) {
        this.gameLength = gameLength;
    }

    /**
     * Creates all HUD DOM elements and appends them to document.body.
     * Safe to call multiple times — subsequent calls are no-ops until dispose() is called.
     */
    create(): void {
        if (this.elements) {
            return;
        }

        const container = document.createElement('div');
        container.className = 'dpi-tester-game-hud-container';
        // Hidden at creation — shown only when pointer lock is acquired (game starts).
        // Prevents a brief HUD flash before rendering of the instructions panel.
        container.style.display = 'none';

        // --- Crosshair ---
        const crosshair = document.createElement('img');
        crosshair.className = 'dpi-tester-crosshair';
        crosshair.src = CrosshairReticle;
        crosshair.alt = STRING(STRINGS.DPI_TESTER_CROSSHAIR_RETICLE_ALT);
        container.appendChild(crosshair);

        // --- Countdown ---
        const countdown = document.createElement('div');
        countdown.className = 'dpi-tester-hud-countdown';
        container.appendChild(countdown);

        // --- Top bar ---
        const topBar = document.createElement('div');
        topBar.className = 'dpi-tester-hud-top-bar';

        // Instructions section (Esc key hint)
        const instructions = document.createElement('div');
        instructions.className = 'dpi-tester-hud-instructions';

        const btnToUse = document.createElement('div');
        btnToUse.className = 'btn-to-use';
        btnToUse.textContent = 'Esc';

        const settingsLabel = document.createElement('div');
        settingsLabel.textContent = STRING(STRINGS.DPI_TESTER_HUD_SETTINGS);

        instructions.appendChild(btnToUse);
        instructions.appendChild(settingsLabel);
        topBar.appendChild(instructions);

        // Progress section
        const progress = document.createElement('div');
        progress.className = 'dpi-tester-hud-progress';

        const progressIndicator = document.createElement('div');
        progressIndicator.className = 'dpi-tester-hud-progress-indicator';
        progress.appendChild(progressIndicator);

        const bullets: HTMLDivElement[] = [];
        for (let i = 0; i < this.gameLength; i++) {
            const bullet = document.createElement('div');
            bullet.className = `dpi-tester-target-bullet ${BULLET_CLASS.PENDING}`;
            progress.appendChild(bullet);
            bullets.push(bullet);
        }

        topBar.appendChild(progress);
        container.appendChild(topBar);

        document.body.appendChild(container);

        this.elements = {
            container,
            crosshair,
            countdown,
            topBar,
            progressIndicator,
            bullets,
        };
    }

    /**
     * Shows the HUD container and its children (crosshair, countdown, top bar).
     * Called when pointer lock is acquired (game starts).
     */
    show(): void {
        if (!this.elements) return;

        this.elements.container.style.display = '';
        this.elements.crosshair.style.display = 'block';
        this.elements.topBar.style.display = 'flex';
        this.elements.countdown.style.display = 'block';
    }

    /**
     * Hides the HUD container and its children (crosshair, countdown, top bar).
     * Called when pointer lock is released (game pauses/ends).
     */
    hide(): void {
        if (!this.elements) return;

        this.elements.crosshair.style.display = 'none';
        this.elements.topBar.style.display = 'none';
        this.elements.countdown.style.display = 'none';
    }

    /**
     * Updates the countdown text displayed in the center of the screen.
     *
     * @param value - The countdown string to display ('3', '2', '1', or '')
     */
    updateCountdown(value: string): void {
        if (!this.elements) return;

        this.elements.countdown.innerHTML = value;
    }

    /**
     * Updates the progress indicator text and marks a specific bullet as hit or missed.
     *
     * @param targetIndex - Zero-based index of the target bullet to update
     * @param isHit - Whether the target was hit (true) or missed (false)
     */
    updateProgress(targetIndex: number, isHit: boolean): void {
        if (!this.elements) return;

        this.elements.progressIndicator.textContent = `${targetIndex + 1}/${this.gameLength}`;

        const bullet = this.elements.bullets[targetIndex];
        if (bullet) {
            bullet.className = isHit ? BULLET_CLASS.HIT : BULLET_CLASS.MISSED;
        }
    }

    /**
     * Resets all bullets to pending state and clears the progress indicator.
     */
    resetProgress(): void {
        if (!this.elements) return;

        this.elements.progressIndicator.textContent = `0/${this.gameLength}`;

        for (let i = 0; i < this.elements.bullets.length; i++) {
            this.elements.bullets[i].className = BULLET_CLASS.PENDING;
        }
    }

    /**
     * Removes all HUD DOM elements from the document and nullifies internal references.
     * After calling dispose(), create() can be called again to re-create the HUD.
     */
    dispose(): void {
        if (!this.elements) return;

        try {
            if (this.elements.container.parentElement) {
                this.elements.container.parentElement.removeChild(this.elements.container);
            }
        } catch (e) {
            logWarning('[HudManager] Failed to remove HUD container:', e, true);
        }

        this.elements = null;
    }
}
