import type * as THREE from 'three';
import { FittsLaw, FittsAnalysisResult } from './FittsLaw';
import { StatisticsEntry } from '../types';

// Constants
const RADIUS_TO_DIAMETER = 2;
const MILLISECONDS_TO_SECONDS = 1000.0;

/** Tracks per-target metrics for Fitts' Law analysis */
interface CurrentTargetMetrics {
    startTime: number;
    position: THREE.Vector3;
    radius: number;
    angularDistance: number;
    distance: number;
}

/** Completed target metrics stored for session analysis */
interface TargetMetric {
    targetIndex: number;
    distance: number;
    width: number;
    movementTime: number;
    wasHit: boolean;
    hitDistance: number | null;
}

export class Statistics {
    private shotsToComplete: number;
    private dpiX: string | null = null;
    private currentTime = 0.0;
    private killStreak = 0;
    private missedTargetsCount = 0;
    private correctTargetsCount = 0;
    private perfectHits = 0;
    private missedShots = 0;
    private undershoots = 0;
    private overshoots = 0;
    private sessionStartTime: number | null = null;
    private sessionEndTime: number | null = null;
    private targetMetrics: TargetMetric[] = [];
    private currentTarget: CurrentTargetMetrics | null = null;

    constructor(gameLength: number) {
        this.shotsToComplete = gameLength;
    }

    reset(): void {
        this.currentTime = 0.0;

        this.killStreak = 0;
        this.missedTargetsCount = 0;
        this.correctTargetsCount = 0;

        this.perfectHits = 0;
        this.missedShots = 0;
        this.undershoots = 0;
        this.overshoots = 0;

        // Session timing
        this.sessionStartTime = null;
        this.sessionEndTime = null;

        // Fitts' Law tracking
        this.targetMetrics = [];
        this.currentTarget = null;
    }

    /**
     * Set the DPI value for this session.
     * @param dpiX - The DPI value
     */
    setDpiX(dpiX: string | null): void {
        this.dpiX = dpiX;
    }

    /**
     * Compute accuracy as a percentage (0-100).
     * @returns {number} Accuracy percentage
     */
    computeAccuracy(): number {
        if (this.shotsToComplete === 0) return 0;
        return (this.correctTargetsCount * 100.0) / this.shotsToComplete;
    }

    startRecordingTime(): void {
        this.sessionStartTime = performance.now();
    }

    stopRecordingTime(): void {
        this.sessionEndTime = performance.now();
    }

    computeElapsedTimeMs(): number {
        this.currentTime = (this.sessionEndTime ?? 0) - (this.sessionStartTime ?? 0);
        return this.currentTime;
    }

    // Performance recording

    /** Record a perfect hit (no overshoot or undershoot) */
    recordPerfectHit(): void {
        this.perfectHits++;
    }

    /** Record a missed shot (clicked but didn't hit target) */
    recordMissedShot(): void {
        this.missedShots++;
    }

    /** Record an undershoot event for the current target */
    recordUndershoot(): void {
        this.undershoots++;
    }

    /** Record an overshoot event for the current target */
    recordOvershoot(): void {
        this.overshoots++;
    }

    /**
     * Start tracking a new target for Fitts' Law metrics.
     * @param {THREE.Vector3} targetPosition - Position of the new target
     * @param {THREE.Vector3} cameraPosition - Camera position for distance calculation
     * @param {number} initialAngularDistance - Initial angular distance from crosshair to target (degrees)
     * @param {number} targetRadius - Physical radius of the target
     */
    startTargetMetrics(
        targetPosition: THREE.Vector3,
        cameraPosition: THREE.Vector3,
        initialAngularDistance = 0,
        targetRadius = 0.042,
    ): void {
        this.currentTarget = {
            startTime: performance.now(),
            position: targetPosition.clone(),
            radius: targetRadius,
            angularDistance: Math.abs(initialAngularDistance),
            distance: cameraPosition.distanceTo(targetPosition),
        };
    }

    /**
     * Complete target metrics tracking when hit or missed.
     * @param wasHit - Whether the target was hit
     * @param hitDistance - Actual distance from hit point to target center (null for misses)
     */
    completeTargetMetrics(wasHit: boolean, hitDistance: number | null = null): void {
        if (this.currentTarget === null) {
            return;
        }

        const { startTime, radius, angularDistance, distance } = this.currentTarget;

        const movementTime: number = (performance.now() - startTime) / MILLISECONDS_TO_SECONDS;
        const targetIndex: number = this.correctTargetsCount + this.missedTargetsCount;

        // Use angular measurements for Fitts' Law (degrees)
        // Distance: initial angular distance from crosshair to target
        // Width: angular diameter of target (converted from physical size)

        // Calculate angular width: θ = 2 * arctan(r / d)
        const angularRadiusRad: number = Math.atan(radius / distance);
        const angularRadiusDeg: number = angularRadiusRad * (180 / Math.PI);
        const angularWidth: number = angularRadiusDeg * RADIUS_TO_DIAMETER;

        // Convert hit distance from physical to angular (if hit occurred)
        let angularHitDistance: number | null = null;
        if (hitDistance !== null && distance > 0) {
            const hitAngularRadiusRad: number = Math.atan(hitDistance / distance);
            angularHitDistance = hitAngularRadiusRad * (180 / Math.PI);
        }

        this.targetMetrics.push({
            targetIndex,
            distance: angularDistance,
            width: angularWidth,
            movementTime,
            wasHit,
            hitDistance: angularHitDistance,
        });

        // Reset for next target
        this.currentTarget = null;
    }

    /**
     * Calculate Fitts' Law analysis for the session.
     * @returns {FittsAnalysisResult} Fitts' Law metrics
     */
    computeFittsLawAnalysis(): FittsAnalysisResult {
        const validTargets: TargetMetric[] = this.targetMetrics.filter(t => t.wasHit && t.movementTime > 0);
        if (validTargets.length === 0) {
            return { throughput: 0, averageID: 0, averageMT: 0, effectiveWidth: 0 };
        }
        return FittsLaw.analyzeFittsLaw(validTargets);
    }

    // Kill streak

    getKillStreak(): number {
        return this.killStreak;
    }

    incrementKillStreak(): void {
        ++this.killStreak;
    }

    resetKillStreak(): void {
        this.killStreak = 0;
    }

    // Hit targets

    getHitTargets(): number {
        return this.correctTargetsCount;
    }

    incrementHitTargets(): void {
        ++this.correctTargetsCount;
        this.incrementKillStreak();
    }

    resetHitTargets(): void {
        this.correctTargetsCount = 0;
    }

    // Missed targets

    getMissedTargets(): number {
        return this.missedTargetsCount;
    }

    incrementMissedTargets(): void {
        ++this.missedTargetsCount;
        this.resetKillStreak();
    }

    resetMissedTargets(): void {
        this.missedTargetsCount = 0;
    }

    /**
     * Compile session statistics into a raw data object.
     * UI formatting (e.g. "123ms", "5/10") should be done by the consumer.
     * @returns {StatisticsEntry} Raw statistics data
     */
    compile(): StatisticsEntry {
        const fittsLaw: FittsAnalysisResult = this.computeFittsLawAnalysis();
        const accuracy: number = this.computeAccuracy();

        return {
            dpiX: this.dpiX !== null ? String(this.dpiX) : null,
            averageMT: fittsLaw.averageMT,
            performance: fittsLaw.throughput * 1000.0 * (accuracy / 100.0),
            accuracy,
            hits: this.correctTargetsCount,
            total: this.shotsToComplete,
            overshoots: this.overshoots,
            undershoots: this.undershoots,
            perfectHits: this.perfectHits,
        };
    }
}
