/**
 * Centralized game configuration — single source of truth.
 *
 * All tunable parameters for the DPI Tester (TargetPracticeGame) are defined here.
 * Consumer modules import the specific constants they need instead of defining local copies.
 *
 * This makes it easy to:
 * - Adjust game balance from one place
 * - Configure for different use cases
 * - Maintain consistent values across the codebase
 * - Document all configurable parameters
 *
 * Constants that are NOT included here:
 * - Research algorithm constants (MovementPhaseAnalysis, FittsLaw ISO constants)
 * - Mathematical constants (RADIUS_TO_DIAMETER, MILLISECONDS_TO_SECONDS)
 * - Structural definitions (QUADRANT_ANGLES — directional enum, not a tunable)
 */
export const GameConfig = {
    // ── Game Settings ──────────────────────────────────────────────
    /** Number of targets to hit per round */
    GAME_LENGTH: 20,

    // ── Timing ─────────────────────────────────────────────────────
    /** Duration of each countdown step (ms) */
    COUNTDOWN_STEP_MS: 1000,
    /**
     * Number of render frames to skip after pointer lock acquisition before
     * starting the countdown clock. This ensures the WebGL canvas is composited
     * on screen before the first countdown tick fires.
     *
     * At 60 fps, 2 frames ≈ 33 ms — enough for Windows DWM to complete its
     * focus/compositor transition without the over-long fixed delay that caused
     * premature beeps on 2nd/3rd plays.
     */
    COUNTDOWN_WARMUP_FRAMES: 2,
    /** Default detune (cents) for countdown beeps */
    COUNTDOWN_DETUNE_DEFAULT: 200,
    /** Detune (cents) for the final "Go" beep */
    COUNTDOWN_DETUNE_GO: 900,
    /** Minimum delay between shots (ms) */
    RATE_OF_FIRE_DELAY_MS: 150,
    /** Delay before retrying reinitialization after cleanup (ms) */
    REINITIALIZATION_RETRY_MS: 50,
    /** Duration of the lerp animation when a target relocates (ms) */
    TARGET_LERP_DURATION_MS: 50,
    /** Delay (ms) before re-enabling Play after first mouse move post-game-over (absorbs OS cursor snap) */
    ACCIDENTAL_RESTART_GUARD_MOVEMENT_DELAY_MS: 500,
    /** Fallback (ms) to re-enable Play if the mouse is never moved after game over */
    ACCIDENTAL_RESTART_GUARD_FALLBACK_MS: 1000,

    // ── Camera ─────────────────────────────────────────────────────
    /** Field of view in degrees */
    CAMERA_FOV: 75,
    /** Near clipping plane */
    CAMERA_NEAR_PLANE: 0.01,
    /** Far clipping plane */
    CAMERA_FAR_PLANE: 1000,
    /** Minimum camera movement distance to trigger billboard updates */
    CAMERA_MOVEMENT_THRESHOLD: 0.01,
    /**
     * Polar angle limits (radians) for PointerLockControls pitch clamping.
     *
     * Three.js PointerLockControls uses polar angle convention:
     *   - 0 radians  = looking straight up   (pitch = +90°)
     *   - π/2 radians = looking straight ahead (pitch =   0°)
     *   - π radians  = looking straight down  (pitch = -90°)
     *
     * The camera quaternion Euler decomposition becomes numerically degenerate
     * (gimbal lock) when pitch reaches exactly ±90° (polar angle = 0 or π).
     * At that singularity, yaw and roll are indistinguishable — any subsequent
     * horizontal mouse delta can produce a wild camera snap.
     *
     * Clamping to [0.05, π − 0.05] (~3° margin from vertical) prevents the
     * camera from reaching the singularity while preserving the full practical
     * look range for a DPI tester.
     */
    CAMERA_MIN_POLAR_ANGLE: 0.05, // ≈3° from straight up
    CAMERA_MAX_POLAR_ANGLE: Math.PI - 0.05, // ≈3° from straight down
    /**
     * Maximum raw mouse delta (pixels) allowed per single `mousemove` event.
     *
     * On Windows, high-report-rate mice (e.g. 8000 Hz) or OS-buffered input can
     * deliver a single `mousemove` event with |movementX| or |movementY| in the
     * hundreds or even negative-thousands of pixels. When fed directly into
     * PointerLockControls (_euler.y -= movementX * 0.002 * pointerSpeed), a value
     * of −600 produces a ~69° yaw rotation in a single frame — visible as a violent
     * camera snap. Clamping to ±150 pixels caps the per-event contribution to ~17°,
     * which still allows fast flicks while preventing pathological input spikes.
     */
    MAX_MOUSE_DELTA_PER_EVENT: 150,

    // ── Player ─────────────────────────────────────────────────────
    /** Player eye height in game units (1.8m) */
    PLAYER_HEIGHT: 0.018,
    /** Walking speed */
    WALK_SPEED: 8.0,
    /** Sprinting speed */
    SPRINT_SPEED: 14.0,
    /** Maximum distance from level center before player is teleported back */
    MAX_DISTANCE_FROM_CENTER: 0.1,

    // ── Controls ───────────────────────────────────────────────────
    /** Timeout (ms) for pointer lock acquisition before self-recovering */
    LOADING_TIMEOUT_MS: 1500,
    /** Delay (ms) to debounce rapid unlock events */
    UNLOCK_RESET_DELAY_MS: 100,
    /** Delay (ms) before retrying a failed pointer lock request */
    POINTER_LOCK_RETRY_DELAY_MS: 500,
    /** Delay (ms) before checking pointer lock status after an error */
    POINTER_LOCK_CHECK_DELAY_MS: 100,

    // ── Target Geometry ────────────────────────────────────────────
    TARGET_GEOMETRY: {
        CIRCLE_RADIUS: 0.034,
        CIRCLE_SEGMENTS: 32,
        RING_INNER_RADIUS: 0.038,
        RING_OUTER_RADIUS: 0.042,
        RING_SEGMENTS: 64,
    },

    // ── Target Positioning ─────────────────────────────────────────
    TARGET_POSITIONING: {
        MIN_X: -0.6,
        MAX_X: 0.6,
        MIN_Y: -0.1,
        MAX_Y: 0.5,
        Z_POSITION: -1,
        /** Minimum distance from previous target — increased for proper flicks */
        MIN_DISTANCE_FROM_LAST: 0.3,
        /** Minimum distance from camera/player origin */
        MIN_DISTANCE_FROM_CENTER: 0.3,
        /** Maximum attempts to find a valid position per quadrant */
        MAX_POSITION_ATTEMPTS: 20,
        /** Minimum distance from cursor center */
        MIN_DISTANCE_FROM_CURSOR: 0.2,
        /** Maximum distance from cursor center */
        MAX_DISTANCE_FROM_CURSOR: 1.0,
        /** Degrees of random variation within quadrant (±) */
        QUADRANT_ANGLE_VARIATION: 20,
        /** Shrink vertical component to 50% of horizontal */
        VERTICAL_SHRINK_FACTOR: 0.5,
        /** Maximum absolute vertical offset from cursor center */
        MAX_VERTICAL_OFFSET: 0.3,
        /** Static upward bias to avoid ground overlap */
        VERTICAL_UPWARD_BIAS: 0.1,
    },

    // ── Target Visual ──────────────────────────────────────────────
    TARGET_VISUAL: {
        EMISSIVE_INTENSITY: 1.5,
        FLASH_INTENSITY: 2,
        FLASH_DURATION_MS: 200,
    },

    /** Number of random variations to try per quadrant before moving on */
    TARGET_ATTEMPTS_PER_QUADRANT: 5,

    /** Default target color (white) */
    TARGET_COLOR: 0xffffff,
    /** Target ring color when hovering (green) */
    COLOR_TARGET_HOVER: 0x00ff00,
    /** Target ring flash color on miss (red) */
    COLOR_TARGET_MISS: 0xf6056d,

    // ── Audio ──────────────────────────────────────────────────────
    /** Master volume multiplier for all SFX */
    MASTER_VOLUME: 0.8,
    /** Per-SFX volume levels (relative to master volume) */
    SFX_VOLUMES: {
        fire: 0.4,
        hit_confirm: 0.8,
        miss: 0.6,
        destroy: 0.5,
        countdown: 0.9,
        teleport: 0.6,
    },
    /** Maximum random detune range for fire sound (cents) */
    FIRE_DETUNE_RANGE: 120,

    // ── Rendering ──────────────────────────────────────────────────
    /** Tone mapping exposure */
    TONE_MAPPING_EXPOSURE: 1,
    /** Post-processing bloom settings */
    BLOOM: {
        THRESHOLD: 0,
        STRENGTH: 0.25,
        RADIUS: 0.0,
        RESOLUTION: { WIDTH: 1024, HEIGHT: 1024 },
    },

    // ── Scene ──────────────────────────────────────────────────────
    /** Deep blue — top of the sky dome */
    SKY_TOP_COLOR: 0x0057ff,
    /** Light cyan — middle sky and fog */
    SKY_COLOR: 0xaaf9ff,
    /** Bright cyan — ground plane */
    GROUND_COLOR: 0x00def1,
    /** Fog distance range */
    FOG: { NEAR: 1, FAR: 400 },
    /** Floor plane Y position */
    FLOOR_Y_POSITION: -70,
    /** Sky ceiling Y position */
    SKY_Y_POSITION: 150,
    /** Sky dome gradient shader uniforms */
    SKY_GRADIENT: { OFFSET: 33, EXPONENT: 0.6 },

    // ── Ground Material ────────────────────────────────────────────
    GROUND_MATERIAL: {
        COLOR: 0xcfcfcf,
        EMISSIVE: 0xe4e4e4,
        EMISSIVE_INTENSITY: 1.5,
    },

    // ── Lighting ───────────────────────────────────────────────────
    /** Hemisphere light intensity */
    HEMISPHERE_LIGHT_INTENSITY: 5,
    /** Directional light intensity */
    DIRECTIONAL_LIGHT_INTENSITY: 2.0,
    /** Shadow mapping configuration */
    SHADOW: {
        MAP_SIZE: 2048,
        CAMERA_SIZE: 50,
        FAR: 3500,
        BIAS: -0.0001,
    },

    // ── Statistics / Analysis ──────────────────────────────────────
    /** Minimum number of movement samples before analysis begins */
    ANALYSIS_WINDOW_MIN: 5,
    /** Minimum amplitude threshold to filter out sensor noise (degrees) */
    MIN_OVERSHOOT_AMPLITUDE_DEG: 1.0,
} as const;
