import { useEffect, useRef, useCallback, useState } from 'react';
import { logError } from 'logger/log';
import { LoadingSpinner } from 'modules/features/game-launcher/components/common';
import { TargetPracticeGame } from './game/Main';
import GameInstructionsPopup from './components/GameInstructionsPopup';
import { useAccidentalRestartGuard, useActiveDpiValue, useActiveDeviceGuard, useGameState, useGameStatistics } from './hooks';

import './DpiTesterOverlay.scss';

function DpiTesterOverlay() {
    const overlayRef = useRef<HTMLElement | null>(null);
    const gameRef = useRef<TargetPracticeGame | null>(null);
    const [gameInstance, setGameInstance] = useState<TargetPracticeGame | null>(null);

    /**
     * Navigates back to home when the active device is disconnected while
     * the DPI Tester is open.
     */
    useActiveDeviceGuard();

    const activeDpi = useActiveDpiValue();

    const {
        isInitializing,
        isUninitialized,
        isReady,
        isGameOver,
        isCleaningUp,
        isCancelled,
        isReseting,
    } = useGameState(gameInstance);

    const { history: statsHistory, recommendation } = useGameStatistics(gameInstance);

    /**
     * Prevents accidental game restarts after pointer lock is released.
     * When the game ends, the OS cursor snaps back to its pre-lock position
     * (typically on top of the Play button). This guard disables the Play button
     * until the user deliberately moves the mouse.
     */
    const { isAwaitingMouseMove } = useAccidentalRestartGuard(isGameOver);

    useEffect(() => {
        const game = new TargetPracticeGame();
        gameRef.current = game;
        setGameInstance(gameRef.current);

        gameRef.current.initialize();

        return () => {
            if (gameRef.current) {
                gameRef.current.cleanUp().catch((error: unknown) => {
                    logError('DpiTester - DpiTesterOverlay - Failed to clean up game on unmount', { error });
                });
            }
            overlayRef.current = null;
            gameRef.current = null;
        };
    }, []);

    /**
     * Launches or restarts the game session without destroying the engine.
     *
     * First play (READY): calls startGame() → READY → COUNTDOWN via pointer lock.
     * Subsequent plays (CANCELLED or GAME_OVER): calls resetMatch() →
     *   RESETING → pointer lock → COUNTDOWN.
     */
    const launchGame = useCallback(() => {
        if (!gameRef.current) return;

        overlayRef.current = document.querySelector('.overlay');
        overlayRef.current?.style.setProperty('background-color', 'transparent', 'important');

        const game = gameRef.current;

        // Set DPI before starting
        game.setDpi(activeDpi);

        if (isReady) {
            // First play of the session — drives READY → COUNTDOWN via pointer lock.
            game.startGame();
        } else if (isCancelled || isGameOver) {
            // Subsequent plays — drives CANCELLED/GAME_OVER → RESETING → COUNTDOWN.
            // resetMatch() handles the pointer lock request internally.
            game.resetMatch();
        }
    }, [activeDpi, isCancelled, isGameOver, isReady]);

    const showInstructions = isUninitialized || isInitializing || isReady || isCancelled || isGameOver;
    const showLoading = isReseting;

    /**
     * Disable the Play button while:
     * - The engine cannot accept a launchGame() call (uninitialized, initializing, cleaning up)
     * - The cursor has just snapped back to the Play button after pointer lock release and
     *   the user has not yet moved the mouse (prevents accidental immediate restart)
     */
    const isPlayButtonDisabled = isUninitialized || isInitializing || isCleaningUp || isAwaitingMouseMove;

    return (
        <div data-testid="dpi-tester-overlay" aria-live="polite">
            {showInstructions && (
                <GameInstructionsPopup
                    statsHistory={statsHistory}
                    recommendation={recommendation}
                    onStartGame={launchGame}
                    isPlayDisabled={isPlayButtonDisabled}
                />
            )}
            {showLoading && (<LoadingSpinner />)}
        </div>
    );
}

export default DpiTesterOverlay;
