import { Tooltip } from '@logi/magnetite';
import { BodyText, Heading } from 'modules/base/components/typography/Typography';
import { getLang } from 'modules/base';
import { StatisticsEntry } from '../game/types';

const { STRING, STRINGS } = getLang();

interface GameStatisticsPanelProps {
    /** Array of statistics entries from completed game sessions */
    statsHistory: StatisticsEntry[];
    /** Recommendation text based on game performance analysis */
    recommendation: string;
}

function GameStatisticsPanel({ statsHistory, recommendation }: GameStatisticsPanelProps) {
    return (
        <div className="dpi-tester-statistics" data-testid="dpi-tester-statistics">
            <Heading
                level={2}
                className="statistics-title"
                data-testid="dpi-tester-insights-title"
            >
                {STRING(STRINGS.DPI_TESTER_INSIGHTS_TITLE)}
            </Heading>

            <BodyText tag="p" level={2} className="statistics-description" data-testid="dpi-tester-recommendation">
                {recommendation}
            </BodyText>

            <div
                className="stats-table"
                role="table"
                aria-labelledby="dpi-tester-insights-title"
                data-testid="dpi-tester-stats-table"
            >
                <div role="rowgroup">
                    <div
                        className="stats-legend table-row"
                        role="row"
                        data-testid="dpi-tester-stats-legend"
                    >
                        <Tooltip content={STRING(STRINGS.DPI_TESTER_STATS_DPI_TOOLTIP)}>
                            <div className="stats-legend-item" role="columnheader" data-testid="dpi-tester-legend-dpi">
                                {STRING(STRINGS.DPI_TESTER_STATS_DPI)}
                            </div>
                        </Tooltip>
                        <Tooltip content={STRING(STRINGS.DPI_TESTER_STATS_SPEED_TOOLTIP)}>
                            <div className="stats-legend-item" role="columnheader" data-testid="dpi-tester-legend-speed">
                                {STRING(STRINGS.DPI_TESTER_STATS_SPEED)}
                            </div>
                        </Tooltip>
                        <Tooltip content={STRING(STRINGS.DPI_TESTER_STATS_PERFORMANCE_TOOLTIP)}>
                            <div className="stats-legend-item" role="columnheader" data-testid="dpi-tester-legend-performance">
                                {STRING(STRINGS.DPI_TESTER_STATS_PERFORMANCE)}
                            </div>
                        </Tooltip>
                        <Tooltip content={STRING(STRINGS.DPI_TESTER_STATS_HITS_TOOLTIP)}>
                            <div className="stats-legend-item" role="columnheader" data-testid="dpi-tester-legend-hits">
                                {STRING(STRINGS.DPI_TESTER_STATS_HITS)}
                            </div>
                        </Tooltip>
                    </div>
                </div>

                <div className="dpi-tester-stats-container" role="rowgroup">
                    {statsHistory.map((entry, i) => (
                        <div
                            key={`stats-${i}`}
                            className="stats-item"
                            role="row"
                            data-testid={`dpi-tester-stats-row-${i}`}
                        >
                            <div role="cell">{entry.dpiX}</div>
                            <div role="cell">{`${(entry.averageMT * 1000).toFixed(1)}ms`}</div>
                            <div role="cell">{entry.performance.toFixed(0)}</div>
                            <div role="cell">{`${entry.hits}/${entry.total}`}</div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
}

export default GameStatisticsPanel;
