// Constants for event analysis algorithms
const ANALYSIS_CONSTANTS = {
    MIN_DATA_LENGTH: 3,
    MIN_FILTER_SAMPLES: 5,
    MIN_QUANTIZATION_VALUES: 2,
    DEFAULT_PRECISION: 0.001,
    FILTER_ALPHA: 0.15,
    PRE_ENTRY_WINDOW_MS: 200,
    EPSILON_CLAMP_FACTOR: 0.5,
    MAD_SCALING_FACTOR: 1.4826,
    NOISE_THRESHOLD: 0.1,
    ADAPTIVE_VELOCITY_THRESHOLD: 0.5,
    RESEARCH_VELOCITY_THRESHOLD: 0.05,
    DEFAULT_MOVEMENT_ONSET_MS: 100,
    MIN_PEAK_DETECTION_POINTS: 3,
    DEADZONE: 0.05,
    TOLERANCE_LINE_OFFSET: 2,
} as const;

export const DETECTION_CONSTANTS = {
    PAUSE_DURATION_MS: 40,
    SMOOTHING_WINDOW_SAMPLES: 3,
} as const;

/** Result of a backward scan for a paused endpoint */
interface PausedEndpointResult {
    t_p: number;
    found: boolean;
    shortfall_deg?: number;
    correction_time_ms?: number;
}

/** Configuration for backward scan */
interface ScanBackwardConfig {
    e: number[];
    v: number[];
    timestamps: number[];
    tEntry: number;
    tMovementStart: number;
    bandHalfWidth: number;
    vEps: number;
    tauMs?: number;
}

/**
 * Movement phase analysis utilities for aiming task detection
 * Analyzes velocity patterns, movement onset, pauses, and corrections
 */
export class MovementPhaseAnalysis {
    /**
     * Calculate velocity array using negative derivative: v(t) = -de/dt
     * @param e - Error values
     * @param timestamps - Timestamp array
     * @returns {number[]} Velocity array
     */
    static calculateVelocity(e: number[], timestamps: number[]): number[] {
        const v: number[] = new Array(e.length).fill(0);

        for (let i = 1; i < e.length; i++) {
            const dt: number = Math.max(1, timestamps[i] - timestamps[i - 1]);
            v[i] = -(e[i] - e[i - 1]) / dt;
        }

        return v;
    }

    /**
     * Calculate research-standard velocity gate (5% of peak velocity)
     * For use with raw data that hasn't been filtered
     * @param v - Velocity array
     * @returns {number} Research-standard velocity threshold (5% of peak)
     */
    static calculateResearchVelocityGate(v: number[]): number {
        if (!v || v.length === 0) return 0;

        const vPeak: number = Math.max(...v.map(Math.abs));

        // Published standard from motor control literature
        const researchThreshold: number = ANALYSIS_CONSTANTS.RESEARCH_VELOCITY_THRESHOLD * vPeak;

        return researchThreshold;
    }

    /**
     * Detect movement onset at first significant local velocity peak
     * @param v - Velocity array
     * @param vEps - Velocity threshold (0.05 * v_peak)
     * @returns {number} Index of first local maxima above threshold, or -1 if none found
     */
    static detectMovementOnsetByFirstPeak(v: number[], vEps: number): number {
        if (!v || v.length < ANALYSIS_CONSTANTS.MIN_PEAK_DETECTION_POINTS) return -1;

        // Find first significant local maximum above threshold
        for (let i = 1; i < v.length - 1; i++) {
            const prev: number = Math.abs(v[i - 1]);
            const curr: number = Math.abs(v[i]);
            const next: number = Math.abs(v[i + 1]);

            if (curr >= prev && curr >= next && curr > vEps) {
                return i;
            }
        }

        return -1;
    }

    /**
     * Detect velocity pause at a specific position
     * @param v - Velocity array
     * @param timestamps - Timestamp array
     * @param position - Position to check for pause
     * @param vEps - Velocity threshold
     * @param tauMs - Minimum pause duration in milliseconds (default: 40ms)
     * @returns {boolean} True if pause detected
     */
    static detectVelocityPause(
        v: number[],
        timestamps: number[],
        position: number,
        vEps: number,
        tauMs: number = DETECTION_CONSTANTS.PAUSE_DURATION_MS,
    ): boolean {
        if (!v || !timestamps || position < 0 || position >= v.length) return false;

        const avgSampleRate: number =
            timestamps.length > 1 ? (timestamps[timestamps.length - 1] - timestamps[0]) / (timestamps.length - 1) : 1;
        const tauSamples: number = Math.round(tauMs / avgSampleRate);

        // Check for pause window ending at position
        const windowStart: number = Math.max(0, (position - tauSamples) + 1);
        const windowEnd: number = position;

        for (let k = windowStart; k <= windowEnd; k++) {
            if (Math.abs(v[k]) > vEps) {
                return false;
            }
        }

        return true;
    }

    /**
     * Scan backward from entry point to find paused endpoint outside target band
     * Enhanced with movement-bounded search to eliminate pre-movement false positives
     * @param {ScanBackwardConfig} config - Configuration object
     * @returns {PausedEndpointResult} Result object with t_p index and validation info
     */
    static scanBackwardForPausedEndpoint(config: ScanBackwardConfig): PausedEndpointResult {
        const {
            e,
            v,
            timestamps,
            tEntry,
            tMovementStart,
            bandHalfWidth,
            vEps,
            tauMs = DETECTION_CONSTANTS.PAUSE_DURATION_MS,
        } = config;

        if (tEntry < 1 || tMovementStart < 0 || tMovementStart >= tEntry) {
            return { t_p: -1, found: false };
        }

        // Scan only within movement sequence to eliminate pre-movement false positives
        for (let i = tEntry - 1; i >= tMovementStart; i--) {
            // Check if outside target band
            if (Math.abs(e[i]) > bandHalfWidth) {
                // Check for pause at this position
                if (this.detectVelocityPause(v, timestamps, i, vEps, tauMs)) {
                    // Confirm movement resumption after pause
                    const resumed: boolean = this.checkMovementResumption(v, i, tEntry, vEps);

                    if (resumed) {
                        return {
                            t_p: i,
                            found: true,
                            shortfall_deg: Math.abs(e[i]) - bandHalfWidth,
                            correction_time_ms: timestamps[tEntry] - timestamps[i],
                        };
                    }
                }
            } else {
                break;
            }
        }

        return { t_p: -1, found: false };
    }

    /**
     * Check for movement resumption after pause
     * @param v - Velocity array
     * @param tP - Pause endpoint index
     * @param tEntry - Entry index
     * @param vEps - Velocity threshold
     * @returns {boolean} True if movement resumed after pause
     */
    static checkMovementResumption(v: number[], tP: number, tEntry: number, vEps: number): boolean {
        for (let j = tP + 1; j <= tEntry; j++) {
            if (Math.abs(v[j]) > vEps) {
                return true;
            }
        }
        return false;
    }

    /**
     * Calculate correction peak velocity between pause and entry
     * @param v - Velocity array
     * @param tP - Pause endpoint index
     * @param tEntry - Entry index
     * @returns {number} Peak velocity during correction phase
     */
    static calculateCorrectionPeakVelocity(v: number[], tP: number, tEntry: number): number {
        if (tP < 0 || tEntry < 0 || tP >= tEntry || tP >= v.length || tEntry >= v.length) {
            return 0;
        }

        let peakV = 0;
        for (let i = tP; i <= tEntry; i++) {
            const absV: number = Math.abs(v[i]);
            if (absV > peakV) {
                peakV = absV;
            }
        }

        return peakV;
    }
}
