import { GameConfig } from './Config';

/**
 * A class that represents the first person player.
 */
export class FPSPlayer {
    private readonly playerHeight: number = GameConfig.PLAYER_HEIGHT;
    private readonly walkSpeed: number = GameConfig.WALK_SPEED;
    private readonly sprintSpeed: number = GameConfig.SPRINT_SPEED;
    private readonly movementEnabled: boolean;

    constructor(allowMovement: boolean) {
        this.movementEnabled = allowMovement;
    }

    height(): number {
        return this.playerHeight;
    }

    speed(isWalking: boolean): number {
        // Since we deal with delta time and not actual velocity,
        // we have to invert the values.
        return isWalking ? this.walkSpeed : this.sprintSpeed;
    }

    canMove(): boolean {
        return this.movementEnabled;
    }
}
