import { useSelector } from 'react-redux';
import { getActiveMouseSensitivityAssignment } from 'controllers/setting_controller';
import { getMouseSettingsCards } from 'controllers/card_controller';

/**
 * Returns the active DPI value from the mouse sensitivity card settings.
 * Matches the value displayed in the DpiCanvas active row input field.
 *
 * In basic mode: returns `entry.dpi`
 * In advanced mode: returns `entry.dpiX`
 */
export const useActiveDpiValue = (): string | null => {
    const mouseSensitivityCard = useSelector(getActiveMouseSensitivityAssignment);
    const allPresets = useSelector(getMouseSettingsCards);

    const activeDpiIndex = mouseSensitivityCard?.mouseSensitivity?.activeDpiIndex ?? 1;
    const presetId = mouseSensitivityCard?.mouseSensitivity?.presetId;
    const currentCard = allPresets.find((p: { id: string }) => p.id === presetId);

    if (!currentCard?.mouseSettings?.advancedDpiTable?.entries) {
        return null;
    }

    const { entries, advancedEnabled } = currentCard.mouseSettings.advancedDpiTable;
    const entry = entries[activeDpiIndex];

    if (!entry) {
        return null;
    }

    const dpiValue = advancedEnabled ? entry.dpiX : entry.dpi;
    return dpiValue != null ? String(dpiValue) : null;
};
