import type * as THREE from 'three';
import { OvershootAnalyzer } from './statistics/OvershootAnalyzer';
import { UndershootAnalyzer } from './statistics/UndershootAnalyzer';
import { Target } from './Target';
import { Utils } from './utils/Utils';
import { GameConfig } from './Config';

/** Shape of a single movement sample stored in the internal buffer */
interface MovementSample {
    timestamp: number;
    signedErrorRaw: number;
}

/**
 * Result of the current aim analysis for hit/miss classification.
 */
export interface AimAnalysisResult {
    hasOvershoot: boolean;
    hasUndershoot: boolean;
}

/**
 * AimAnalysisSystem encapsulates all per-target aim analysis:
 * signed-angle calculation, dominant error axis locking,
 * movement sample collection, and overshoot/undershoot detection.
 *
 * Owns: OvershootAnalyzer, UndershootAnalyzer, errorAxis state,
 *       and the per-target movement sample buffer.
 * Does NOT own: Camera/Target (passed in per frame).
 */
export class AimAnalysisSystem {
    private readonly overshootAnalyzer: OvershootAnalyzer;
    private readonly undershootAnalyzer: UndershootAnalyzer;
    private errorAxis: 'yaw' | 'pitch' | null;

    /** Per-target movement sample buffer */
    private movementData: MovementSample[];
    private trackingStartTime: number | null;

    constructor() {
        this.overshootAnalyzer = new OvershootAnalyzer();
        this.undershootAnalyzer = new UndershootAnalyzer();
        this.errorAxis = null;
        this.movementData = [];
        this.trackingStartTime = null;
    }

    /**
     * Runs aim analysis for the current frame.
     *
     * Calculates signed yaw/pitch angles from camera to target,
     * locks the dominant error axis on the first sample per target,
     * records the signed error into the internal movement buffer,
     * and runs overshoot/undershoot detection once enough samples exist.
     *
     * @param time - Current timestamp (ms) for movement sample recording
     * @param camera - The player camera for angle calculations
     * @param targetPosition - World position of the current target
     */
    update(
        time: number,
        camera: THREE.Camera,
        targetPosition: THREE.Vector3,
    ): void {
        const { yaw, pitch } = Utils.calculateSignedAngles(camera, targetPosition);

        // Lock to dominant error axis per target for consistent analysis
        if (this.errorAxis === null) {
            this.errorAxis = Math.abs(yaw) >= Math.abs(pitch) ? 'yaw' : 'pitch';
        }

        const signedError = this.errorAxis === 'yaw' ? yaw : pitch;

        // Start tracking on first sample if not already started
        if (this.trackingStartTime === null) {
            this.trackingStartTime = performance.now();
        }

        // Continuous data collection prevents gaps during target transitions
        this.movementData.push({
            timestamp: time - this.trackingStartTime,
            signedErrorRaw: signedError,
        });

        if (this.movementData.length > GameConfig.ANALYSIS_WINDOW_MIN) {
            if (!this.overshootAnalyzer.eventDetected) {
                this.overshootAnalyzer.detectOvershoots(this.movementData);
            }

            if (!this.undershootAnalyzer.eventDetected) {
                const targetTolerance = Target.getAngularToleranceDeg(camera, targetPosition);
                this.undershootAnalyzer.detectUndershoots(this.movementData, targetTolerance);
            }
        }
    }

    /**
     * Returns current analysis results for hit/miss classification.
     * Call this after update() to check if overshoot/undershoot was detected
     * for the current target.
     */
    getResult(): AimAnalysisResult {
        return {
            hasOvershoot: this.overshootAnalyzer.eventDetected,
            hasUndershoot: this.undershootAnalyzer.eventDetected,
        };
    }

    /**
     * Resets analyzers, error axis, and movement buffer for a new target.
     */
    reset(): void {
        this.overshootAnalyzer.reset();
        this.undershootAnalyzer.reset();
        this.movementData = [];
        this.trackingStartTime = null;
        this.errorAxis = null;
    }
}
